/**
 * @file contract.cpp
 * @date 2026-08-18
 *
 * @license{LicenseRef-AWH-1.0}
 *
 * @author Yuriy Lobarev
 *
 * @brief Проверки согласия кодеков между собой — одна и та же запись подаётся всем
 *        владеющим значениям рамки, и договор извлечения обязан ответить на неё
 *        одинаково у каждого из них
 *
 * @details Проверки эти заведены оттого, что расхождение договора невидимо изнутри
 * кодека: набор всякого из них самодостаточен и проходит целиком, тогда как неправ из
 * них один. Так и вышло 18.08.2026 — разметка отвергала записи `1e400` и
 * `123456789012345678901234567890`, тогда как JSON и YAML извлекали из них
 * бесконечность и дробное приближение. Ни два захода аудита, ни ворошители, ни три дня
 * прогонов расхождения не показали: увидело его одно лишь сличение кодеков между собой
 *
 * @par Правило старшинства при столкновении согласия со стандартом
 *
 * @details Решение владельца от 03.09.2026, и оно старше всякого довода о согласии:
 * ПЕРВИЧЕН стандарт. Кодеки рамки обязаны нести общий набор ходов под общими именами,
 * однако там, где стандарт кодека требует от одноимённого хода СВОЕЙ логики, выбирается
 * логика стандарта, а не единообразие. Общее имя обязывает к общему ВОПРОСУ, а не к
 * общему ответу
 *
 * @details Отсюда следует и устройство проверок этого файла. Сличать надлежит ответы на
 * один и тот же вопрос, а расхождение ответов - разбирать доводом: вытекает ли оно из
 * стандарта либо из недосмотра. Первое закрепляется проверкой ВМЕСТЕ С ДОВОДОМ, чтобы
 * его не «привели к одному виду» те, кто довода не знал; второе чинится
 *
 * @note Примеры расхождений ЗАКОННЫХ, закреплённых здесь: запись пустого документа
 *       (RFC 8259 требует одного значения, XML 1.0 - одного корневого узла, а RFC 4180
 *       пустого файла не запрещает, оттого таблица отвечает успехом, а документ и
 *       разметка - отказом); разбор пустого текста по той же причине; отсутствие у
 *       таблицы обхода дерева и правки по пути, ибо модель её таблица, а не дерево
 *
 * @note Пример расхождения НЕЗАКОННОГО, исправленного: запись пустого дерева у JSON
 *       отдавала пустой текст с кодом «нет ошибки», тогда как запись того же дерева в
 *       файл отвечала отказом. Тут стандарт ничего не требовал - расходились два хода
 *       одного кодека, и это чинилось, а не закреплялось
 *
 * @warning ПРАВИЛО ДЛЯ ТЕХ, КТО СТАНЕТ ПИСАТЬ ПРОВЕРКИ ЗДЕСЬ. Случай подбирать так, чтобы
 * верное поведение и неверное давали РАЗНЫЙ ответ. Совпади они по постороннему
 * обстоятельству - и проверка будет зелена при живом отступлении, а зелень её неотличима
 * от исправности
 *
 * @warning Правило это выведено не из рассуждения, а из ТРЁХ осечек одного дня,
 * случившихся у трёх разных владельцев кодеков 03.09.2026:
 *
 * @warning 1. Щуп о звене пути клал поле «1» на место 1. «Нашло по ИМЕНИ» вышло
 * неотличимо от «взяло по МЕСТУ», щуп показал зелёное, а `at("m/1")` при том отдавал
 * чужое поле. Лечится обратной расстановкой: имя «1» на место 0, имя «0» на место 1
 *
 * @warning 2. Проверка о ведущем нуле брала перечень из ДВУХ значений. Путь `/01`
 * отвергался по ВЫХОДУ ЗА ПРЕДЕЛ, а не по ведущему нулю, и отступление жило под зелёной
 * проверкой. Лечится перечнем, заведомо ДЛИННЕЕ разбираемого номера, и вопросом о
 * достижимом номере ПЕРЕД вопросом об отвергаемом
 *
 * @warning 3. Проверка об установке журнала подменялась пустышкой и оставалась зелёной
 * дважды: она наблюдала за тем, чего при пустышке не происходит вовсе. Лечится
 * требованием, чтобы наблюдаемое ПРИШЛО, а не тем, что ничего не упало
 *
 * @warning Общее у всех трёх одно: проверка не била ни во что, а выглядела бьющей.
 * Оттого всякое утверждение здесь надлежит поверять ПОДМЕНОЙ - подделать именно то
 * поведение, какое утверждение отвергает, и убедиться, что проверка краснеет. Подмена,
 * не покрасившая проверку, означает, что проверка эта не о том
 *
 * @warning ВТОРОЕ ПРАВИЛО, О ДОВОДАХ. Довод, ссылающийся на согласие владельцев, обязан
 * назвать ПРОВЕРКУ, в какой согласие это закреплено. Ссылка на разговор - с датою ли, с
 * именами ли - доводом не является: перечитать её негде, а читающий примет её за
 * решённое и перепроверять не станет. Покуда проверки нет, довод излагается от
 * УСТРОЙСТВА либо от стандарта, а согласие поминается как намерение, не как основание
 *
 * @warning Правило это выведено из случая, где дата и имена НЕ ПОМОГЛИ. Примечание в
 * кодеке TOML гласило «согласовано с владельцами прочих кодеков рамки 03.09.2026»: дата
 * стояла, владельцы названы, - а согласовано было ОБРАТНОЕ, и отступление жило под
 * ссылкой на несуществующее решение. Назови довод проверку - её отсутствие открылось бы
 * ПРИ НАПИСАНИИ довода, а не при разборе месяцем позже
 *
 * @warning ТРЕТЬЕ ПРАВИЛО, О ПОСТРОЕНИИ. Проверка ПРАВКИ никогда не покрывает
 * ПОСТРОЕНИЯ: правка начинается с разобранного, построение - с пустоты, и путь у них
 * разный. Кодек, все проверки правки которого зелены, может не уметь построить документ
 * с нуля вовсе, и ни одна проверка правки того не покажет
 *
 * @warning Из отсутствия построения НЕ СЛЕДУЕТ недоделка, и это вторая половина правила,
 * без которой первая вредна. Дорог здесь четыре, и всякая есть решение: у ABC построение
 * есть дорога ГЛАВНАЯ - текста он не разбирает вовсе; у TOML оно есть наравне с разбором;
 * у YAML его нет НАМЕРЕННО - правка по пути требует дерева разобранного, ибо путь ведёт
 * от корня, а корня у пустого дерева нет; у INI его нет тоже. Оттого договор спрашивает
 * не «умеет ли кодек строить с нуля», а «если строит - то ПОЛНЫМ ЛИ КРУГОМ»: собрал,
 * записал, разобрал обратно, сличил. Сборка, отдающая запись, и запись, разбору
 * подлежащая, суть разные свойства, и порок виден только кругом
 *
 * @warning Половина эта дописана 03.09.2026 по следам случая, где отсутствие построения
 * приняли за дыру - и правка, дыру эту «чинившая», уронила проверки, стерегущие решение.
 * Покраснели они ВЕРНО. Прежде чем звать отсутствующую дорогу недоделкой, надлежит
 * спросить владельца, не заперта ли она намеренно - см. второе правило, о доводах
 *
 * @warning ЧЕТВЁРТОЕ ПРАВИЛО, О ПОДМЕНАХ. Подменять надлежит КАЖДОЕ утверждение довода
 * порознь, а не то, что кажется в нём главным, - и в том числе то, что кажется заведомо
 * верным. Именно в заведомо верном и сидят подмены безвредные, какие мы принимаем за
 * покрытие: место, где всякая порча проходит незамеченной, выглядит ровно как место,
 * где всё исправно
 *
 * @warning Случаев, из каких правило это выведено, за два дня набралось пять, и все они
 * одной породы - довод шире проверенного: три раза утверждение стояло в доводе, а
 * проверки под ним не было вовсе; раз проверка сличала нуль с нулём, ибо сборщик образца
 * поля не трогал; раз след разбора не нёс места, и сдвиг его был проверке невидим. Общее
 * у пяти одно: ПРОВЕРКА, ПИСАННАЯ ПОД ГОТОВОЕ ПОВЕДЕНИЕ, СКЛОННА ПРИНИМАТЬ ЕГО ФОРМУ, А
 * НЕ СТЕРЕЧЬ ЕГО СУТЬ
 *
 * @warning ОГОВОРКА К ЧЕТВЁРТОМУ ПРАВИЛУ, БЕЗ КОТОРОЙ ОНО САМО СТАНОВИТСЯ ЛОВУШКОЙ.
 * «Место живо» доказывается двумя разными способами, и путать их нельзя: ЩУПОМ - исход
 * меняется, значит место работает, и молчание проверки есть её слепота; РАЗБОРОМ
 * УСТРОЙСТВА - исход НЕ меняется, и тогда надлежит искать, кто держит договор вместо
 * этого места. Оттого безвредная подмена есть находка сама по себе: она говорит либо
 * «проверка слепа», либо «договор держит не это место», и различить их можно только
 * разбором, а не повторной подменой. Покуда не различил - не докладывай ни того, ни
 * другого
 *
 * @warning Пример разбора, а не повторной подмены. Перебор постоянных вида записи ABC
 * сдвигом на единицу дал: SPAN_LENGTH - две покрасневших проверки, TIME_WIDTH - шесть,
 * UUID_WIDTH и MAX_NODES - по восьми, INLINE_LIMIT - восемь, а INDEX_THRESHOLD - НУЛЬ.
 * Разбор показал второе из двух: порог этот есть решение о РАСХОДЕ - до него розыск идёт
 * перебором, с него строится указатель имён, - и обе дороги отвечают одно ПО УСТРОЙСТВУ,
 * оттого сдвиг его и безвреден. Дырою же было отсутствие проверки на СОГЛАСИЕ дорог,
 * закрытое проверкою LookupAgreesOnBothSidesOfTheIndexThreshold
 *
 * @copyright Copyright © 2026
 */

/**
 * Стандартные заголовочные файлы
 */
#include <cmath>
#include <string>
#include <vector>
#include <cstdio>
#include <csignal>
#include <fstream>
#include <sstream>
#include <functional>
#include <sys/resource.h>

/**
 * Подключаем заголовочные файлы проекта
 */
#include <gtest/gtest.h>
#include <codec/json/json.hpp>
#include <codec/csv/csv.hpp>
#include <codec/xml/xml.hpp>
#include <codec/yaml/yaml.hpp>
#include <codec/toml/toml.hpp>
#include <codec/ini/ini.hpp>
#include <codec/abc/abc.hpp>
#include <sys/log.hpp>

/**
 * @brief Пространство имён проверок этого файла
 *
 * @note Держится оно безымянным намеренно: проверки кодеков собираются одной
 *       программою, и одноимённые построения разных файлов иначе сходятся в
 *       одно, порождая порчу вдали от места её причины
 *
 */
namespace {
	/**
	 * @brief Объект журнала проверок с отключённым выводом
	 *
	 * @details Вывод отключается назначением пустого перечня приёмников: отказы
	 *          разбора проверки наводят намеренно, и журнал их засорял бы выдачу
	 *
	 */
	struct Silent {
		/**
		 * @brief Функция получения объекта фреймворка проверок
		 *
		 * @details Объект заводится статикою местною, а не общею файла: заведение его
		 *          порядком построения статики оканчивается падением ещё до входа в
		 *          проверки, ибо фреймворк сам опирается на статику из библиотеки
		 *
		 * @return объект фреймворка проверок
		 *
		 */
		static const awh::fmk_t & framework() noexcept {
			// Объект фреймворка проверок
			static awh::fmk_t fmk;
			// Выводим объект фреймворка проверок
			return fmk;
		}
		// Объект журнала проверок
		awh::log_t log;
		/**
		 * @brief Конструктор
		 *
		 */
		Silent() noexcept : log(&Silent::framework()) {
			// Выполняем отключение вывода логов
			this->log.mode({});
		}
	};
	/**
	 * @brief Функция получения объекта журнала проверок
	 *
	 * @return объект журнала проверок
	 *
	 */
	const awh::log_t * logger() noexcept {
		// Объект журнала проверок
		static Silent silent;
		// Выводим объект журнала проверок
		return &silent.log;
	}
}

/**
 * Используем стандартное пространство имён
 */
using namespace std;
using namespace awh;
using namespace awh::codec;

/**
 * @brief Безымянное пространство имён вспомогательных объявлений проверок
 *
 * @note Пространство это безымянно намеренно: проверки всех кодеков собираются одной
 *       программой, и вынесенное наружу имя столкнулось бы с таким же именем соседа
 *
 */
namespace {
	/**
	 * @brief Итог извлечения числа из записи
	 *
	 */
	struct outcome_t {
		bool extracted;   // Признак успешности извлечения
		double real;      // Извлечённое дробное число
		bool wholed;      // Признак успешности извлечения целого числа
		int64_t whole;    // Извлечённое целое число со знаком
		/**
		 * @brief Конструктор
		 *
		 */
		outcome_t() noexcept : extracted(false), real(0.), wholed(false), whole(0) {}
	};
	/**
	 * @brief Метод сличения двух итогов извлечения
	 *
	 * @details Бесконечности сличаются признаком, а не равенством: равенства
	 * бесконечностей язык не обещает, тогда как договор велит им совпасть
	 *
	 * @param left  первый сличаемый итог
	 * @param right второй сличаемый итог
	 * @return      признак совпадения итогов
	 *
	 */
	static bool same(const outcome_t & left, const outcome_t & right) noexcept {
		/**
		 * Если признаки успешности извлечения разнятся
		 */
		if((left.extracted != right.extracted) || (left.wholed != right.wholed))
			// Выводим признак несовпадения итогов
			return false;
		/**
		 * Если извлечение записи числом дробным не удалось у обоих
		 */
		if(!left.extracted)
			// Выводим признак совпадения итогов
			return true;
		/**
		 * Если извлечённые дробные числа бесконечны у обоих
		 */
		if(::std::isinf(left.real) && ::std::isinf(right.real)){
			/**
			 * Если знаки бесконечностей разнятся
			 */
			if(::std::signbit(left.real) != ::std::signbit(right.real))
				// Выводим признак несовпадения итогов
				return false;
		/**
		 * Если извлечённые дробные числа бесконечны не у обоих
		 */
		} else if(left.real != right.real)
			// Выводим признак несовпадения итогов
			return false;
		// Выводим признак совпадения извлечённых целых чисел
		return (!left.wholed || (left.whole == right.whole));
	}
	/**
	 * @brief Метод извлечения числа из записи кодеком JSON
	 *
	 * @param record  подаваемая запись числа
	 * @param outcome собираемый итог извлечения
	 * @return        признак того, что запись кодеком разобрана
	 *
	 */
	static bool viaJson(const string & record, outcome_t & outcome) noexcept {
		// Дерево документа JSON
		json::document_t document(::logger());
		/**
		 * Если разбор записи завершился отказом
		 */
		if(!document.parse(record))
			// Выводим признак того, что запись кодеком не разобрана
			return false;
		// Снятое с дерева документа владеющее значение
		const json::value_t value(document.root());
		// Выполняем извлечение записи числом дробным
		outcome.extracted = value.value(outcome.real);
		// Выполняем извлечение записи числом целым
		outcome.wholed = value.value(outcome.whole);
		// Выводим признак того, что запись кодеком разобрана
		return true;
	}
	/**
	 * @brief Метод извлечения числа из записи кодеком CSV
	 *
	 * @details Кодек этот в сличение включён с 01.09.2026: прежде договор извлечения у
	 * него был свой - отказ там, где число теряется, - и сличать его с прочими было
	 * незачем. Решением владельца он приведён к общему договору рамки, и с той поры
	 * расходиться ему с соседями нечем
	 *
	 * @note Своих видов у таблицы нет вовсе: запись кладётся полем, и вид её решается
	 *       самой записью при извлечении - ровно как у разметки
	 *
	 * @param record  подаваемая запись числа
	 * @param outcome собираемый итог извлечения
	 * @return        признак того, что запись кодеком разобрана
	 *
	 */
	static bool viaCsv(const string & record, outcome_t & outcome) noexcept {
		// Настройки контейнера таблицы
		csv::document_t::settings_t settings;
		// Отключаем ожидание заголовка
		settings.reader.header = csv::header_t::NONE;
		// Дерево таблицы CSV
		csv::document_t document(::logger(), settings);
		/**
		 * Если разбор записи завершился отказом
		 */
		if(!document.parse(record + "\r\n"))
			// Выводим признак того, что запись кодеком не разобрана
			return false;
		// Выполняем извлечение записи числом дробным
		outcome.extracted = document.numeric(0, size_t(0), outcome.real);
		// Выполняем извлечение записи числом целым
		outcome.wholed = document.numeric(0, size_t(0), outcome.whole);
		// Выводим признак того, что запись кодеком разобрана
		return true;
	}
	/**
	 * @brief Метод извлечения числа из записи кодеком XML
	 *
	 * @note Своих видов у разметки нет вовсе: запись кладётся содержимым узла, и
	 *       вид её решается самой записью при извлечении
	 *
	 * @param record  подаваемая запись числа
	 * @param outcome собираемый итог извлечения
	 * @return        признак того, что запись кодеком разобрана
	 *
	 */
	static bool viaXml(const string & record, outcome_t & outcome) noexcept {
		// Собираемый текст разметки
		const string text = ("<a>" + record + "</a>");
		// Дерево разметки XML
		xml::document_t document(::logger());
		/**
		 * Если разбор записи завершился отказом
		 */
		if(!document.parse(text))
			// Выводим признак того, что запись кодеком не разобрана
			return false;
		// Снятое с дерева разметки владеющее значение
		const xml::value_t value(document.element());
		// Выполняем извлечение записи числом дробным
		outcome.extracted = value.value(outcome.real);
		// Выполняем извлечение записи числом целым
		outcome.wholed = value.value(outcome.whole);
		// Выводим признак того, что запись кодеком разобрана
		return true;
	}
	/**
	 * @brief Метод извлечения числа из записи кодеком YAML
	 *
	 * @param record  подаваемая запись числа
	 * @param outcome собираемый итог извлечения
	 * @return        признак того, что запись кодеком разобрана
	 *
	 */
	static bool viaYaml(const string & record, outcome_t & outcome) noexcept {
		// Собираемый текст документа
		const string text = ("value: " + record + "\n");
		// Дерево документа YAML
		yaml::document_t document(::logger());
		/**
		 * Если разбор записи завершился отказом
		 */
		if(!document.parse(text))
			// Выводим признак того, что запись кодеком не разобрана
			return false;
		// Снятое с дерева документа владеющее значение
		const yaml::value_t value(document.root());
		// Выполняем извлечение записи числом дробным
		outcome.extracted = value.at("/value").value(outcome.real);
		// Выполняем извлечение записи числом целым
		outcome.wholed = value.at("/value").value(outcome.whole);
		// Выводим признак того, что запись кодеком разобрана
		return true;
	}
	/**
	 * @brief Метод извлечения числа из записи кодеком TOML
	 *
	 * @details Владеющего значения у кодека этого ещё нет, и договор извлечения берётся
	 * прямо у дерева документа. Разницы для щупа в том нет: договор один и тот же, а
	 * владеющее значение к нему лишь пристраивается - переносится он сюда целиком, и
	 * расхождение обязано всплыть здесь ещё до переноса, а не сличением задним числом
	 *
	 * @note Переставить кодек на владеющее значение надлежит вместе с переносом его:
	 *       щуп сличает договор, а не путь до него
	 *
	 * @param record  подаваемая запись числа
	 * @param outcome собираемый итог извлечения
	 * @return        признак того, что запись кодеком разобрана
	 *
	 */
	static bool viaToml(const string & record, outcome_t & outcome) noexcept {
		// Собираемый текст документа
		const string text = ("value = " + record + "\n");
		// Дерево документа TOML
		toml::document_t document(::logger());
		/**
		 * Если разбор записи завершился отказом
		 */
		if(!document.parse(text))
			// Выводим признак того, что запись кодеком не разобрана
			return false;
		// Составное имя искомой пары
		const vector <string_view> path = {"value"};
		// Выполняем извлечение записи числом дробным
		outcome.extracted = document.value(outcome.real, path);
		// Выполняем извлечение записи числом целым
		outcome.wholed = document.value(outcome.whole, path);
		// Выводим признак того, что запись кодеком разобрана
		return true;
	}
	/**
	 * @brief Метод извлечения числа из записи кодеком INI
	 *
	 * @note Своих видов у кодека нет вовсе: значение свойства есть запись, и вид её
	 *       решается самой записью при извлечении - ровно как у разметки
	 *
	 * @param record  подаваемая запись числа
	 * @param outcome собираемый итог извлечения
	 * @return        признак того, что запись кодеком разобрана
	 *
	 */
	static bool viaIni(const string & record, outcome_t & outcome) noexcept {
		// Собираемый текст настроек
		const string text = ("value=" + record + "\n");
		// Дерево настроек INI
		ini::document_t document(::logger());
		/**
		 * Если разбор записи завершился отказом
		 */
		if(!document.parse(text))
			// Выводим признак того, что запись кодеком не разобрана
			return false;
		// Выполняем извлечение записи числом дробным
		outcome.extracted = document.value(outcome.real, "value");
		// Выполняем извлечение записи числом целым
		outcome.wholed = document.value(outcome.whole, "value");
		// Выводим признак того, что запись кодеком разобрана
		return true;
	}
};

/**
 * @brief Проверка согласия договора извлечения у кодеков рамки
 *
 * @details Всякая запись подаётся кодекам JSON, XML и YAML, и итоги извлечения из неё
 *          сличаются между собой. Кодек, записи не разобравший вовсе, из сличения
 *          выбывает: разбор — дело договора своего у всякого кодека, а сличается здесь
 *          один лишь договор извлечения, общий у них по устройству
 *
 * @note Записи взяты по краям видов: за пределом дробного и мельче наименьшего его, за
 *       пределом целого обоих знаков, ровно на пределе, а также обычные числа - ими
 *       проверяется, что сличение не пропускает всё подряд
 *
 * @note ABC в переборе этом НЕ участвует, и это не пропуск. Подаётся здесь ТЕКСТ, а
 *       разбора текста у ABC не заведено вовсе: число приходит к нему уже видом своим,
 *       уложенным в октеты, и извлекать его из написания нечего. Внеси его сюда - и
 *       пришлось бы завести ему разбор текста ради одной лишь проверки, то есть
 *       подогнать устройство под проверку, а не наоборот
 *
 */
TEST(CodecContract, NumberExtraction) {
	// Перечень записей, подаваемых кодекам
	const vector <string> records = {
		"0", "1", "-1", "1.5", "-1.5", "0.0", "1e3", "1E3", "1e-3",
		"9223372036854775807", "-9223372036854775808",
		"18446744073709551615", "18446744073709551616",
		"123456789012345678901234567890", "-123456789012345678901234567890",
		"1e400", "-1e400", "1e-400", "1.7976931348623157e309",
		"0.1234567890123456789012345678901234567890"
	};
	// Перечень кодеков, чьи договоры сличаются
	const vector <pair <string, function <bool (const string &, outcome_t &)>>> codecs = {
		{"JSON", viaJson}, {"XML", viaXml}, {"YAML", viaYaml},
		{"TOML", viaToml}, {"INI", viaIni}, {"CSV", viaCsv}
	};
	/**
	 * Выполняем перебор всех подаваемых записей
	 */
	for(auto & record : records){
		// Название кодека, чей итог взят образцом
		string origin;
		// Итог извлечения, взятый образцом сличения
		outcome_t sample;
		// Признак того, что образец сличения снят
		bool sampled = false;
		/**
		 * Выполняем перебор всех сличаемых кодеков
		 */
		for(auto & codec : codecs){
			// Собираемый итог извлечения очередного кодека
			outcome_t outcome;
			/**
			 * Если запись кодеком не разобрана вовсе
			 */
			if(!codec.second(record, outcome))
				// Выполняем переход к следующему кодеку
				continue;
			/**
			 * Если образец сличения ещё не снят
			 */
			if(!sampled){
				// Запоминаем снятый образец сличения
				sample = outcome;
				// Запоминаем название кодека, чей итог взят образцом
				origin = codec.first;
				// Запоминаем, что образец сличения снят
				sampled = true;
				// Выполняем переход к следующему кодеку
				continue;
			}
			/**
			 * Выполняем проверку совпадения итога извлечения с образцом
			 *
			 * @note Сообщение печатает ОБА извлечения - и дробное, и целое: сличаются они
			 *       оба, а расходиться вправе одно. Печатая одно дробное, сообщение
			 *       читалось «JSON даёт 1.5, а TOML даёт 1.5» и уводило от причины прочь
			 */
			ASSERT_TRUE(same(sample, outcome))
				<< "запись [" << record << "] извлекается кодеками по-разному: "
				<< origin << " даёт дробным " << (sample.extracted ? "" : "отказ ") << sample.real
				<< " и целым " << (sample.wholed ? "" : "отказ ") << sample.whole
				<< ", а " << codec.first << " даёт дробным " << (outcome.extracted ? "" : "отказ ") << outcome.real
				<< " и целым " << (outcome.wholed ? "" : "отказ ") << outcome.whole;
		}
		// Выполняем проверку того, что запись разобрана хоть одним кодеком
		ASSERT_TRUE(sampled) << "запись [" << record << "] не разобрана ни одним кодеком";
	}
}

/**
 * @brief Проверка согласия кодеков в отказе записям, числами не являющимся
 *
 * @details Запись, числом не являющаяся, обязана отвергаться извлечением у всякого
 *          кодека, её разобравшего. Проверка эта держит вторую сторону договора: свести
 *          кодеки к согласию можно и дозволив им всё подряд, и тогда сличение итогов
 *          проходило бы, ничего не проверяя
 *
 * @note ABC в переборе этом НЕ участвует, и это не пропуск. Подаётся здесь ТЕКСТ, а
 *       разбора текста у ABC не заведено вовсе: число приходит к нему уже видом своим,
 *       уложенным в октеты, и извлекать его из написания нечего. Внеси его сюда - и
 *       пришлось бы завести ему разбор текста ради одной лишь проверки, то есть
 *       подогнать устройство под проверку, а не наоборот
 *
 */
TEST(CodecContract, NumberRefusal) {
	/**
	 * Перечень записей, числами не являющихся ни по одному из стандартов
	 *
	 * @note Записи `0b101` и `nan` из перечня этого изъяты: описание TOML знает их
	 *       числами - двоичным целым и нечислом дробным, - и держатся они ниже, среди
	 *       расхождений, стандартами заданных. Перечень этот писался, когда кодека
	 *       TOML в щупе не было, и был он верен ровно до внесения его
	 */
	const vector <string> records = {
		"текст", "12abc", "abc12", "1e", "--5", "5.5.5"
	};
	// Перечень кодеков, чьи договоры сличаются
	const vector <pair <string, function <bool (const string &, outcome_t &)>>> codecs = {
		{"JSON", viaJson}, {"XML", viaXml}, {"YAML", viaYaml},
		{"TOML", viaToml}, {"INI", viaIni}, {"CSV", viaCsv}
	};
	/**
	 * Выполняем перебор всех подаваемых записей
	 */
	for(auto & record : records){
		/**
		 * Выполняем перебор всех сличаемых кодеков
		 */
		for(auto & codec : codecs){
			// Собираемый итог извлечения очередного кодека
			outcome_t outcome;
			/**
			 * Если запись кодеком не разобрана вовсе
			 */
			if(!codec.second(record, outcome))
				// Выполняем переход к следующему кодеку
				continue;
			// Выполняем проверку того, что запись числом не извлекается
			ASSERT_FALSE(outcome.extracted)
				<< "запись [" << record << "] числом не является, а кодек " << codec.first
				<< " извлёк из неё " << outcome.real;
		}
	}
}

/**
 * @brief Проверка расхождений кодеков, стандартами их заданных
 *
 * @details Согласие договора извлечения не означает согласия в том, ЧТО СЧИТАТЬ ЧИСЛОМ:
 *          это решает стандарт всякого кодека, и решает по-разному. YAML знает записи
 *          шестнадцатеричные и восьмеричные, знак плюса и `.inf`; JSON не знает ни
 *          одной из них и отвергает такую запись ещё разбором; разметка своих видов не
 *          имеет вовсе, оттого запись `.5` ей годится наравне с `0.5`, как годится она
 *          и описанию видов XSD
 *
 * @note Проверка эта заведена НЕ ради согласия, а ради несогласия: сведи кто-нибудь
 *       кодеки к одному виду записи ради стройности - и стандарты окажутся нарушены.
 *       Расхождения эти намеренны, и проверка их закрепляет
 *
 * @note ABC в переборе этом НЕ участвует, и это не пропуск. Подаётся здесь ТЕКСТ, а
 *       разбора текста у ABC не заведено вовсе: число приходит к нему уже видом своим,
 *       уложенным в октеты, и извлекать его из написания нечего. Внеси его сюда - и
 *       пришлось бы завести ему разбор текста ради одной лишь проверки, то есть
 *       подогнать устройство под проверку, а не наоборот
 *
 */
TEST(CodecContract, StandardDivergence) {
	// Собираемый итог извлечения
	outcome_t outcome;
	/**
	 * Выполняем перебор записей, числами являющихся у одного лишь YAML
	 *
	 * @note Записи эти заданы стандартом YAML: шестнадцатеричная, восьмеричная, знак
	 *       плюса и бесконечность
	 */
	for(auto & item : vector <pair <string, double>> {{"0x10", 16.}, {"0o17", 15.}, {"+5", 5.}}){
		// Собираемый итог извлечения кодеком YAML
		outcome_t taken;
		// Выполняем проверку того, что запись кодеком YAML разобрана и извлечена
		ASSERT_TRUE(viaYaml(item.first, taken)) << "запись [" << item.first << "]";
		ASSERT_TRUE(taken.extracted) << "запись [" << item.first << "]";
		ASSERT_DOUBLE_EQ(taken.real, item.second);
		// Выполняем проверку того, что кодек JSON записи такой не разбирает вовсе
		ASSERT_FALSE(viaJson(item.first, outcome)) << "запись [" << item.first << "]";
	}
	// Собираемый итог извлечения записи бесконечности
	outcome_t boundless;
	// Выполняем проверку того, что кодек YAML знает запись бесконечности
	ASSERT_TRUE(viaYaml(".inf", boundless));
	ASSERT_TRUE(boundless.extracted);
	ASSERT_TRUE(::std::isinf(boundless.real));
	/**
	 * Выполняем перебор записей, числами являющихся у разметки и у YAML
	 *
	 * @note Записи эти стандарт JSON отвергает разбором: цифра перед точкой и после неё
	 *       обязательна у него, тогда как описание видов XSD такие записи дозволяет
	 */
	for(auto & item : vector <pair <string, double>> {{".5", 0.5}, {"5.", 5.}}){
		// Собираемый итог извлечения кодеком XML
		outcome_t taken;
		// Выполняем проверку того, что запись разметкой извлекается
		ASSERT_TRUE(viaXml(item.first, taken)) << "запись [" << item.first << "]";
		ASSERT_TRUE(taken.extracted) << "запись [" << item.first << "]";
		ASSERT_DOUBLE_EQ(taken.real, item.second);
		// Выполняем проверку того, что кодек JSON записи такой не разбирает вовсе
		ASSERT_FALSE(viaJson(item.first, outcome)) << "запись [" << item.first << "]";
	}
	/**
	 * Выполняем перебор записей, числами являющихся у одного лишь TOML
	 *
	 * @note Записи эти заданы описанием TOML 1.0.0: двоичное целое, разделитель разрядов
	 *       подчёркиванием и нечисло дробное. Прочие кодеки числами их не считают -
	 *       разметка и INI отвергают их извлечением, JSON отвергает разбором
	 */
	for(auto & item : vector <pair <string, double>> {{"0b101", 5.}, {"1_000", 1000.}}){
		// Собираемый итог извлечения кодеком TOML
		outcome_t taken;
		// Выполняем проверку того, что запись кодеком TOML разобрана и извлечена
		ASSERT_TRUE(viaToml(item.first, taken)) << "запись [" << item.first << "]";
		ASSERT_TRUE(taken.extracted) << "запись [" << item.first << "]";
		ASSERT_DOUBLE_EQ(taken.real, item.second);
		// Собираемый итог извлечения кодеком INI
		outcome_t missed;
		// Выполняем проверку того, что кодек INI записи такой числом не считает
		ASSERT_TRUE(viaIni(item.first, missed)) << "запись [" << item.first << "]";
		ASSERT_FALSE(missed.extracted) << "запись [" << item.first << "]";
	}
	// Собираемый итог извлечения записи нечисла кодеком TOML
	outcome_t senseless;
	/**
	 * Выполняем проверку того, что кодек TOML знает запись нечисла
	 *
	 * @note Написание у TOML своё: `nan` без точки, тогда как YAML пишет его `.nan`.
	 *       Извлечение выдаёт нечисло, а обращение его нулём есть дело сужения вида, а
	 *       не извлечения
	 */
	ASSERT_TRUE(viaToml("nan", senseless));
	ASSERT_TRUE(senseless.extracted);
	ASSERT_TRUE(::std::isnan(senseless.real));
}
/**
 * @brief Проверка длинной записи числа
 *
 * @details Длина записи числа - расхождение, заданное стандартами, и свести кодеки к
 *          одному пределу здесь значило бы нарушить два описания из трёх. Описания
 *          XML и YAML длину записи числа не ограничивают ничем, и предел отверг бы
 *          законный документ; описание JSON её тоже не ограничивает, но у кодека
 *          предел записи стоит и в чтении, и в письме разом, оттого договор внутри
 *          него цел, а отказ правомерен
 *
 * @note Держатся здесь ТРИ вещи, а не две: разбор, дословное удержание записи и
 *       СБОРКА ТЕКСТА ЗАНОВО. Различие существенно: предел записи числа сказался бы
 *       ровно на сборке, тогда как удержание прошло бы и с пределом - вырезая запись
 *       из исходного текста. Проверка, держащая одно лишь удержание, доказала бы не то
 *
 * @warning Одинок здесь JSON, и одинок правомерно. Стоит его пределу разойтись между
 *          чтением и письмом - и кодек станет принимать то, чего не умеет записать;
 *          такое расхождение задано уже не стандартом, а небрежностью
 *
 * @note ABC в переборе этом НЕ участвует, и это не пропуск. Подаётся здесь ТЕКСТ, а
 *       разбора текста у ABC не заведено вовсе: число приходит к нему уже видом своим,
 *       уложенным в октеты, и извлекать его из написания нечего. Внеси его сюда - и
 *       пришлось бы завести ему разбор текста ради одной лишь проверки, то есть
 *       подогнать устройство под проверку, а не наоборот
 *
 */
TEST(CodecContract, LongNumberRecord) {
	// Собираемая запись числа в две тысячи разрядов
	string digits(1, '1');
	// Выполняем добавление недостающих разрядов записи числа
	digits.append(1999, '0');
	// Объект владеющего значения разметки
	xml::value_t markup;
	// Выполняем проверку разбора длинной записи числа кодеком XML
	ASSERT_TRUE(markup.parse("<a>" + digits + "</a>"));
	// Выполняем проверку дословного удержания записи числа
	ASSERT_EQ(markup[static_cast <size_t> (0)].text(), digits);
	// Выполняем проверку сборки текста заново без потери разрядов
	ASSERT_EQ(markup.dump(), "<a>" + digits + "</a>");
	// Объект владеющего значения YAML
	yaml::value_t staged;
	// Выполняем проверку разбора длинной записи числа кодеком YAML
	ASSERT_TRUE(staged.parse("value: " + digits + "\n"));
	// Выполняем проверку того, что собранный заново текст запись числа сохранил
	ASSERT_NE(staged.dump().find(digits), string::npos) << staged.dump();
	// Объект владеющего значения JSON
	json::value_t plain;
	// Выполняем проверку отказа разбора длинной записи числа кодеком JSON
	ASSERT_FALSE(plain.parse("[" + digits + "]"));
	/**
	 * Выполняем проверку согласия чтения и письма у кодека JSON
	 *
	 * @note Запись, принятая чтением, обязана записываться письмом обратно: предел у
	 *       них один, и разойтись они не вправе. Сличается запись длиной на единицу
	 *       меньше предела - самая длинная из принимаемых
	 */
	string shorter(1, '1');
	// Выполняем добавление недостающих разрядов допустимой записи числа
	shorter.append(json::MAX_NUMBER - 2, '0');
	// Объект владеющего значения JSON под допустимую запись
	json::value_t accepted;
	// Выполняем проверку разбора допустимой записи числа
	ASSERT_TRUE(accepted.parse("[" + shorter + "]")) << shorter.size();
	// Выполняем проверку дословного удержания допустимой записи числа
	ASSERT_EQ(accepted[static_cast <size_t> (0)].raw(), shorter);
	// Выполняем проверку сборки текста заново без потери разрядов
	ASSERT_EQ(accepted.dump(), "[" + shorter + "]");
	/**
	 * Выполняем закрепление дословного удержания у владеющего значения таблицы
	 *
	 * @details Поле таблицы есть последовательность знаков, и своих видов числа у
	 *          наречия нет вовсе - оттого длинная запись обязана удерживаться
	 *          ДОСЛОВНО, а разбор её видом языка идти лишь при извлечении
	 *
	 * @warning Порок обратного устройства молчалив: разбери таблица запись числом
	 * при чтении, и две тысячи разрядов легли бы в дробное двойной точности,
	 * сохранившее верными лишь семнадцать. Текст собрался бы заново, круг сошёлся
	 * бы по виду, а разряды пропали бы без отказа и без знака
	 */
	{
		// Объект таблицы
		csv::document_t doc(::logger());
		// Выполняем проверку разбора длинной записи числа кодеком CSV
		ASSERT_TRUE(doc.parse(digits + "\r\n"));
		// Владеющее значение, снятое с таблицы
		const csv::value_t table(doc);
		// Выполняем проверку дословного удержания записи числа
		ASSERT_EQ(table.at("/0/0").text(), digits);
		// Выполняем проверку сборки текста заново без потери разрядов
		ASSERT_EQ(table.dump(), digits + "\r\n");
	}
}
/**
 * @brief Проверка договора о сужении числа у трёх кодеков разом
 *
 * @details Правил здесь два, и разные они не по небрежности, а потому что разные
 *          случаи: целое, не помещающееся в узкий вид, ЗАВОРАЧИВАЕТСЯ приведением
 *          языка - приведение это языком определено, и выдумывать поверх него нечего;
 *          дробное же за пределом целого вида ОГРАНИВАЕТСЯ пределом - там приведение
 *          языком не определено вовсе, и огранение заведено по необходимости
 *
 * @note Держится это порознь в наборе всякого кодека, но порознь оно и разойтись
 *       может: расхождение изнутри одного кодека невидимо. Здесь сличается одна
 *       запись через все кодеки разом
 *
 * @warning Огранение сличается ОБОИМИ краями. Проверка одного лишь верхнего прошла бы
 *          и при нижнем крае, забытом вовсе, - а забытый край это уже неопределённое
 *          поведение, ради изгнания которого огранение и заведено
 *
 */
TEST(CodecContract, Narrowing) {
	// Извлекаемое число видом в один байт без знака
	uint8_t byte = 0;
	// Извлекаемое целое значение
	int32_t number = 0;
	// Объект владеющего значения JSON
	json::value_t plain;
	// Выполняем разбор записей, подлежащих сужению
	ASSERT_TRUE(plain.parse("[8080,1e300,-1e300]"));
	// Выполняем проверку заворота целого числа кодеком JSON
	ASSERT_TRUE(plain[static_cast <size_t> (0)].value(byte));
	ASSERT_EQ(byte, static_cast <uint8_t> (8080));
	// Выполняем проверку огранения дробного числа верхним пределом
	ASSERT_TRUE(plain[static_cast <size_t> (1)].value(number));
	ASSERT_EQ(number, ::std::numeric_limits <int32_t>::max());
	// Выполняем проверку огранения дробного числа нижним пределом
	ASSERT_TRUE(plain[static_cast <size_t> (2)].value(number));
	ASSERT_EQ(number, ::std::numeric_limits <int32_t>::lowest());
	// Объект владеющего значения разметки
	xml::value_t markup;
	// Выполняем разбор записей, подлежащих сужению
	ASSERT_TRUE(markup.parse("<a><b>8080</b><b>1e300</b><b>-1e300</b></a>"));
	// Получаем корневой узел разобранной разметки
	const xml::value_t & root = markup[static_cast <size_t> (0)];
	// Выполняем проверку заворота целого числа кодеком XML
	ASSERT_TRUE(root[static_cast <size_t> (0)].value(byte));
	ASSERT_EQ(byte, static_cast <uint8_t> (8080));
	// Выполняем проверку огранения дробного числа верхним пределом
	ASSERT_TRUE(root[static_cast <size_t> (1)].value(number));
	ASSERT_EQ(number, ::std::numeric_limits <int32_t>::max());
	// Выполняем проверку огранения дробного числа нижним пределом
	ASSERT_TRUE(root[static_cast <size_t> (2)].value(number));
	ASSERT_EQ(number, ::std::numeric_limits <int32_t>::lowest());
	// Объект владеющего значения YAML
	yaml::value_t staged;
	// Выполняем разбор записей, подлежащих сужению
	ASSERT_TRUE(staged.parse("- 8080\n- 1e300\n- -1e300\n"));
	// Выполняем проверку заворота целого числа кодеком YAML
	ASSERT_TRUE(staged[static_cast <size_t> (0)].value(byte));
	ASSERT_EQ(byte, static_cast <uint8_t> (8080));
	// Выполняем проверку огранения дробного числа верхним пределом
	ASSERT_TRUE(staged[static_cast <size_t> (1)].value(number));
	ASSERT_EQ(number, ::std::numeric_limits <int32_t>::max());
	// Выполняем проверку огранения дробного числа нижним пределом
	ASSERT_TRUE(staged[static_cast <size_t> (2)].value(number));
	ASSERT_EQ(number, ::std::numeric_limits <int32_t>::lowest());
	/**
	 * Огранение дробного числа у кодека ABC
	 *
	 * @note Заворота целого здесь нет, и это не упущение проверки: у ABC извлечение
	 *       узких видов не заведено вовсе - договор его знает лишь `int64_t`, `uint64_t`
	 *       и `double`, - оттого заворачивать нечего. Огранение же дробного за пределом
	 *       целого у него есть, и держится оно тем же правилом, что у прочих
	 * @note Пределы здесь взяты от `int64_t`, а не от `int32_t`: сличается ПРАВИЛО
	 *       огранения, а не ширина вида, и ширину всякий кодек берёт свою
	 */
	// Извлекаемое целое значение видом в восемь байт
	int64_t wide = 0;
	// Извлекаемое целое значение видом в восемь байт без знака
	uint64_t unsigned_wide = 0;
	// Выполняем проверку огранения дробного числа верхним пределом
	ASSERT_TRUE(abc::value_t(1e300).value(wide));
	ASSERT_EQ(wide, ::std::numeric_limits <int64_t>::max());
	// Выполняем проверку огранения дробного числа нижним пределом
	ASSERT_TRUE(abc::value_t(-1e300).value(wide));
	ASSERT_EQ(wide, ::std::numeric_limits <int64_t>::lowest());
	/**
	 * Выполняем проверку огранения дробного числа видом беззнаковым
	 *
	 * @warning Нижний край у вида беззнакового это НУЛЬ, а не отрицательное число:
	 *          огранение, взявшее пределы у знакового вида, дало бы здесь заворот в
	 *          огромное положительное, и был бы он неотличим от законного числа
	 */
	ASSERT_TRUE(abc::value_t(1e300).value(unsigned_wide));
	ASSERT_EQ(unsigned_wide, ::std::numeric_limits <uint64_t>::max());
	ASSERT_TRUE(abc::value_t(-1e300).value(unsigned_wide));
	ASSERT_EQ(unsigned_wide, static_cast <uint64_t> (0));
	/**
	 * Выполняем закрепление того же уклада у владеющего значения таблицы
	 *
	 * @details Значение таблицы завелось позже прочих, и ряд извлечений у него
	 *          поначалу был короче: пять видов против двенадцати. Потребитель,
	 *          переносящий разбор с документа на таблицу, упирался бы в
	 *          отсутствие узких видов, а завёл бы их кто-нибудь наскоро - уклад
	 *          сужения разошёлся бы у краёв вида, где его никто не ищет
	 *
	 * @note Сужение у таблицы ведётся тем же общим ходом рамки `awh::codec::convert`,
	 *       что и у прочих. Замер до заведения проверки: заворот 8080 в один байт
	 *       даёт 144 у всех трёх, огранение 1e300 - предел вида у всех трёх
	 *
	 * @warning Проверка эта на ЭТОЙ машине общий ход от приведения языком НЕ отличает,
	 * и говорится это прямо, чтобы зелёное её не принимали за доказанное покрытие.
	 * Замерено подменою: увод таблицы с `awh::codec::convert` на голый `static_cast`
	 * исхода здесь не меняет, ибо приведение дробного к целому у ARM64 НАСЫЩАЕТ, и
	 * язык случайно отвечает то же, что общий ход. Отличие выйдет наружу там, где
	 * приведение не насыщает: у языка поведение там неопределено, и предел нижний
	 * приходит на месте верхнего. Оттого сторожем здесь служит не одна эта проверка,
	 * а прогон её на стенде иной разрядности
	 */
	{
		// Объект таблицы
		csv::document_t doc(::logger());
		// Выполняем разбор записей, подлежащих сужению
		ASSERT_TRUE(doc.parse("8080,1e300,-1e300\r\n"));
		// Владеющее значение, снятое с таблицы
		const csv::value_t table(doc);
		// Выполняем проверку заворота целого числа кодеком CSV
		ASSERT_TRUE(table.at("/0/0").value(byte));
		// Выполняем проверку совпадения заворота с прочими кодеками
		ASSERT_EQ(byte, static_cast <uint8_t> (8080));
		// Выполняем проверку огранения дробного числа верхним пределом
		ASSERT_TRUE(table.at("/0/1").value(number));
		// Выполняем проверку совпадения огранения с прочими кодеками
		ASSERT_EQ(number, ::std::numeric_limits <int32_t>::max());
		// Выполняем проверку огранения дробного числа нижним пределом
		ASSERT_TRUE(table.at("/0/2").value(number));
		// Выполняем проверку совпадения огранения с прочими кодеками
		ASSERT_EQ(number, ::std::numeric_limits <int32_t>::lowest());
	}
}
/**
 * @brief Проверка договора об обращении к вместилищу по номеру
 *
 * @details Договор этот распадается на три части, и лишь первая из них общая. Части
 *          расходящиеся заданы описаниями языков, а не выбором устройства: у JSON и
 *          YAML дыра заполняется значением пустым - оно у них законно, - тогда как у
 *          разметки заполнить дыру нечем, ибо узла разметки без имени не существует
 *          вовсе
 *
 * @note Разделение идёт по виду ДОРОГИ, а не по виду звена: разыскивающая дорога не
 *       заводит нигде, заводящая заводит там, где заполнить дыру есть чем
 *
 * @warning Части расходящиеся сведению не подлежат: свести их значило бы нарушить
 *          описание одного из языков. Держатся они здесь именно врозь и с доводом,
 *          ровно как расхождение по записи `NaN`
 *
 */
TEST(CodecContract, IndexedAccess) {
	/**
	 * Часть общая: чтение по номеру за пределом вместилища не заводит и не наращивает
	 */
	json::value_t plain;
	// Выполняем разбор перечня из двух значений
	ASSERT_TRUE(plain.parse("[1,2]"));
	// Объект владеющего значения разметки
	xml::value_t markup;
	// Выполняем разбор разметки из двух вложенных узлов
	ASSERT_TRUE(markup.parse("<a><b/><c/></a>"));
	// Объект владеющего значения YAML
	yaml::value_t staged;
	// Выполняем разбор перечня из двух значений
	ASSERT_TRUE(staged.parse("- 1\n- 2\n"));
	// Получаем неизменяемые значения всех трёх кодеков
	const json::value_t & jc = plain;
	const xml::value_t & xc = markup[static_cast <size_t> (0)];
	const yaml::value_t & yc = staged;
	// Выполняем чтение за пределом вместилища у кодека JSON
	jc[static_cast <size_t> (99)];
	// Выполняем проверку того, что вместилище не наросло
	ASSERT_EQ(jc.size(), static_cast <size_t> (2));
	// Выполняем чтение за пределом вместилища у кодека XML
	xc[static_cast <size_t> (99)];
	// Выполняем проверку того, что вместилище не наросло
	ASSERT_EQ(xc.size(), static_cast <size_t> (2));
	// Выполняем чтение за пределом вместилища у кодека YAML
	yc[static_cast <size_t> (99)];
	// Выполняем проверку того, что вместилище не наросло
	ASSERT_EQ(yc.size(), static_cast <size_t> (2));
	// Объект владеющего значения ABC
	abc::value_t binary;
	// Выполняем набор перечня из двух значений
	ASSERT_TRUE(binary.push(abc::value_t(int64_t(1))));
	ASSERT_TRUE(binary.push(abc::value_t(int64_t(2))));
	// Получаем неизменяемое значение кодека ABC
	const abc::value_t & bc = binary;
	// Выполняем чтение за пределом вместилища у кодека ABC
	bc[static_cast <size_t> (99)];
	// Выполняем проверку того, что вместилище не наросло
	ASSERT_EQ(bc.size(), static_cast <size_t> (2));
	/**
	 * Часть расходящаяся: заводящая дорога со звеном числовым
	 *
	 * @note У JSON и YAML перечень наращивается до затребованного номера, а дыры
	 *       заполняются значением пустым; у разметки заведение отвергается
	 */
	plain.place("/4");
	// Выполняем проверку наращивания перечня кодеком JSON
	ASSERT_EQ(plain.dump(), "[1,2,null,null,null]");
	// Выполняем заведение по номеру у кодека YAML
	staged.place("/4");
	// Выполняем проверку наращивания перечня кодеком YAML
	ASSERT_EQ(staged.size(), static_cast <size_t> (5));
	/**
	 * Выполняем проверку записываемости наросшего перечня кодеком YAML
	 *
	 * @note Сличается именно ЗАПИСЬ наросшего, а не один лишь его размер: наращивание
	 *       и записываемость наросшего - разные свойства, и второе ломалось у разметки
	 *       ровно там, где первое работало. Проверять надлежит то, что ломается, а не
	 *       то, что и так держится
	 */
	/**
	 * @note Черты начала документа в ожидании нет намеренно: перезапись владеющего
	 *       значения YAML открывает документ неявно и черту ставит лишь по настройке
	 *       `explicitStart` - ровно так же, как открывает первый документ потока дерево.
	 *       Прежде она ставилась всегда, и перезапись значения расходилась с перезаписью
	 *       дерева, того же содержимого, на одну эту черту
	 */
	ASSERT_EQ(staged.dump(), "- 1\n- 2\n-\n-\n-\n");
	// Выполняем заведение по номеру у кодека ABC
	binary.place("/4");
	// Выполняем проверку наращивания перечня кодеком ABC
	ASSERT_EQ(binary.size(), static_cast <size_t> (5));
	/**
	 * Выполняем проверку записываемости наросшего перечня кодеком ABC
	 *
	 * @note Запись сличается ОКТЕТ В ОКТЕТ, а не одним размером: `85` это метка перечня
	 *       из пяти звеньев, `01` и `02` - два числа встроенных, а три `C0` - три дыры,
	 *       заполненные ничем. Проверяя один лишь размер, нельзя отличить заполнение
	 *       дыры НИЧЕМ от заполнения её нулём, а это разные вещи: нуль есть значение
	 */
	ASSERT_EQ(binary.dump(), (vector <uint8_t> {0x85, 0x01, 0x02, 0xC0, 0xC0, 0xC0}));
	// Выполняем заведение по номеру у кодека XML
	markup.place("/0/4");
	// Выполняем проверку того, что разметка заведения по номеру не допустила
	ASSERT_EQ(markup[static_cast <size_t> (0)].size(), static_cast <size_t> (2));
	// Выполняем проверку того, что разметка осталась записываемой
	ASSERT_EQ(markup.dump(), "<a><b/><c/></a>");
	/**
	 * Выполняем проверку записываемости наросшего перечня у разметки
	 *
	 * @note Разметка наращивания заводящею дорогою не допускает вовсе, а обращением
	 *       изменяемым допускает - и наросшее там записи НЕ ПОДЛЕЖИТ, покуда узлам не
	 *       дано имя. Сличается здесь именно это: пустая выдача текста, обращающаяся
	 *       годной по присвоении имени
	 */
	markup[static_cast <size_t> (0)][static_cast <size_t> (3)];
	// Выполняем проверку того, что дерево с безымянными узлами записи не подлежит
	ASSERT_TRUE(markup.dump().empty());
	/**
	 * Выполняем перебор всех заведённых ростом узлов разметки
	 */
	for(size_t i = 2; i < markup[static_cast <size_t> (0)].size(); i++)
		// Выполняем присвоение имени очередному заведённому узлу
		markup[static_cast <size_t> (0)][i].name("d");
	// Выполняем проверку того, что дерево с именованными узлами записывается
	ASSERT_EQ(markup.dump(), "<a><b/><c/><d/><d/></a>");
}
/**
 * @brief Проверка согласия кодеков на снятии навязанной кодировки
 *
 * @note Кодировка исходного текста навязывается извне там, где она известна не из
 *       самого текста - скажем, из поля «Content-Type» ответа по договору HTTP.
 *       Написание отмены у всех трёх кодеков одно: кодировка неопределённая
 * @warning Кодек XML отвечал на это обращение ОТКАЗОМ, тогда как JSON и YAML снимали
 *          навязывание. Расхождение сглажено по двум против одного, и закреплено
 *          здесь: одно и то же обращение к двум кодекам одного набора обязано
 *          означать одно и то же, иначе потребитель, перешедший с кодека на кодек,
 *          получает ловушку тем более опасную, что молчаливую
 *
 * @note ABC в сличении этом НЕ участвует: хода `encoding()` у него нет вовсе, и завести
 *       его нечем. Кодировка строк у ABC задана САМИМ ФОРМАТОМ - строка объявлена в
 *       UTF-8, и октеты, ей не отвечающие, отвергаются разбором, - оттого ни узнавать
 *       её, ни навязывать извне не приходится. Отсутствие хода здесь есть свойство
 *       устройства, а не пробел набора
 */
TEST(CodecContract, EncodingRelease) {
	/**
	 * Снятие навязанной кодировки у кодека JSON
	 */
	{
		// Объект приведения текста
		json::decoder_t decoder(::logger());
		// Выполняем навязывание кодировки исходного текста
		ASSERT_TRUE(decoder.encoding(json::encoding_t::UTF16LE));
		// Выполняем проверку принятия снятия навязанной кодировки
		ASSERT_TRUE(decoder.encoding(json::encoding_t::NONE));
		// Текст, к которому приводится исходный
		string result = "";
		// Выполняем подачу текста в кодировке UTF-8
		ASSERT_TRUE(decoder.convert("\"ok\"", 4, true, result));
		// Выполняем проверку того, что кодировка определена по самому тексту
		ASSERT_EQ(result, "\"ok\"");
	}
	/**
	 * Снятие навязанной кодировки у кодека XML
	 */
	{
		// Объект приведения текста
		xml::decoder_t decoder(::logger());
		// Выполняем навязывание кодировки исходного текста
		ASSERT_TRUE(decoder.encoding(xml::encoding_t::UTF16LE));
		// Выполняем проверку принятия снятия навязанной кодировки
		ASSERT_TRUE(decoder.encoding(xml::encoding_t::NONE));
		// Текст, к которому приводится исходный
		string result = "";
		// Выполняем подачу текста в кодировке UTF-8
		ASSERT_TRUE(decoder.convert("<a/>", 4, true, result));
		// Выполняем проверку того, что кодировка определена по самому тексту
		ASSERT_EQ(result, "<a/>");
	}
	/**
	 * Снятие навязанной кодировки у кодека YAML
	 */
	{
		// Объект приведения текста
		yaml::decoder_t decoder(::logger());
		// Выполняем навязывание кодировки исходного текста
		ASSERT_TRUE(decoder.encoding(yaml::encoding_t::UTF16LE));
		// Выполняем проверку принятия снятия навязанной кодировки
		ASSERT_TRUE(decoder.encoding(yaml::encoding_t::NONE));
	}
}
/**
 * @brief Проверка согласия кодеков по опросу кодировки исходного текста
 *
 * @details Ход `encoding()` заведён у дерева всех кодеков рамки по заказу владельца о
 * согласовании их между собой. Отвечает он о кодировке, какою текст ПРОЧИТАН, - о той,
 * из которой шёл перевод в UTF-8, - и договор этот обязан выполняться одинаково у всех
 *
 * @note Проверка сличает не наличие хода, а ответ его: у JSON чтение живёт полем дерева,
 *       а у разметки и таблицы - лишь внутри разбора, и кодировка там хранится своим
 *       полем. Устройства разные, ответ обязан быть один
 *
 * @note Проверяются три положения договора: до разбора кодировка неопределена, после
 *       разбора текста с меткой порядка байтов выдаётся распознанная по метке, а очистка
 *       дерева кодировку сбрасывает наравне с кодом отказа
 *
 * @note ABC в сличении этом НЕ участвует по той же причине, что и в снятии навязанной
 *       кодировки: хода `encoding()` у него нет, ибо кодировка строк задана самим
 *       форматом, а метки порядка байтов двоичная запись не несёт и нести не может -
 *       первый её октет есть метка вида, а не метка кодировки
 *
 */
TEST(CodecContract, EncodingIsAskedAlikeAcrossCodecs) {
	/**
	 * Опрос кодировки у кодека JSON
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем проверку неопределённости кодировки до разбора
		ASSERT_EQ(doc.encoding(), json::encoding_t::NONE);
		// Выполняем разбор текста в кодировке UTF-8 с меткой порядка байтов
		ASSERT_TRUE(doc.parse(string("\xEF\xBB\xBF" "{\"a\":1}", 10)));
		// Выполняем проверку распознанной по метке кодировки
		ASSERT_EQ(doc.encoding(), json::encoding_t::UTF8);
		// Выполняем очистку дерева документа
		doc.clear();
		// Выполняем проверку сброса кодировки очисткой дерева
		ASSERT_EQ(doc.encoding(), json::encoding_t::NONE);
	}
	/**
	 * Опрос кодировки у кодека XML
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем проверку неопределённости кодировки до разбора
		ASSERT_EQ(doc.encoding(), xml::encoding_t::NONE);
		// Выполняем разбор текста в кодировке UTF-8 с меткой порядка байтов
		ASSERT_TRUE(doc.parse(string("\xEF\xBB\xBF" "<a/>", 7)));
		// Выполняем проверку распознанной по метке кодировки
		ASSERT_EQ(doc.encoding(), xml::encoding_t::UTF8);
		// Выполняем очистку дерева разметки
		doc.clear();
		// Выполняем проверку сброса кодировки очисткой дерева
		ASSERT_EQ(doc.encoding(), xml::encoding_t::NONE);
	}
	/**
	 * Опрос кодировки у кодека CSV
	 */
	{
		// Объект таблицы
		csv::document_t doc(::logger());
		// Выполняем проверку неопределённости кодировки до разбора
		ASSERT_EQ(doc.encoding(), csv::encoding_t::NONE);
		// Выполняем разбор текста в кодировке UTF-8 с меткой порядка байтов
		ASSERT_TRUE(doc.parse(string("\xEF\xBB\xBF" "a,b", 6)));
		// Выполняем проверку распознанной по метке кодировки
		ASSERT_EQ(doc.encoding(), csv::encoding_t::UTF8);
		// Выполняем очистку таблицы
		doc.clear();
		// Выполняем проверку сброса кодировки очисткой таблицы
		ASSERT_EQ(doc.encoding(), csv::encoding_t::NONE);
	}
}
/**
 * @brief Проверка согласия кодеков по опросу пустоты и наличия по пути
 *
 * @details Ходы `empty()` и `has()` заведены общим набором у всех кодеков рамки по
 * заказу владельца о согласовании их между собой. Вид пути остаётся своим у каждого
 * кодека: у документа это указатель RFC 6901, у разметки - путь по именам узлов
 *
 * @note Проверка сличает не наличие ходов, а ответы их на одни и те же положения:
 *       пустой кодек отвечает пустотой, разобранный - нет; путь к существующему месту
 *       отвечает наличием, путь в никуда - отсутствием
 *
 * @note У таблицы `size()` не заведено намеренно: одного размера у неё нет вовсе -
 *       есть `rows()`, `cols()` и `size(row)`. Пустота же вопрос однозначный, и она
 *       общею сделана. Правки дерева по пути у таблицы нет по той же причине: модель
 *       её таблица, а не дерево, и вести путь там некуда
 *
 */
TEST(CodecContract, EmptinessAndPresenceAreAskedAlikeAcrossCodecs) {
	/**
	 * Опрос пустоты и наличия у кодека JSON
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем проверку пустоты документа до разбора
		ASSERT_TRUE(doc.empty());
		// Выполняем разбор текста документа
		ASSERT_TRUE(doc.parse("{\"a\":{\"b\":1}}")) << json::message(doc.error());
		// Выполняем проверку того, что разобранный документ пустым не является
		ASSERT_FALSE(doc.empty());
		// Выполняем проверку наличия значения по существующему указателю
		ASSERT_TRUE(doc.has("/a/b"));
		// Выполняем проверку отсутствия значения по указателю в никуда
		ASSERT_FALSE(doc.has("/a/нет"));
		// Выполняем очистку документа
		doc.clear();
		// Выполняем проверку пустоты документа после очистки
		ASSERT_TRUE(doc.empty());
	}
	/**
	 * Опрос пустоты и наличия у кодека XML
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем проверку пустоты дерева до разбора
		ASSERT_TRUE(doc.empty());
		// Выполняем разбор текста разметки
		ASSERT_TRUE(doc.parse("<a><b/></a>")) << xml::message(doc.error());
		// Выполняем проверку того, что разобранное дерево пустым не является
		ASSERT_FALSE(doc.empty());
		// Выполняем проверку наличия узла по существующему пути
		ASSERT_TRUE(doc.has("/a/b"));
		// Выполняем проверку отсутствия узла по пути в никуда
		ASSERT_FALSE(doc.has("/a/нет"));
		// Выполняем очистку дерева разметки
		doc.clear();
		// Выполняем проверку пустоты дерева после очистки
		ASSERT_TRUE(doc.empty());
	}
	/**
	 * Опрос пустоты и наличия у кодека ABC
	 *
	 * @note Запись подаётся здесь двоичная, а не текстовая, и собирается она владеющим
	 *       значением: разбора текста у ABC не заведено вовсе. Сличается при этом не
	 *       способ подачи, а ответы на те же три положения - пустой, разобранный,
	 *       очищенный, - и они у него общие с прочими
	 * @warning `empty()` у ABC меряет УЗЛЫ АРЕНЫ, а `size()` - детей корня, и разошлись
	 *          бы они на записи из одного значения: узел там есть, а детей у корня нет.
	 *          Здесь подаётся запись вложенная, где обе меры непусты, - расхождение это
	 *          держится своей проверкой, `ChildCountIsSeparatedFromStorageCount`
	 */
	{
		// Объект владеющего значения вложенного отображения
		abc::value_t inner, outer;
		// Выполняем набор вложенного отображения
		ASSERT_TRUE(inner.insert(abc::value_t(string("b")), abc::value_t(int64_t(1))));
		// Выполняем набор внешнего отображения
		ASSERT_TRUE(outer.insert(abc::value_t(string("a")), inner));
		// Выполняем сборку двоичной записи
		const vector <uint8_t> record = outer.dump();
		// Объект документа
		abc::document_t doc(::logger());
		// Выполняем проверку пустоты документа до разбора
		ASSERT_TRUE(doc.empty());
		// Выполняем разбор двоичной записи документа
		ASSERT_TRUE(doc.parse(record.data(), record.size())) << abc::message(doc.error());
		// Выполняем проверку того, что разобранный документ пустым не является
		ASSERT_FALSE(doc.empty());
		// Выполняем проверку наличия значения по существующему указателю
		ASSERT_TRUE(doc.has("/a/b"));
		// Выполняем проверку отсутствия значения по указателю в никуда
		ASSERT_FALSE(doc.has("/a/нет"));
		// Выполняем очистку документа
		doc.clear();
		// Выполняем проверку пустоты документа после очистки
		ASSERT_TRUE(doc.empty());
	}
	/**
	 * Опрос пустоты у кодека CSV
	 */
	{
		// Объект таблицы
		csv::document_t doc(::logger());
		// Выполняем проверку пустоты таблицы до разбора
		ASSERT_TRUE(doc.empty());
		// Выполняем разбор текста таблицы
		ASSERT_TRUE(doc.parse("a,b\r\n1,2\r\n")) << csv::message(doc.error());
		// Выполняем проверку того, что разобранная таблица пустой не является
		ASSERT_FALSE(doc.empty());
		// Выполняем очистку таблицы
		doc.clear();
		// Выполняем проверку пустоты таблицы после очистки
		ASSERT_TRUE(doc.empty());
		/**
		 * Выполняем проверку того, что таблица с одним заголовком пустой не считается
		 *
		 * @note Записей у неё нет, а содержимое есть: записывается она непустым текстом,
		 *       и звать её пустой было бы ложью
		 */
		ASSERT_TRUE(doc.header({"имя", "значение"}));
		// Выполняем проверку того, что таблица с одним заголовком пустой не является
		ASSERT_FALSE(doc.empty());
		// Выполняем проверку отсутствия записей у таблицы с одним заголовком
		ASSERT_EQ(doc.rows(), static_cast <size_t> (0));
		// Выполняем проверку непустоты записи таблицы с одним заголовком
		ASSERT_FALSE(doc.dump().empty());
	}
}
/**
 * @brief Проверка согласия кодеков по записи пустого документа
 *
 * @details Общее имя хода ещё не значит общего поведения его, и сличать надлежит
 * ответы, а не подписи. Запись ПУСТОГО кодека - место, где кодеки расходятся законно,
 * и расхождение это вытекает из стандартов, а не из недосмотра
 *
 * @note Документ JSON без значения документом не является вовсе (RFC 8259: текст есть
 *       одно значение), и запись его отвечает отказом `EMPTY_TEXT`. Разметка XML без
 *       корневого узла разметкой не является (XML 1.0: ровно один корневой элемент), и
 *       запись отвечает `MISSING_ROOT`. Таблица же CSV без записей есть таблица ГОДНАЯ
 *       (RFC 4180 пустого файла не запрещает), и запись её отвечает УСПЕХОМ, отдавая
 *       файл нулевой длины
 *
 * @note Проверка заведена оттого, что расхождение это выглядит несогласованностью и
 *       напрашивается на «приведение к одному виду». Приведёт его тот, кто не знал
 *       довода, - и сломает либо JSON, либо CSV. Здесь довод записан вместе с
 *       требованием
 *
 * @note Прежде у JSON запись пустого дерева отдавала пустой текст с кодом «нет ошибки»,
 *       а запись того же дерева в ФАЙЛ отвечала отказом - то есть два хода одного
 *       кодека судили об одном и том же по-разному. Вскрыто сличением трёх кодеков
 *       щупом; поведение приведено к разметке
 *
 */
TEST(CodecContract, EmptyDocumentWritingDivergesByStandard) {
	/**
	 * Запись пустого документа JSON
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем проверку пустоты записи пустого документа
		ASSERT_TRUE(doc.dump().empty());
		// Выполняем проверку кода отказа записи документа без значения
		ASSERT_EQ(doc.error(), json::error_t::EMPTY_TEXT) << json::message(doc.error());
	}
	/**
	 * Запись пустого дерева разметки
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем проверку пустоты записи пустого дерева
		ASSERT_TRUE(doc.dump().empty());
		// Выполняем проверку кода отказа записи дерева без корневого узла
		ASSERT_EQ(doc.error(), xml::error_t::MISSING_ROOT) << xml::message(doc.error());
	}
	/**
	 * Запись пустой таблицы
	 */
	{
		// Объект таблицы
		csv::document_t doc(::logger());
		// Выполняем проверку пустоты записи пустой таблицы
		ASSERT_TRUE(doc.dump().empty());
		/**
		 * Выполняем проверку отсутствия отказа записи пустой таблицы
		 *
		 * @note Таблица без записей есть таблица годная, и отказом её запись отвечать
		 *       не смеет: расхождение это законно и держится стандартом
		 */
		ASSERT_EQ(doc.error(), csv::error_t::NONE) << csv::message(doc.error());
	}
	/**
	 * Запись пустого документа ABC
	 *
	 * @note ABC становится здесь рядом с JSON и разметкой, а не с таблицей: пустая
	 *       запись документом у него не является, и отдать он её не вправе. Довод тот
	 *       же, что у JSON, но идёт он не от текста, а от разбора: читатель, принявший
	 *       нуль октетов за годный документ, принял бы за него и оборванную посылку -
	 *       отличить недосланное от пустого было бы нечем
	 * @warning Значение НЕУСТАНОВЛЕННОЕ пустой записью НЕ является: укладывается оно
	 *          одним октетом `C0`, и запись эта годная. Пусто здесь именно НОЛЬ октетов
	 */
	{
		// Объект документа
		abc::document_t doc(::logger());
		// Выполняем проверку пустоты записи пустого документа
		ASSERT_TRUE(doc.dump().empty());
		// Выполняем проверку кода отказа записи документа без значения
		ASSERT_EQ(doc.error(), abc::error_t::EMPTY_RECORD) << abc::message(doc.error());
	}
}
/**
 * @brief Проверка согласия кодеков по судьбе содержимого при отказе
 *
 * @details Отказ разбора либо чтения файла обязан снимать прежде собранное ЦЕЛИКОМ у
 * всякого кодека рамки. Иначе потребитель, не проверивший признака отказа, работал бы
 * с половиной прежнего документа, принимая её за целый новый
 *
 * @note Договор этот сличается у трёх кодеков разом и по трём разным путям отказа:
 *       отсутствующий файл, каталог вместо файла и негодный текст. Пути эти в кодеке
 *       РАЗНЫЕ - один отвергается до чтения, другой на чтении, третий на разборе, - и
 *       снимать содержимое обязан всякий из них
 *
 * @note Проверка заведена оттого, что договор этот нигде не был записан, а держался
 *       на трёх независимых очистках в трёх кодеках. Расхождение вскрылось бы у
 *       потребителя, а не у нас
 *
 */
TEST(CodecContract, RefusalDropsThePreviousContentAlike) {
	/**
	 * Судьба содержимого документа JSON при отказе
	 */
	{
		/**
		 * Выполняем перебор всех путей отказа
		 */
		for(uint8_t path = 0; path < 3; path++){
			// Объект документа
			json::document_t doc(::logger());
			// Выполняем разбор годного текста документа
			ASSERT_TRUE(doc.parse("{\"a\":1}")) << json::message(doc.error());
			// Выполняем проверку того, что документ собран
			ASSERT_FALSE(doc.empty());
			// Выполняем наведение отказа выбранным путём
			switch(path){
				// Выполняем чтение отсутствующего файла
				case 0: ASSERT_FALSE(doc.load("./нет-такого-файла-документа.json")); break;
				// Выполняем чтение каталога вместо файла
				case 1: ASSERT_FALSE(doc.load(".")); break;
				// Выполняем разбор негодного текста
				case 2: ASSERT_FALSE(doc.parse("{битый")); break;
			}
			// Выполняем проверку снятия прежде собранного документа
			ASSERT_TRUE(doc.empty()) << static_cast <uint32_t> (path);
			// Выполняем проверку пустоты записи документа после отказа
			ASSERT_TRUE(doc.dump().empty()) << static_cast <uint32_t> (path);
		}
	}
	/**
	 * Судьба содержимого дерева разметки при отказе
	 */
	{
		/**
		 * Выполняем перебор всех путей отказа
		 */
		for(uint8_t path = 0; path < 3; path++){
			// Объект дерева разметки
			xml::document_t doc(::logger());
			// Выполняем разбор годного текста разметки
			ASSERT_TRUE(doc.parse("<a>1</a>")) << xml::message(doc.error());
			// Выполняем проверку того, что дерево собрано
			ASSERT_FALSE(doc.empty());
			// Выполняем наведение отказа выбранным путём
			switch(path){
				// Выполняем чтение отсутствующего файла
				case 0: ASSERT_FALSE(doc.load("./нет-такого-файла-разметки.xml")); break;
				// Выполняем чтение каталога вместо файла
				case 1: ASSERT_FALSE(doc.load(".")); break;
				// Выполняем разбор негодного текста
				case 2: ASSERT_FALSE(doc.parse("<битый")); break;
			}
			// Выполняем проверку снятия прежде собранного дерева
			ASSERT_TRUE(doc.empty()) << static_cast <uint32_t> (path);
			// Выполняем проверку пустоты записи дерева после отказа
			ASSERT_TRUE(doc.dump().empty()) << static_cast <uint32_t> (path);
		}
	}
	/**
	 * Судьба содержимого таблицы при отказе
	 */
	{
		/**
		 * Выполняем перебор всех путей отказа
		 */
		for(uint8_t path = 0; path < 3; path++){
			// Объект таблицы
			csv::document_t doc(::logger());
			// Выполняем разбор годного текста таблицы
			ASSERT_TRUE(doc.parse("a,b\r\n1,2\r\n")) << csv::message(doc.error());
			// Выполняем проверку того, что таблица собрана
			ASSERT_FALSE(doc.empty());
			// Выполняем наведение отказа выбранным путём
			switch(path){
				// Выполняем чтение отсутствующего файла
				case 0: ASSERT_FALSE(doc.load("./нет-такого-файла-таблицы.csv")); break;
				// Выполняем чтение каталога вместо файла
				case 1: ASSERT_FALSE(doc.load(".")); break;
				// Выполняем разбор негодного текста
				case 2: ASSERT_FALSE(doc.parse("a,\"б")); break;
			}
			// Выполняем проверку снятия прежде собранной таблицы
			ASSERT_TRUE(doc.empty()) << static_cast <uint32_t> (path);
			// Выполняем проверку пустоты записи таблицы после отказа
			ASSERT_TRUE(doc.dump().empty()) << static_cast <uint32_t> (path);
		}
	}
	/**
	 * Судьба содержимого документа ABC при отказе
	 *
	 * @note Путь отказа здесь ОДИН, а не три: чтения файла у ABC не заведено вовсе -
	 *       файловая его сторона это вместилище со своим заголовком и кусками, а не
	 *       голая запись, - и путей отказа, до разбора лежащих, у него нет
	 *
	 * @warning Записи здесь взяты такие, где отказ настигает разбор ПОСЛЕ того, как
	 *          часть дерева уже собрана: `A1` объявляет пару, которой нет, а `9F` -
	 *          вместимое неопределённой длины без завершителя. Возьми запись, негодную
	 *          с первого октета, - и собрать до отказа было бы нечего, а дерево вышло
	 *          бы пустым само собою. Проверка тогда была бы зелена и при дефекте: ровно
	 *          на этом дефект и держался
	 */
	{
		// Объект владеющего значения
		abc::value_t root;
		// Выполняем набор годной записи
		ASSERT_TRUE(root.insert(abc::value_t(string("a")), abc::value_t(int64_t(1))));
		// Выполняем сборку годной двоичной записи
		const vector <uint8_t> record = root.dump();
		// Перечень записей, отказ на которых настигает разбор на середине
		const vector <vector <uint8_t>> corrupted = {
			{0xA1}, {0x9F}, {0xA1, 0x61, 0x61}
		};
		/**
		 * Выполняем перебор всех негодных записей
		 */
		for(size_t i = 0; i < corrupted.size(); i++){
			// Объект документа
			abc::document_t doc(::logger());
			// Выполняем разбор годной записи документа
			ASSERT_TRUE(doc.parse(record.data(), record.size())) << abc::message(doc.error());
			// Выполняем проверку того, что документ собран
			ASSERT_FALSE(doc.empty());
			// Выполняем наведение отказа негодною записью
			ASSERT_FALSE(doc.parse(corrupted.at(i).data(), corrupted.at(i).size())) << i;
			// Выполняем проверку снятия прежде собранного дерева
			ASSERT_TRUE(doc.empty()) << i;
			// Выполняем проверку того, что узлов арены не осталось
			ASSERT_EQ(doc.nodes(), static_cast <size_t> (0)) << i;
			/**
			 * Выполняем проверку того, что причина отказа снятием НЕ затёрта
			 *
			 * @note Половина эта держит ПОРЯДОК, а не выбор хода. Снять содержимое
			 *       можно и очисткою, сбрасывающей причину, - покуда причина пишется
			 *       ПОСЛЕ снятия, вреда от того нет, и подмена снятия очисткою проверку
			 *       не красит. Красит её перенос снятия за запись причины: потребитель,
			 *       спросивший причину после отказа, слышит тогда «нет ошибки»
			 * @note Проверено обеими подменами: перенос красит строку эту, замена хода -
			 *       не красит ничего. Довод писался сперва о выборе хода и был НЕВЕРЕН
			 */
			ASSERT_NE(doc.error(), abc::error_t::NONE) << i;
		}
	}
}
/**
 * @brief Проверка согласия кодеков по разбору пустого текста
 *
 * @details Оборотная сторона записи пустого документа: там расходятся ходы `dump()`,
 * здесь - ход `parse()`. Расхождение то же самое и по той же причине, и записано оно
 * здесь затем, чтобы оба конца договора стояли рядом
 *
 * @note Пустой текст не является ни документом JSON, ни разметкой XML: первый обязан
 *       нести одно значение, вторая - ровно один корневой узел. Оба отвечают ОТКАЗОМ,
 *       и коды их суть те же, какими они отвечают на запись пустого дерева. Таблица же
 *       пустой текст принимает УСПЕХОМ, обращая его в таблицу без записей
 *
 * @note Текст из одних ПРОБЕЛОВ у таблицы пустым не считается вовсе: пробел есть
 *       значимое содержимое поля, и `«   \\r\\n »` даёт две записи об одном поле
 *       каждая. У документа и разметки пробельный текст неотличим от пустого - оба
 *       отвергают его тем же кодом
 *
 */
TEST(CodecContract, EmptyTextParsingDivergesByStandard) {
	/**
	 * Выполняем перебор пустого текста и текста из одних пробелов
	 */
	for(const string & text : {string(""), string("   \r\n ")}){
		/**
		 * Разбор пустого текста документом JSON
		 */
		{
			// Объект документа
			json::document_t doc(::logger());
			// Выполняем проверку отказа разбора пустого текста
			ASSERT_FALSE(doc.parse(text)) << text;
			// Выполняем проверку кода отказа разбора текста без значения
			ASSERT_EQ(doc.error(), json::error_t::EMPTY_TEXT) << json::message(doc.error());
		}
		/**
		 * Разбор пустого текста деревом разметки
		 */
		{
			// Объект дерева разметки
			xml::document_t doc(::logger());
			// Выполняем проверку отказа разбора пустого текста
			ASSERT_FALSE(doc.parse(text)) << text;
			// Выполняем проверку кода отказа разбора текста без корневого узла
			ASSERT_EQ(doc.error(), xml::error_t::MISSING_ROOT) << xml::message(doc.error());
		}
		/**
		 * Разбор пустого текста таблицей
		 */
		{
			// Объект таблицы
			csv::document_t doc(::logger());
			// Выполняем проверку успешности разбора пустого текста
			ASSERT_TRUE(doc.parse(text)) << text;
			// Выполняем проверку отсутствия отказа разбора пустого текста
			ASSERT_EQ(doc.error(), csv::error_t::NONE) << csv::message(doc.error());
		}
	}
	/**
	 * Выполняем проверку различения пустого текста и текста из пробелов таблицей
	 *
	 * @note Оба текста таблица принимает, но обращает в РАЗНОЕ: пустой даёт таблицу без
	 *       записей, а пробельный - две записи об одном поле каждая. Пробел есть
	 *       значимое содержимое поля, и отбрасывать его таблица не смеет
	 */
	{
		// Объект таблицы, разбирающей пустой текст
		csv::document_t empty(::logger());
		// Выполняем разбор пустого текста таблицы
		ASSERT_TRUE(empty.parse(""));
		// Выполняем проверку пустоты таблицы, собранной из пустого текста
		ASSERT_TRUE(empty.empty());
		// Выполняем проверку отсутствия записей у таблицы из пустого текста
		ASSERT_EQ(empty.rows(), static_cast <size_t> (0));
		// Объект таблицы, разбирающей текст из одних пробелов
		csv::document_t spaced(::logger());
		// Выполняем разбор текста таблицы из одних пробелов
		ASSERT_TRUE(spaced.parse("   \r\n "));
		// Выполняем проверку того, что таблица из пробелов пустой не является
		ASSERT_FALSE(spaced.empty());
		// Выполняем проверку числа записей таблицы из пробелов
		ASSERT_EQ(spaced.rows(), static_cast <size_t> (2));
		// Выполняем проверку сохранности пробелов записью таблицы
		ASSERT_EQ(spaced.dump(), "\"   \"\r\n\" \"\r\n");
	}
	/**
	 * Разбор пустой записи документом ABC
	 *
	 * @details ABC становится здесь рядом с JSON и разметкой: нуль октетов документом
	 *          не является, и разбор отвечает отказом. Довод у него свой и идёт от
	 *          двоичной подачи: прими читатель нуль октетов за годный документ - и
	 *          оборванная посылка стала бы неотличима от пустой
	 *
	 * @note Пробельного текста у ABC нет вовсе - разбирает он октеты, а не текст, - и
	 *       перебора двух написаний пустоты здесь потому нет
	 */
	{
		// Объект документа
		abc::document_t doc(::logger());
		// Выполняем проверку отказа разбора пустой записи
		ASSERT_FALSE(doc.parse(nullptr, 0));
		// Выполняем проверку кода отказа разбора записи без значения
		ASSERT_EQ(doc.error(), abc::error_t::EMPTY_RECORD) << abc::message(doc.error());
	}
	/**
	 * Выполняем проверку различения пустой записи и записи о НИЧЁМ кодеком ABC
	 *
	 * @details Различение это у ABC ровно то же, каким таблица различает пустой текст и
	 *          текст из пробелов: пусто и «ничего» суть разные вещи. Нуль октетов
	 *          документом не является, а один октет `C0` - значение неустановленное, и
	 *          запись эта ГОДНАЯ
	 *
	 * @warning Проверяется здесь ОБЕ меры разом, и в том вся сила: `nodes()` даёт
	 *          единицу - узел в арене есть, - а `size()` даёт нуль, ибо детей у корня
	 *          нет. Спроси проверка одну лишь `size()` - и годная запись о ничём была
	 *          бы неотличима от записи пустой, отвергнутой выше
	 */
	{
		// Запись значения неустановленного длиною в один октет
		const uint8_t nothing = 0xC0;
		// Объект документа
		abc::document_t doc(::logger());
		// Выполняем проверку успешности разбора записи о ничём
		ASSERT_TRUE(doc.parse(&nothing, sizeof(nothing))) << abc::message(doc.error());
		// Выполняем проверку отсутствия отказа разбора записи о ничём
		ASSERT_EQ(doc.error(), abc::error_t::NONE) << abc::message(doc.error());
		// Выполняем проверку наличия узла арены у записи о ничём
		ASSERT_EQ(doc.nodes(), static_cast <size_t> (1));
		// Выполняем проверку отсутствия детей корня у записи о ничём
		ASSERT_EQ(doc.size(), static_cast <size_t> (0));
	}
}
/**
 * @brief Проверка согласия кодеков по стойкости настроек
 *
 * @details Настройки кодека суть свойство САМОГО кодека, а не разобранного им текста:
 * переживать они обязаны и очистку, и новый разбор, и всякий отказ. Иначе потребитель,
 * поставивший настройки однажды, получал бы их молча сброшенными на втором документе
 *
 * @note Сличаются четыре пути разом: успешный разбор, очистка, отказ разбора и отказ
 *       чтения файла. Пути эти в кодеке разные, и всякий из них трогает состояние -
 *       сбросить настройки способен любой
 *
 * @note У разметки ход `settings()` заведён 03.09.2026 вместе с прочим общим набором, и
 *       проверка эта для неё не столько сторож, сколько первое закрепление договора
 *
 */
TEST(CodecContract, SettingsSurviveEveryOperation) {
	/**
	 * Стойкость настроек документа JSON
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Получаем настройки документа
		json::document_t::settings_t settings = doc.settings();
		// Устанавливаем нарядный вид записи текста документа
		settings.writer.format = json::format_t::PRETTY;
		// Выполняем установку настроек документа
		doc.settings(settings);
		// Выполняем успешный разбор текста документа
		ASSERT_TRUE(doc.parse("{\"a\":1}"));
		// Выполняем проверку сохранности настроек после разбора
		ASSERT_EQ(doc.settings().writer.format, json::format_t::PRETTY);
		// Выполняем очистку документа
		doc.clear();
		// Выполняем проверку сохранности настроек после очистки
		ASSERT_EQ(doc.settings().writer.format, json::format_t::PRETTY);
		// Выполняем разбор негодного текста документа
		ASSERT_FALSE(doc.parse("{битый"));
		// Выполняем проверку сохранности настроек после отказа разбора
		ASSERT_EQ(doc.settings().writer.format, json::format_t::PRETTY);
		// Выполняем чтение отсутствующего файла документа
		ASSERT_FALSE(doc.load("./нет-такого-файла-документа.json"));
		// Выполняем проверку сохранности настроек после отказа чтения
		ASSERT_EQ(doc.settings().writer.format, json::format_t::PRETTY);
	}
	/**
	 * Стойкость настроек дерева разметки
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Получаем настройки дерева разметки
		xml::document_t::settings_t settings = doc.settings();
		// Устанавливаем нарядный вид записи текста разметки
		settings.writer.format = xml::format_t::PRETTY;
		// Выполняем установку настроек дерева разметки
		doc.settings(settings);
		// Выполняем успешный разбор текста разметки
		ASSERT_TRUE(doc.parse("<a>1</a>"));
		// Выполняем проверку сохранности настроек после разбора
		ASSERT_EQ(doc.settings().writer.format, xml::format_t::PRETTY);
		// Выполняем очистку дерева разметки
		doc.clear();
		// Выполняем проверку сохранности настроек после очистки
		ASSERT_EQ(doc.settings().writer.format, xml::format_t::PRETTY);
		// Выполняем разбор негодного текста разметки
		ASSERT_FALSE(doc.parse("<битый"));
		// Выполняем проверку сохранности настроек после отказа разбора
		ASSERT_EQ(doc.settings().writer.format, xml::format_t::PRETTY);
		// Выполняем чтение отсутствующего файла разметки
		ASSERT_FALSE(doc.load("./нет-такого-файла-разметки.xml"));
		// Выполняем проверку сохранности настроек после отказа чтения
		ASSERT_EQ(doc.settings().writer.format, xml::format_t::PRETTY);
	}
	/**
	 * Стойкость настроек таблицы
	 */
	{
		// Объект таблицы
		csv::document_t doc(::logger());
		// Получаем настройки таблицы
		csv::document_t::settings_t settings = doc.settings();
		// Устанавливаем разделителем полей точку с запятой
		settings.writer.separator = ';';
		// Выполняем установку настроек таблицы
		doc.settings(settings);
		// Выполняем успешный разбор текста таблицы
		ASSERT_TRUE(doc.parse("a\r\n1\r\n"));
		// Выполняем проверку сохранности настроек после разбора
		ASSERT_EQ(doc.settings().writer.separator, ';');
		// Выполняем очистку таблицы
		doc.clear();
		// Выполняем проверку сохранности настроек после очистки
		ASSERT_EQ(doc.settings().writer.separator, ';');
		// Выполняем разбор негодного текста таблицы
		ASSERT_FALSE(doc.parse("a,\"б"));
		// Выполняем проверку сохранности настроек после отказа разбора
		ASSERT_EQ(doc.settings().writer.separator, ';');
		// Выполняем чтение отсутствующего файла таблицы
		ASSERT_FALSE(doc.load("./нет-такого-файла-таблицы.csv"));
		// Выполняем проверку сохранности настроек после отказа чтения
		ASSERT_EQ(doc.settings().writer.separator, ';');
	}
	/**
	 * Стойкость настроек документа ABC
	 *
	 * @note Путей здесь три, а не четыре: чтения файла у ABC не заведено, и отказа
	 *       чтения потому нет. Настройки же у него одни, читателя, - записи своих
	 *       настроек документ ABC не держит, они подаются прямо ходу `dump()`
	 */
	{
		// Объект владеющего значения
		abc::value_t root;
		// Выполняем набор годной записи
		ASSERT_TRUE(root.insert(abc::value_t(string("a")), abc::value_t(int64_t(1))));
		// Выполняем сборку годной двоичной записи
		const vector <uint8_t> record = root.dump();
		// Объект документа
		abc::document_t doc(::logger());
		/**
		 * Получаем настройки документа
		 *
		 * @note Вид настроек здесь берётся у ЧИТАТЕЛЯ, а не у документа: своего вида
		 *       настроек документ ABC не заводит, ибо править ему нечего - настройки
		 *       записи подаются прямо ходу `dump()`, а не хранятся полем
		 */
		abc::reader_t::settings_t settings = doc.settings();
		// Устанавливаем предел глубины вложенности, от умолчания отличный
		settings.maxDepth = 7;
		// Выполняем установку настроек документа
		doc.settings(settings);
		// Выполняем успешный разбор записи документа
		ASSERT_TRUE(doc.parse(record.data(), record.size())) << abc::message(doc.error());
		// Выполняем проверку сохранности настроек после разбора
		ASSERT_EQ(doc.settings().maxDepth, static_cast <uint32_t> (7));
		// Выполняем очистку документа
		doc.clear();
		// Выполняем проверку сохранности настроек после очистки
		ASSERT_EQ(doc.settings().maxDepth, static_cast <uint32_t> (7));
		// Запись, отказ на которой настигает разбор на середине
		const uint8_t corrupted = 0xA1;
		// Выполняем разбор негодной записи документа
		ASSERT_FALSE(doc.parse(&corrupted, sizeof(corrupted)));
		// Выполняем проверку сохранности настроек после отказа разбора
		ASSERT_EQ(doc.settings().maxDepth, static_cast <uint32_t> (7));
	}
}
/**
 * @brief Сохранение оставляет прежний файл нетронутым при отказе записи
 *
 * @details Отказ записи, - переполненный носитель либо превышенный предел размера
 * файла, - настигает сохранение уже ПОСЛЕ усечения цели, буде запись ведётся прямо
 * в неё. Цель при этом обращается в обрубок, а вызов честно отвечает отказом: данные
 * пользователя уничтожены молча. Все три кодека потому собирают текст в файл соседний
 * и переносят его на место цели лишь по успешном завершении
 *
 * @note Замер щупом до правки: цель о 4096 октетах обращалась в обрубок о 8192 у
 *       кодеков JSON и XML, тогда как таблица CSV прежнее содержимое сберегала
 *
 * @note ABC в сличении этом НЕ участвует: ходов `load` и `save` у него нет вовсе, и
 *       отсутствие их есть РАЗДЕЛЕНИЕ двух дорог, а не пробел. Дорог у потребителя ABC
 *       две, и они разного назначения: вместилище со сделками - для того, ради чего
 *       кодек и заведён, - и голая пара `Storage::store` / `Storage::fetch` для того,
 *       кому нужны просто октеты в файле
 *
 * @note Довод этот записан СЧЁТОМ, а не ссылкой на устройство, ибо «у меня своё
 *       устройство» оправдывает что угодно. Свойств у вместилища шесть, и всякое
 *       спрошено порознь: выразимо ли оно ходом `save(имя файла)` без потери?
 *
 * @li Заголовок опознания в 96 октетов с контрольной суммой - НЕ выразим: `save`
 *     кладёт октеты, ему поданные, а заголовок надо ВЫРАБОТАТЬ и сверить при чтении
 * @li Кадры со своим сжатием и шифрованием - НЕ выразимы: способ сжатия и ключ
 *     задаются кодеку заранее, а у `save` довода под них нет вовсе
 * @li Оглавление записей - НЕ выразимо: оно растёт правкой, а `save` есть работа
 *     однократная, ничего не помнящая между вызовами
 * @li Подпись деревом свёрток - НЕ выразима: свёртка берётся с КАЖДОГО кадра по мере
 *     укладки, то есть требует потока, а не готовых октетов
 * @li Откат по журналу - НЕ выразим, и он же довод решающий: сделка, спрятанная за
 *     `save(имя)`, есть прямая ложь потребителю - он ждёт «положить в файл», а
 *     получает сделку, чьих гарантий не заказывал и чьей цены не видит
 * @li Уборка мусора с перекладкой - НЕ выразима: она читает прежний контейнер и
 *     пишет новый, то есть работа над ДВУМЯ файлами, а `save` знает один
 *
 * @note Счёт вышел шесть из шести. Спрошено было и обратное - есть ли среди шести хоть
 *       одно, выразимое `save` без потери, - и такого не нашлось; будь оно, довод
 *       пришлось бы сузить до «пять из шести», ибо формулировка счётом проверяема, а
 *       «вместилище несводимо» неопровержима и тем негодна
 *
 * @warning Довод этот держался прежде на ПОЛОВИНЕ дороги: `store` голую запись в файл
 *          клал, а взять её обратно было нечем - `load` кормит сниматель вместилища,
 *          ждущий заголовка. Пара замкнута 03.09.2026 заведением `fetch`, и до того
 *          отсутствие `save` читалось бы пробелом справедливо. Закрепление пары -
 *          `CodecAbcStorage.StoreAndFetchAreTwins`
 *
 */
TEST(CodecContract, SavingKeepsThePreviousFileOnWriteFailure) {
	/**
	 * Проверка эта опирается на предел размера файла, которого у MS Windows нет
	 */
	#if defined(_WIN32) || defined(_WIN64)
		// Выполняем пропуск проверки за отсутствием предела размера файла
		GTEST_SKIP() << "У MS Windows предела RLIMIT_FSIZE не имеется";
	#else
		// Адрес цели, содержимое которой обязано пережить отказ записи
		const string filename = "./цель-отказа-записи.dat";
		// Прежнее содержимое цели
		const string previous(4096, 'X');
		/**
		 * @brief Хранитель предела размера файла и обработчика его превышения
		 *
		 * @note Предел этот и обработчик - настройки ПРОЦЕССА, и, останься они
		 *       поднятыми, отказом отозвались бы соседние проверки, к пределу
		 *       отношения не имеющие. Жёсткий предел не трогается вовсе, потому
		 *       мягкий и поднимается обратно беспрепятственно
		 *
		 */
		struct guard_t {
			// Прежний предел размера файла
			struct rlimit limit;
			// Прежний обработчик превышения предела
			void (* handler)(int);
			/**
			 * @brief Конструктор
			 *
			 */
			guard_t() noexcept : handler(nullptr) {
				// Запоминаем прежний предел размера файла
				::getrlimit(RLIMIT_FSIZE, &this->limit);
				// Глушим смерть процесса по превышению предела
				this->handler = ::signal(SIGXFSZ, SIG_IGN);
				// Снижаем мягкий предел размера файла
				struct rlimit lowered = this->limit;
				// Устанавливаем мягкий предел размера файла
				lowered.rlim_cur = 8192;
				// Выполняем установку сниженного предела размера файла
				::setrlimit(RLIMIT_FSIZE, &lowered);
			}
			/**
			 * @brief Деструктор
			 *
			 */
			~guard_t() noexcept {
				// Выполняем восстановление прежнего предела размера файла
				::setrlimit(RLIMIT_FSIZE, &this->limit);
				// Выполняем восстановление прежнего обработчика превышения предела
				::signal(SIGXFSZ, this->handler);
			}
		};
		/**
		 * @brief Метод чтения содержимого файла целиком
		 *
		 * @param filename адрес читаемого файла
		 * @return         прочитанное содержимое файла
		 *
		 */
		auto slurp = [](const string & filename) noexcept -> string {
			// Открываем читаемый файл
			ifstream file(filename, ios::binary);
			// Объект собираемого содержимого файла
			ostringstream result;
			// Выполняем чтение содержимого файла целиком
			result << file.rdbuf();
			// Выводим прочитанное содержимое файла
			return result.str();
		};
		/**
		 * @brief Метод восстановления прежнего содержимого цели
		 *
		 * @param filename адрес цели
		 * @param previous прежнее содержимое цели
		 *
		 */
		auto restore = [](const string & filename, const string & previous) noexcept -> void {
			// Открываем цель для записи
			ofstream file(filename, ios::binary | ios::trunc);
			// Выполняем запись прежнего содержимого цели
			file.write(previous.data(), static_cast <streamsize> (previous.size()));
		};
		// Выполняем установку прежнего содержимого цели ДО снижения предела
		restore(filename, previous);
		/**
		 * Неделимость сохранения документа
		 */
		{
			// Текст документа, заведомо превышающий предел размера файла
			string text(1, '[');
			/**
			 * Выполняем набор значений документа
			 */
			for(uint16_t i = 0; i < 2000; i++)
				// Добавляем очередное значение документа
				text.append("\"поле" + std::to_string(i) + "\",");
			// Заменяем последнюю запятую закрывающей скобкой
			text.back() = ']';
			// Объект документа
			json::document_t doc(::logger());
			// Выполняем разбор текста документа
			ASSERT_TRUE(doc.parse(text));
			// Выполняем снижение предела размера файла
			guard_t guard;
			// Выполняем проверку отказа записи документа
			ASSERT_FALSE(doc.save(filename));
			// Выполняем проверку сохранности прежнего содержимого цели
			ASSERT_EQ(slurp(filename), previous);
		}
		/**
		 * Неделимость сохранения дерева разметки
		 */
		{
			// Текст разметки, заведомо превышающий предел размера файла
			string text = "<root>";
			/**
			 * Выполняем набор узлов дерева разметки
			 */
			for(uint16_t i = 0; i < 2000; i++)
				// Добавляем очередной узел дерева разметки
				text.append("<a>значение" + std::to_string(i) + "</a>");
			// Завершаем текст разметки
			text.append("</root>");
			// Объект дерева разметки
			xml::document_t doc(::logger());
			// Выполняем разбор текста разметки
			ASSERT_TRUE(doc.parse(text));
			// Выполняем снижение предела размера файла
			guard_t guard;
			// Выполняем проверку отказа записи дерева разметки
			ASSERT_FALSE(doc.save(filename));
			// Выполняем проверку сохранности прежнего содержимого цели
			ASSERT_EQ(slurp(filename), previous);
		}
		/**
		 * Неделимость сохранения таблицы
		 */
		{
			// Текст таблицы, заведомо превышающий предел размера файла
			string text;
			/**
			 * Выполняем набор записей таблицы
			 */
			for(uint16_t r = 0; r < 800; r++){
				/**
				 * Выполняем набор полей очередной записи таблицы
				 */
				for(uint16_t c = 0; c < 20; c++){
					// Добавляем очередное поле записи таблицы
					text.append("поле" + std::to_string(r) + "_" + std::to_string(c));
					// Добавляем разделитель полей записи таблицы
					if(c < 19)
						// Устанавливаем разделитель полей записи таблицы
						text.append(1, ',');
				}
				// Завершаем очередную запись таблицы
				text.append("\r\n");
			}
			// Объект таблицы
			csv::document_t doc(::logger());
			// Выполняем разбор текста таблицы
			ASSERT_TRUE(doc.parse(text));
			// Выполняем снижение предела размера файла
			guard_t guard;
			// Выполняем проверку отказа записи таблицы
			ASSERT_FALSE(doc.save(filename));
			// Выполняем проверку сохранности прежнего содержимого цели
			ASSERT_EQ(slurp(filename), previous);
		}
		/**
		 * Выполняем закрепление неделимости у ВЛАДЕЮЩИХ ЗНАЧЕНИЙ всех трёх кодеков
		 *
		 * @details Своё сохранение есть не только у документа, но и у владеющего
		 *          значения, а ход это ОТДЕЛЬНЫЙ, кодом с документом общего не
		 *          имеющий. Договор, закреплённый у одного лишь документа, разошёлся
		 *          бы здесь беззвучно: правка идёт по одному месту, а мест шесть
		 *
		 * @note Пробел этот вскрыт перебором по всем семи кодекам разом, а не чтением
		 *       своего кода: у трёх соседних кодеков сохранение и поныне ведётся
		 *       прямою записью в цель, и найдено это было именно перебором
		 */
		{
			// Собираемый текст документа, заведомо превышающий предел размера файла
			string text("{");
			/**
			 * Выполняем набор свойств документа
			 */
			for(uint16_t i = 0; i < 4000; i++){
				// Добавляем разделитель свойств документа
				if(i > 0)
					// Устанавливаем разделитель свойств документа
					text.append(1, ',');
				// Добавляем очередное свойство документа
				text.append("\"имя-достаточно-длинное-").append(std::to_string(i)).append("\":").append(std::to_string(i));
			}
			// Завершаем собираемый текст документа
			text.append(1, '}');
			// Объект документа
			json::document_t doc(::logger());
			// Выполняем разбор текста документа
			ASSERT_TRUE(doc.parse(text));
			// Владеющее значение, снятое с документа
			const json::value_t value(doc.root());
			// Выполняем снижение предела размера файла
			guard_t guard;
			// Выполняем проверку отказа записи владеющего значения
			ASSERT_FALSE(value.save(filename));
			// Выполняем проверку сохранности прежнего содержимого цели
			ASSERT_EQ(slurp(filename), previous);
		}
		{
			// Собираемый текст разметки, заведомо превышающий предел размера файла
			string text("<root>");
			/**
			 * Выполняем набор узлов разметки
			 */
			for(uint16_t i = 0; i < 4000; i++)
				// Добавляем очередной узел разметки
				text.append("<узел-достаточно-длинный>").append(std::to_string(i)).append("</узел-достаточно-длинный>");
			// Завершаем собираемый текст разметки
			text.append("</root>");
			// Объект дерева разметки
			xml::document_t doc(::logger());
			// Выполняем разбор текста разметки
			ASSERT_TRUE(doc.parse(text));
			// Владеющее значение, снятое с дерева разметки
			const xml::value_t value(doc.element());
			// Выполняем проверку пригодности снятого значения
			ASSERT_TRUE(value.valid());
			// Выполняем снижение предела размера файла
			guard_t guard;
			// Выполняем проверку отказа записи владеющего значения
			ASSERT_FALSE(value.save(filename));
			// Выполняем проверку сохранности прежнего содержимого цели
			ASSERT_EQ(slurp(filename), previous);
		}
		{
			// Собираемое владеющее значение таблицы
			csv::value_t value(csv::value_t::type_t::TABLE);
			/**
			 * Выполняем набор записей таблицы
			 */
			for(uint16_t r = 0; r < 800; r++){
				// Собираемая запись таблицы
				csv::value_t record(csv::value_t::type_t::RECORD);
				/**
				 * Выполняем набор полей очередной записи таблицы
				 */
				for(uint16_t c = 0; c < 20; c++)
					// Выполняем добавление очередного поля записи
					ASSERT_TRUE(record.push(csv::value_t(string("поле") + std::to_string(r) + "_" + std::to_string(c))));
				// Выполняем добавление записи в таблицу
				ASSERT_TRUE(value.push(record));
			}
			// Выполняем снижение предела размера файла
			guard_t guard;
			// Выполняем проверку отказа записи владеющего значения
			ASSERT_FALSE(value.save(filename));
			// Выполняем проверку сохранности прежнего содержимого цели
			ASSERT_EQ(slurp(filename), previous);
		}
		// Выполняем снос цели проверки
		::remove(filename.c_str());
	#endif
}
/**
 * @brief Содержимое строится с нуля общим ходом у всех трёх кодеков
 *
 * @details Кодек, у какого содержимое заводится одним лишь разбором текста, потребителю
 * СОБИРАЮЩЕМУ негоден вовсе. Дерево разметки таким и было: розыск по пустому пути
 * отвергается сам, а прививка требовала места существующего, - и построение с нуля
 * упиралось в разбор текста, наскоро собранного строкою
 *
 * @note Корнем дерева разметки становится один лишь узел разметки, тогда как корнем
 *       документа JSON - значение любого вида. Расхождение это идёт от XML 1.0,
 *       требующего у документа ровно один корневой элемент, и приведению не подлежит
 *
 */
TEST(CodecContract, ContentIsBuiltFromScratchAlike) {
	/**
	 * Построение дерева разметки с нуля
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Собираемое содержимое узла разметки
		xml::value_t body("body");
		// Выполняем добавление текстового содержимого узла разметки
		ASSERT_TRUE(body.push(xml::value_t(xml::kind_t::TEXT, "содержимое")));
		// Собираемый корневой узел разметки
		xml::value_t root("envelope");
		// Выполняем добавление вложенного узла разметки
		ASSERT_TRUE(root.push(body));
		// Выполняем прививку собранного значения корнем дерева разметки
		ASSERT_TRUE(doc.set("", root));
		// Выполняем проверку собранного текста разметки
		ASSERT_EQ(doc.dump(), "<envelope><body>содержимое</body></envelope>");
		// Выполняем проверку отсутствия кода отказа
		ASSERT_EQ(doc.error(), xml::error_t::NONE);
	}
	/**
	 * Замена корневого узла разметки на месте
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем разбор текста разметки
		ASSERT_TRUE(doc.parse("<a><b>1</b></a>"));
		// Выполняем прививку нового корневого узла разметки
		ASSERT_TRUE(doc.set("", xml::value_t("c")));
		// Выполняем проверку замены корневого узла разметки целиком
		ASSERT_EQ(doc.dump(), "<c/>");
	}
	/**
	 * Корнем дерева разметки становится один лишь узел разметки
	 *
	 * @note Отступление это от документа JSON предписано XML 1.0
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем прививку текстового значения корнем дерева разметки
		ASSERT_FALSE(doc.set("", xml::value_t(xml::kind_t::TEXT, "просто текст")));
		// Выполняем проверку кода отказа прививки корня
		ASSERT_EQ(doc.error(), xml::error_t::MISSING_ROOT);
		// Выполняем проверку того, что дерево разметки осталось пустым
		ASSERT_TRUE(doc.dump().empty());
	}
	/**
	 * Построение документа JSON с нуля
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем прививку значения корнем документа
		ASSERT_TRUE(doc.set("", json::value_t(static_cast <int64_t> (1))));
		// Выполняем проверку собранного текста документа
		ASSERT_EQ(doc.dump(), "1");
		// Выполняем проверку отсутствия кода отказа
		ASSERT_EQ(doc.error(), json::error_t::NONE);
	}
	/**
	 * Построение таблицы с нуля
	 */
	{
		// Объект таблицы
		csv::document_t doc(::logger());
		// Выполняем установку заголовка таблицы
		doc.header(vector <string> {"a"});
		// Выполняем добавление записи таблицы
		doc.append(vector <string> {"1"});
		// Выполняем проверку собранного текста таблицы
		ASSERT_FALSE(doc.dump().empty());
		// Выполняем проверку отсутствия кода отказа
		ASSERT_EQ(doc.error(), csv::error_t::NONE);
	}
	/**
	 * Круговой ход построенного дерева разметки
	 *
	 * @note Построенное обязано разбираться обратно: дерево, собранное руками, могло бы
	 *       записываться текстом, разбору не подлежащим, и порок этот виден лишь кругом
	 */
	{
		// Объект собираемого дерева разметки
		xml::document_t doc(::logger());
		// Выполняем прививку собранного значения корнем дерева разметки
		ASSERT_TRUE(doc.set("", xml::value_t("a")));
		// Объект дерева разметки для обратного разбора
		xml::document_t back(::logger());
		// Выполняем разбор собранного текста разметки
		ASSERT_TRUE(back.parse(doc.dump()));
		// Выполняем проверку совпадения текста разметки после круга
		ASSERT_EQ(back.dump(), doc.dump());
	}
	/**
	 * Построение записи ABC с нуля
	 *
	 * @details У ABC потребитель СОБИРАЮЩИЙ есть основной, а не побочный: разбора текста
	 *          кодек не имеет вовсе, и всякая запись его начинается построением. Оттого
	 *          проверка эта у него не сторож редкого случая, а сторож главной дороги
	 *
	 * @note Корнем записи ABC становится значение любого вида - тем он ближе к JSON, чем
	 *       к разметке, требующей корнем ровно один узел
	 */
	{
		// Собираемое вложенное отображение
		abc::value_t body;
		// Выполняем добавление содержимого вложенного отображения
		ASSERT_TRUE(body.insert(abc::value_t(string("текст")), abc::value_t(string("содержимое"))));
		// Собираемое корневое отображение
		abc::value_t root;
		// Выполняем прививку вложенного отображения корню
		ASSERT_TRUE(root.insert(abc::value_t(string("узел")), body));
		// Выполняем сборку двоичной записи построенного
		const vector <uint8_t> record = root.dump();
		// Выполняем проверку того, что построенное записи подлежит
		ASSERT_FALSE(record.empty());
		/**
		 * Выполняем проверку разбираемости построенного обратно
		 *
		 * @note Круг здесь важнее самой сборки: значение, собранное руками, могло бы
		 *       укладываться в октеты, разбору не подлежащие, - скажем, с меткою длины,
		 *       уложенным октетам не отвечающей, - и порок этот виден лишь кругом
		 */
		abc::document_t back(::logger());
		// Выполняем разбор собранной двоичной записи
		ASSERT_TRUE(back.parse(record.data(), record.size())) << abc::message(back.error());
		// Выполняем проверку совпадения записи после круга
		ASSERT_EQ(back.dump(), record);
		// Выполняем проверку достижимости построенного по пути
		ASSERT_TRUE(back.has("/узел/текст"));
	}
}
/**
 * @brief Пустой путь понимается всеми ходами правки одинаково
 *
 * @details Путь, у одного хода значимый, а у прочих отвергаемый, трактуется двояко:
 * прививка писала бы корневой узел, а опрос наличия и извлечение его не видели бы вовсе.
 * Замер до правки: `set("")` у дерева разметки заводил корень, тогда как `has("")`
 * отвечал отсутствием, а `at("")` - непригодным узлом
 *
 * @note Снос корня отвергается у обоих кодеков: XML 1.0 требует у документа ровно один
 *       корневой элемент, а документ JSON без значения записи не подлежит. Заменить
 *       корень целиком дозволено прививкой, а снести его - нет
 *
 */
TEST(CodecContract, EmptyPathIsUnderstoodAlikeByEveryEditingCall) {
	/**
	 * Пустой путь у дерева разметки
	 *
	 * @note Каждый ход опрашивается на СВОЁМ дереве намеренно: сброс содержимое корня
	 *       правит, и опрос его соседями по одному дереву судил бы уже о правленом
	 */
	{
		// Опрос наличия корневого узла разметки
		{
			// Объект дерева разметки
			xml::document_t doc(::logger());
			// Выполняем разбор текста разметки
			ASSERT_TRUE(doc.parse("<a><b/></a>"));
			// Выполняем проверку наличия узла по пустому пути
			ASSERT_TRUE(doc.has(""));
		}
		// Извлечение корневого узла разметки
		{
			// Объект дерева разметки
			xml::document_t doc(::logger());
			// Выполняем разбор текста разметки
			ASSERT_TRUE(doc.parse("<a><b/></a>"));
			// Выполняем проверку пригодности узла, извлечённого по пустому пути
			ASSERT_TRUE(doc.at("").valid());
			// Выполняем проверку того, что извлечён именно корневой узел разметки
			ASSERT_EQ(doc.at("").name().local, "a");
		}
		// Снос корневого узла разметки
		{
			// Объект дерева разметки
			xml::document_t doc(::logger());
			// Выполняем разбор текста разметки
			ASSERT_TRUE(doc.parse("<a><b/></a>"));
			// Выполняем проверку отказа сноса по пустому пути
			ASSERT_FALSE(doc.erase(""));
			// Выполняем проверку сохранности дерева разметки
			ASSERT_EQ(doc.dump(), "<a><b/></a>");
		}
		// Сброс содержимого корневого узла разметки
		{
			// Объект дерева разметки
			xml::document_t doc(::logger());
			// Выполняем разбор текста разметки
			ASSERT_TRUE(doc.parse("<a><b/></a>"));
			// Выполняем проверку успешности сброса по пустому пути
			ASSERT_TRUE(doc.reset(""));
			// Выполняем проверку опустошения корневого узла разметки
			ASSERT_EQ(doc.dump(), "<a/>");
		}
	}
	/**
	 * Пустой указатель у документа
	 */
	{
		// Опрос наличия корня документа
		{
			// Объект документа
			json::document_t doc(::logger());
			// Выполняем разбор текста документа
			ASSERT_TRUE(doc.parse("{\"a\":1}"));
			// Выполняем проверку наличия значения по пустому указателю
			ASSERT_TRUE(doc.has(""));
		}
		// Снос корня документа
		{
			// Объект документа
			json::document_t doc(::logger());
			// Выполняем разбор текста документа
			ASSERT_TRUE(doc.parse("{\"a\":1}"));
			// Выполняем проверку отказа сноса по пустому указателю
			ASSERT_FALSE(doc.erase(""));
			// Выполняем проверку сохранности документа
			ASSERT_EQ(doc.dump(), "{\"a\":1}");
		}
		// Сброс корня документа
		{
			// Объект документа
			json::document_t doc(::logger());
			// Выполняем разбор текста документа
			ASSERT_TRUE(doc.parse("{\"a\":1}"));
			// Выполняем проверку успешности сброса по пустому указателю
			ASSERT_TRUE(doc.reset(""));
			// Выполняем проверку опустошения документа
			ASSERT_EQ(doc.dump(), "null");
		}
	}
	/**
	 * Пустой путь у документа ABC
	 *
	 * @details Половина здесь одна, читающая: правки дерева у документа ABC не заведено
	 *          вовсе - он есть разбор ТОЛЬКО ДЛЯ ЧТЕНИЯ, - и ходов `set`, `erase`,
	 *          `reset` у него нет. Отсутствие их не отступление: правка живёт у
	 *          владеющего значения, и оно здесь опрашивается вторым
	 *
	 * @note Договор RFC 6901 о пустом пути один у всех кодеков рамки: пустой путь есть
	 *       ВЕСЬ документ. Проверяется тем самым, что оба взгляда ABC понимают его
	 *       одинаково, - расхождение близнецов у него уже случалось
	 */
	{
		// Объект владеющего значения
		abc::value_t root;
		// Выполняем набор годной записи
		ASSERT_TRUE(root.insert(abc::value_t(string("a")), abc::value_t(int64_t(1))));
		// Выполняем сборку годной двоичной записи
		const vector <uint8_t> record = root.dump();
		// Опрос наличия корня документа
		{
			// Объект документа
			abc::document_t doc(::logger());
			// Выполняем разбор записи документа
			ASSERT_TRUE(doc.parse(record.data(), record.size())) << abc::message(doc.error());
			// Выполняем проверку наличия значения по пустому пути
			ASSERT_TRUE(doc.has(""));
		}
		// Извлечение корня документа
		{
			// Объект документа
			abc::document_t doc(::logger());
			// Выполняем разбор записи документа
			ASSERT_TRUE(doc.parse(record.data(), record.size())) << abc::message(doc.error());
			// Выполняем проверку пригодности значения, извлечённого по пустому пути
			ASSERT_TRUE(doc.at("").valid());
			/**
			 * Выполняем проверку того, что извлечён именно КОРЕНЬ документа
			 *
			 * @note Сличается с ответом хода `root()`, а не с числом наугад: совпади
			 *       размер по случайности - и проверка ничего бы не значила. Здесь же
			 *       сличаются два хода, обязанных отдавать одно
			 */
			ASSERT_EQ(doc.at("").size(), doc.root().size());
			// Выполняем проверку совпадения вида извлечённого значения с корнем
			ASSERT_EQ(doc.at("").type(), doc.root().type());
		}
		/**
		 * Выполняем проверку понимания пустого пути владеющим значением
		 *
		 * @note Взгляд этот второй, и здесь он ОБЯЗАН отвечать то же самое: пустой путь
		 *       у него тоже есть всё значение целиком
		 */
		ASSERT_TRUE(root.at("").valid());
		// Выполняем проверку того, что извлечено именно всё значение целиком
		ASSERT_EQ(root.at("").size(), root.size());
	}
}
/**
 * @brief Код отказа и положение его ставятся заново всякой работе
 *
 * @details Код, поставленный отказом разбора, обязан умереть с первою же работой
 * следующей, - иначе он переживает работу удавшуюся, и звучащий принимает его за отказ
 * её. Положение при том лживее самого кода: у отказа записи места в исходном тексте нет
 * вовсе, и старое место складывается с новым кодом в донесение стройное, но ложное
 *
 * @note Замер до правки: у дерева разметки разбор отказывал в строке 3 столбце 1, следом
 *       УДАВАЛАСЬ прививка и запись, а `error()` отвечал кодом `UNCLOSED_TAG` с местом
 *       3:1 - в тексте, которого более нет. Документ JSON и таблица CSV поле это
 *       сбрасывали уже
 *
 * @note Отказ самой правки по пути кода НЕ ставит ни у одного из кодеков: путь, ведущий
 *       в никуда, оглашается возвратом `false`, и он потребителю виден прямо. Код отведён
 *       работам, чей отказ иначе неотличим от пустого исхода
 *
 */
TEST(CodecContract, ErrorAndItsLocationAreSetAnewByEveryCall) {
	/**
	 * Донесение дерева разметки
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем разбор негодного текста разметки
		ASSERT_FALSE(doc.parse("<a>\n<b>\n<битый"));
		// Выполняем проверку кода отказа разбора
		ASSERT_EQ(doc.error(), xml::error_t::UNCLOSED_TAG);
		// Выполняем проверку положения отказа разбора
		ASSERT_EQ(doc.errorLocation().line, static_cast <size_t> (3));
		// Выполняем прививку собранного значения корнем дерева разметки
		ASSERT_TRUE(doc.set("", xml::value_t("a")));
		// Выполняем проверку сброса кода отказа удавшейся прививкой
		ASSERT_EQ(doc.error(), xml::error_t::NONE);
		// Выполняем проверку сброса положения отказа удавшейся прививкой
		ASSERT_EQ(doc.errorLocation().line, static_cast <size_t> (0));
		// Выполняем разбор негодного текста разметки заново
		ASSERT_FALSE(doc.parse("<a>\n<b>\n<битый"));
		// Выполняем запись дерева разметки, разбором не заведённого
		ASSERT_TRUE(doc.dump().empty());
		/**
		 * Выполняем проверку того, что запись поставила СВОЙ код отказа
		 *
		 * @note Дерево пусто, и записывать нечего, - код обязан быть об этом, а не об
		 *       отказе разбора, ему предшествовавшем
		 */
		ASSERT_EQ(doc.error(), xml::error_t::MISSING_ROOT);
		// Выполняем проверку сброса положения отказа записью
		ASSERT_EQ(doc.errorLocation().line, static_cast <size_t> (0));
	}
	/**
	 * Сброс донесения сносом узла дерева разметки
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем разбор негодного текста разметки
		ASSERT_FALSE(doc.parse("<a>\n<b>\n<битый"));
		// Выполняем разбор годного текста разметки, донесение притом сбрасывая
		ASSERT_TRUE(doc.parse("<a><b/></a>"));
		// Выполняем разбор негодного текста разметки заново
		ASSERT_FALSE(doc.parse("<a>\n<b>\n<битый"));
		// Выполняем повторный разбор годного текста разметки
		ASSERT_TRUE(doc.parse("<a><b/></a>"));
		/**
		 * Выполняем негодный разбор ради постановки кода и положения
		 *
		 * @note Разбор этот дерево ОЧИЩАЕТ, оттого следом и ведётся годный: снос
		 *       обязан сбрасывать донесение на дереве, узлы имеющем
		 */
		ASSERT_FALSE(doc.parse("<a><b/></a>x<c/>"));
		// Выполняем проверку постановки кода отказа разбора
		ASSERT_NE(doc.error(), xml::error_t::NONE);
		// Выполняем прививку собранного значения корнем дерева разметки
		ASSERT_TRUE(doc.set("", xml::value_t("a")));
		// Выполняем прививку вложенного узла разметки
		ASSERT_TRUE(doc.set("/a", xml::value_t("b")));
		// Выполняем негодную правку ради постановки кода отказа
		ASSERT_FALSE(doc.set("", xml::value_t(xml::kind_t::TEXT, "текст")));
		// Выполняем проверку постановки кода отказа правки
		ASSERT_EQ(doc.error(), xml::error_t::MISSING_ROOT);
		// Выполняем снос узла разметки по пути
		ASSERT_TRUE(doc.erase("/b"));
		// Выполняем проверку сброса кода отказа удавшимся сносом
		ASSERT_EQ(doc.error(), xml::error_t::NONE);
	}
	/**
	 * Сброс донесения сбросом содержимого узла дерева разметки
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем разбор текста разметки
		ASSERT_TRUE(doc.parse("<a><b/></a>"));
		// Выполняем негодную правку ради постановки кода отказа
		ASSERT_FALSE(doc.set("", xml::value_t(xml::kind_t::TEXT, "текст")));
		// Выполняем проверку постановки кода отказа правки
		ASSERT_EQ(doc.error(), xml::error_t::MISSING_ROOT);
		// Выполняем сброс содержимого корневого узла разметки
		ASSERT_TRUE(doc.reset(""));
		// Выполняем проверку сброса кода отказа удавшимся сбросом содержимого
		ASSERT_EQ(doc.error(), xml::error_t::NONE);
	}
	/**
	 * Донесение документа
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем разбор негодного текста документа
		ASSERT_FALSE(doc.parse("{\n\"a\":\n битый"));
		// Выполняем проверку положения отказа разбора
		ASSERT_EQ(doc.errorLocation().line, static_cast <size_t> (3));
		// Выполняем прививку значения корнем документа
		ASSERT_TRUE(doc.set("", json::value_t(static_cast <int64_t> (1))));
		// Выполняем проверку сброса кода отказа удавшейся прививкой
		ASSERT_EQ(doc.error(), json::error_t::NONE);
		// Выполняем проверку сброса положения отказа удавшейся прививкой
		ASSERT_EQ(doc.errorLocation().line, static_cast <size_t> (0));
	}
	/**
	 * Донесение таблицы
	 */
	{
		// Объект таблицы
		csv::document_t doc(::logger());
		// Выполняем разбор негодного текста таблицы
		ASSERT_FALSE(doc.parse("a,b\r\n1,\"б"));
		// Выполняем проверку положения отказа разбора
		ASSERT_EQ(doc.errorLocation().line, static_cast <size_t> (2));
		// Выполняем установку заголовка таблицы
		doc.header(vector <string> {"a"});
		// Выполняем добавление записи таблицы
		doc.append(vector <string> {"1"});
		// Выполняем запись текста таблицы
		ASSERT_FALSE(doc.dump().empty());
		// Выполняем проверку сброса кода отказа удавшейся записью
		ASSERT_EQ(doc.error(), csv::error_t::NONE);
		// Выполняем проверку сброса положения отказа удавшейся записью
		ASSERT_EQ(doc.errorLocation().line, static_cast <size_t> (0));
	}
	/**
	 * Донесение документа ABC
	 *
	 * @note Место отказа у ABC меряется СМЕЩЕНИЕМ в октетах, а не строкой и столбцом:
	 *       строк у двоичной записи нет. Мера своя, а договор общий - место обязано
	 *       ставиться заново всякой работе наравне с кодом
	 *
	 * @warning Отсутствие места здесь пишется НЕ нулём, а `NO_OFFSET`: нуль есть
	 *          законное смещение - первый октет записи, - и отказ на нём был бы
	 *          неотличим от отсутствия отказа, пиши сброс нулём. Проверка потому и
	 *          наводит отказ на записи `A1`, где место равно ЕДИНИЦЕ, а не нулю
	 */
	{
		// Объект владеющего значения
		abc::value_t root;
		// Выполняем набор годной записи
		ASSERT_TRUE(root.insert(abc::value_t(string("a")), abc::value_t(int64_t(1))));
		// Выполняем сборку годной двоичной записи
		const vector <uint8_t> record = root.dump();
		// Запись, отказ на которой настигает разбор на середине
		const uint8_t corrupted = 0xA1;
		// Объект документа
		abc::document_t doc(::logger());
		// Выполняем разбор негодной записи документа
		ASSERT_FALSE(doc.parse(&corrupted, sizeof(corrupted)));
		// Выполняем проверку кода отказа разбора
		ASSERT_EQ(doc.error(), abc::error_t::UNEXPECTED_EOF) << abc::message(doc.error());
		// Выполняем проверку положения отказа разбора
		ASSERT_EQ(doc.errorLocation().offset, static_cast <uint64_t> (1));
		// Выполняем удавшийся разбор годной записи документа
		ASSERT_TRUE(doc.parse(record.data(), record.size())) << abc::message(doc.error());
		// Выполняем проверку сброса кода отказа удавшимся разбором
		ASSERT_EQ(doc.error(), abc::error_t::NONE) << abc::message(doc.error());
		// Выполняем проверку сброса положения отказа удавшимся разбором
		ASSERT_EQ(doc.errorLocation().offset, abc::NO_OFFSET);
	}
	/**
	 * Выполняем закрепление донесения у ВЛАДЕЮЩЕГО ЗНАЧЕНИЯ таблицы
	 *
	 * @details Канал донесения есть у каждого владеющего значения, и договор записан
	 *          у них общим: разбор текста, чтение файла, выдача текста и запись его
	 *          в файл ставят код заново каждая. Без него пустой текст выдачи
	 *          неотличим от значения пустого
	 *
	 * @note Значение таблицы завелось позже прочих, и канала этого у него не было
	 *       ВОВСЕ - недосмотр вскрыт сличением состава: договор у соседей прямо
	 *       называет таблицу CSV отвечающей тем же порядком, а отвечать ей было нечем
	 *
	 * @warning Сброс ведётся в НАЧАЛЕ работы, а не при её успехе: оставь мы прежний
	 * код, и потребитель, сличающий его после работы удавшейся, читал бы отказ работы
	 * предыдущей - молча и без знака
	 */
	{
		// Владеющее значение таблицы
		csv::value_t value;
		// Выполняем проверку чистоты донесения у значения нового
		ASSERT_EQ(value.error(), csv::error_t::NONE);
		// Объект таблицы для получения настроек разбора
		csv::document_t document(::logger());
		// Получаем настройки таблицы
		auto settings = document.settings();
		// Выполняем указание на присутствие заголовка в первой записи
		settings.reader.header = csv::header_t::PRESENT;
		/**
		 * Выполняем проверку отказа разбора текста с незакрытой кавычкой
		 */
		ASSERT_FALSE(value.parse("имя\r\n\"незакрытая\r\n", settings));
		// Выполняем проверку кода отказа разбора текста таблицы
		ASSERT_EQ(value.error(), csv::error_t::UNTERMINATED_QUOTE);
		// Выполняем проверку того, что отказ назвал строку текста
		ASSERT_GT(value.errorLocation().line, static_cast <uint32_t> (0));
		/**
		 * Выполняем проверку того, что успешная работа донесение СБРАСЫВАЕТ
		 */
		ASSERT_TRUE(value.parse("имя\r\nАня\r\n", settings));
		// Выполняем проверку чистоты донесения после работы удавшейся
		ASSERT_EQ(value.error(), csv::error_t::NONE);
		/**
		 * Выполняем проверку донесения при выдаче текста у значения, таблицею не
		 * являющегося
		 *
		 * @note Ровно та беда, ради которой канал и заведён: без кода пустой текст
		 *       выдачи неотличим от таблицы пустой
		 */
		{
			// Владеющее значение поля таблицы
			csv::value_t field(string("текст"));
			// Выполняем проверку пустоты выдачи у значения, таблицею не являющегося
			ASSERT_TRUE(field.dump().empty());
			// Выполняем проверку того, что пустота выдачи объяснена кодом отказа
			ASSERT_NE(field.error(), csv::error_t::NONE);
		}
		/**
		 * Выполняем проверку донесения при отказе сохранения в файл
		 */
		ASSERT_FALSE(value.save(""));
		// Выполняем проверку кода отказа сохранения таблицы в файл
		ASSERT_EQ(value.error(), csv::error_t::FILE_NOT_OPENED);
		/**
		 * Выполняем проверку того, что УСПЕШНОЕ сохранение донесение сбрасывает
		 *
		 * @note Случай этот закрепляет договор с другой стороны: работа удавшаяся
		 *       обязана донесение ОЧИСТИТЬ, а не оставить прежним
		 *
		 * @warning Проверка эта подмену сброса в самом сохранении НЕ ловит, и сказано
		 * это прямо, чтобы зелёное не приняли за покрытие. Причина не в дыре проверки,
		 * а в устройстве: сохранение собирает текст выдачею, а выдача сбрасывает
		 * донесение первым же действием - сброс в сохранении оттого ДУБЛИРУЕТСЯ и
		 * подменою безвреден. Держится он на месте нарочно: перестань выдача
		 * сбрасывать, и сохранение осталось бы единственным сторожем договора
		 */
		{
			// Адрес временного файла проверки
			const string target = "./contract-csv-value-error.csv";
			// Сторож временного файла проверки
			struct Guard {
				// Адрес стерегомого файла
				string filename;
				// Деструктор сторожа
				~Guard() noexcept { ::remove(this->filename.c_str()); }
			} guard{target};
			// Выполняем снос файла, пережившего прошлый прогон
			::remove(target.c_str());
			// Выполняем проверку успешности сохранения таблицы в файл
			ASSERT_TRUE(value.save(target));
			// Выполняем проверку того, что успешная запись донесение сбросила
			ASSERT_EQ(value.error(), csv::error_t::NONE);
		}
	}
}
/**
 * @brief Счёт детей корня отделён от счёта узлов хранилища
 *
 * @details Хранилища кодеков ведут себя по-разному: у одних дописываются и сносом не
 * убавляются, у других сжимаются, у третьих дерева правке не подлежат вовсе. Смысла
 * одного «узлы хранилища» у семерых иметь потому не могут, тогда как «дети корня»
 * определимы у всех одинаково, - оттого `size()` отведён детям, а `nodes()` хранилищу
 *
 * @note Замер, разведение это оправдавший: у документа JSON снос поля хранилище УБАВЛЯЕТ
 *       (53 -> 52), а у дерева разметки снос узла не убавляет его вовсе - узлы остаются
 *       в арене недостижимыми. Одно имя на две такие величины лгало бы у одного из двух
 *
 * @note У отображения `size()` считает ПАРЫ, а не звенья: два поля дают 2, а не 4. Кодек
 *       ABC держится того же правила
 *
 */
TEST(CodecContract, ChildCountIsSeparatedFromStorageCount) {
	/**
	 * Счёт у документа
	 *
	 * @note Дерево взято так, чтобы величины РАСХОДИЛИСЬ: объект о двух полях, второе из
	 *       коих несёт вложенный объект. Совпади они - щуп был бы слеп, и подмена одной
	 *       величины другою прошла бы молча
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем разбор текста документа
		ASSERT_TRUE(doc.parse("{\"a\":1,\"b\":{\"c\":2}}"));
		// Выполняем проверку количества значений в корне документа
		ASSERT_EQ(doc.size(), static_cast <size_t> (2));
		// Выполняем проверку того, что счёт узлов хранилища величина ИНАЯ
		ASSERT_GT(doc.nodes(), doc.size());
		// Выполняем разбор текста документа с массивом
		ASSERT_TRUE(doc.parse("[1,2,3]"));
		// Выполняем проверку количества значений в корне документа
		ASSERT_EQ(doc.size(), static_cast <size_t> (3));
		// Выполняем разбор текста документа со скалярным корнем
		ASSERT_TRUE(doc.parse("1"));
		// Выполняем проверку отсутствия детей у скалярного корня
		ASSERT_EQ(doc.size(), static_cast <size_t> (0));
		// Выполняем проверку того, что узел хранилища при том есть
		ASSERT_EQ(doc.nodes(), static_cast <size_t> (1));
	}
	/**
	 * Счёт у дерева разметки
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем разбор текста разметки
		ASSERT_TRUE(doc.parse("<r><a/><b><c/></b></r>"));
		// Выполняем проверку количества вложенных узлов корня разметки
		ASSERT_EQ(doc.size(), static_cast <size_t> (2));
		// Выполняем проверку количества узлов арены дерева
		ASSERT_EQ(doc.nodes(), static_cast <size_t> (5));
		// Выполняем проверку счёта детей у самого узла разметки
		ASSERT_EQ(doc.at("/r/b").size(), static_cast <size_t> (1));
		// Выполняем проверку отсутствия детей у пустого узла разметки
		ASSERT_EQ(doc.at("/r/a").size(), static_cast <size_t> (0));
	}
	/**
	 * Счёт у таблицы
	 *
	 * @note Детьми корня у таблицы служат записи её, и `size()` выдаёт их посредником к
	 *       `rows()`. Хода `nodes()` у неё нет вовсе: арены узлов таблица не держит, и
	 *       выдумывать величину под общее имя было бы хуже её отсутствия
	 */
	{
		// Объект таблицы
		csv::document_t doc(::logger());
		// Получаем настройки таблицы
		csv::document_t::settings_t settings = doc.settings();
		// Устанавливаем наличие заголовка у разбираемой таблицы
		settings.reader.header = csv::header_t::PRESENT;
		// Выполняем установку настроек таблицы
		doc.settings(settings);
		// Выполняем разбор текста таблицы
		ASSERT_TRUE(doc.parse("имя,возраст\r\nАня,7\r\nБорис,8\r\n"));
		/**
		 * Выполняем проверку счёта записей таблицы
		 *
		 * @note Заголовок записью не считается: строк в тексте три, а записей две
		 */
		ASSERT_EQ(doc.size(), static_cast <size_t> (2));
		// Выполняем проверку совпадения счёта записей с ходом `rows()`
		ASSERT_EQ(doc.size(), doc.rows());
		/**
		 * Выполняем проверку счёта полей записи
		 *
		 * @note Довод указывает, ЧЬИХ детей считать, - ровно как `at(путь).size()` у дерева
		 */
		ASSERT_EQ(doc.size(0), static_cast <size_t> (2));
	}
	/**
	 * Снос убавляет детей корня у обоих кодеков, а хранилище - лишь у одного
	 *
	 * @note Расхождение это законное и приведению не подлежит: арена дерева разметки
	 *       намеренно лишь дописывается, ибо перенумерование узлов обесценило бы всякую
	 *       ссылку, наружу выданную. Оно же и есть довод развести две величины
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем разбор текста документа
		ASSERT_TRUE(doc.parse("{\"a\":1,\"b\":2,\"c\":3}"));
		// Запоминаем счёт узлов хранилища до сноса
		const size_t before = doc.nodes();
		// Выполняем снос поля объекта
		ASSERT_TRUE(doc.erase("/b"));
		// Выполняем проверку убавления числа полей объекта
		ASSERT_EQ(doc.size(), static_cast <size_t> (2));
		// Выполняем проверку убавления хранилища документа сносом
		ASSERT_LT(doc.nodes(), before);
	}
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем разбор текста разметки
		ASSERT_TRUE(doc.parse("<r><a/><b/><c/></r>"));
		// Запоминаем счёт узлов арены до сноса
		const size_t before = doc.nodes();
		// Выполняем снос узла разметки
		ASSERT_TRUE(doc.erase("/r/b"));
		// Выполняем проверку убавления числа детей корня разметки
		ASSERT_EQ(doc.size(), static_cast <size_t> (2));
		// Выполняем проверку того, что арена дерева сносом НЕ убавилась
		ASSERT_EQ(doc.nodes(), before);
	}
	/**
	 * Счёт у дерева разбора двоичного контейнера
	 *
	 * @note Запись ABC двоична, оттого дерево собирается владеющим значением и выдаётся
	 *       октетами, а не подаётся текстом. Величины взяты расходящимися по тому же
	 *       доводу: отображение о двух парах, вторая из коих несёт вложенное отображение
	 *
	 * @note Хранилище ABC держится до самой очистки и сносом не убавляется - третий род
	 *       поведения после сжимающегося у JSON и лишь дописывающегося у разметки. Тем
	 *       разведение и оправдано окончательно
	 */
	{
		// Собираемое значение двоичного контейнера
		abc::value_t root, nested;
		// Выполняем заведение вложенного отображения
		ASSERT_TRUE(nested.insert(abc::value_t(string("c")), abc::value_t(int64_t(2))));
		// Выполняем заведение первого поля корня
		ASSERT_TRUE(root.insert(abc::value_t(string("a")), abc::value_t(int64_t(1))));
		// Выполняем заведение второго поля корня вложенным отображением
		ASSERT_TRUE(root.insert(abc::value_t(string("b")), nested));
		// Выполняем выдачу собранной записи октетами
		const vector <uint8_t> record = root.dump();
		// Объект дерева разбора двоичного контейнера
		abc::document_t doc(::logger());
		// Выполняем разбор собранной записи
		ASSERT_TRUE(doc.parse(record.data(), record.size())) << abc::message(doc.error());
		/**
		 * Выполняем проверку количества значений в корне документа
		 *
		 * @note У отображения счёт идёт ПАРАМИ: два поля дают 2, а не 4
		 */
		ASSERT_EQ(doc.size(), static_cast <size_t> (2));
		// Выполняем проверку того, что счёт узлов хранилища величина ИНАЯ
		ASSERT_GT(doc.nodes(), doc.size());
		/**
		 * Выполняем поверку перечня
		 */
		{
			// Собираемый перечень значений
			abc::value_t listing;
			/**
			 * Выполняем заведение трёх значений перечня
			 */
			for(size_t i = 0; i < 3; i++)
				// Выполняем заведение очередного значения перечня
				ASSERT_TRUE(listing.push(abc::value_t(static_cast <int64_t> (i))));
			// Выполняем выдачу собранного перечня октетами
			const vector <uint8_t> packed = listing.dump();
			// Выполняем разбор собранного перечня
			ASSERT_TRUE(doc.parse(packed.data(), packed.size())) << abc::message(doc.error());
			// Выполняем проверку количества значений в корне документа
			ASSERT_EQ(doc.size(), static_cast <size_t> (3));
		}
		/**
		 * Выполняем поверку скалярного корня
		 */
		{
			// Выполняем выдачу скалярного значения октетами
			const vector <uint8_t> single = abc::value_t(int64_t(1)).dump();
			// Выполняем разбор скалярного значения
			ASSERT_TRUE(doc.parse(single.data(), single.size())) << abc::message(doc.error());
			// Выполняем проверку отсутствия детей у скалярного корня
			ASSERT_EQ(doc.size(), static_cast <size_t> (0));
			// Выполняем проверку того, что узел хранилища при том есть
			ASSERT_EQ(doc.nodes(), static_cast <size_t> (1));
		}
	}
}
/**
 * @brief Звено пути толкуется видом вместилища, а не видом записи звена
 *
 * @details Договор согласован владельцами кодеков 03.09.2026 и равняется на RFC 6901. У
 * ОБЪЕКТА звено пути есть ИМЯ ЧЛЕНА всегда, хотя бы и записанное цифрами. У МАССИВА звено
 * есть номер, и номер с ведущим нулём негоден (раздел 4 стандарта): без того `01` и `1`
 * означали бы одно и то же, и путь перестал бы задавать значение однозначно
 *
 * @note Половины эти РАЗНЫЕ, и держать надо обе. Проверка на один ведущий нуль дефекта
 * первого рода не ловит вовсе: `01` номером негоден почти всегда, оттого проходит верно
 * даже там, где простое `1` идёт мимо имени. А проверка на одно имя не ловит
 * перестаравшейся починки, отвергающей `01` и у объекта, где он законное имя члена
 *
 * @warning Расстановка полей здесь ОБРАТНА их числам намеренно: имя «1» стоит первым
 * (место 0), имя «0» вторым (место 1). Совпади имя с местом - и «нашло по имени» стало бы
 * неотличимо от «взяло по номеру», а проверка была бы зелёной при живом отступлении.
 * Замер 03.09.2026: у ABC щуп с совпадающей расстановкой показал зелёное, тогда как
 * `at("m/1")` отдавал поле «0» - не то МОЛЧА, что хуже отказа
 *
 * @note Наличие спрашивается через `at(path).valid()`, а не через `has(path)`, и это
 * намеренно: договор наш о ПОВЕДЕНИИ, а не о написании. У INI хода `has(путь)` нет и не
 * будет - там уже есть `has(ключ, раздел, подраздел)`, и новый ход с одним доводом дал бы
 * двусмысленность, при какой `has("/a/b")` ЛИТЕРАЛОМ ушёл бы в старый ход, принял бы это
 * за имя ключа и молча ответил «нет». Ход, у какого литерал работает не так, как
 * переменная, хуже отсутствия хода, и отказ заводить его - решение верное, а не пробел
 *
 * @note Выдача `at()` у кодеков РАЗНАЯ по устройству, и ровнять её не надо: YAML, JSON,
 * XML и ABC выдают узел дерева, TOML и INI - владеющее значение, ибо узлового вида у них
 * нет вовсе. Оттого проверка спрашивает годность да содержимое, а не вид выдачи
 *
 * @note Отступление у YAML этой проверкой и было найдено 03.09.2026, при вводе кодека в
 * перебор: ведущий нуль там не отвергался вовсе, а разбирался ЧИСЛОМ - `01` давало 1,
 * `007` давало 7. Отказ приходил лишь от выхода за предел перечня, и оттого прежняя
 * проверка кодека, бравшая перечень из ДВУХ значений, была зелена при живом отступлении.
 * Решающий замер - один и тот же путь при разной длине перечня: из трёх `/list/007`
 * valid=0, из девяти valid=1. Причина - разбор номера был СВОЙ у каждого из двух взглядов
 * кодека (помощник у владеющего значения, прямой `strtoull` у узла дерева), и правка
 * одного правила целиком не закрывала. Исправлено владельцем кодека
 *
 * @note Кодек CSV в переборе не участвует по устройству: таблица путей не знает вовсе
 *
 * @warning Записано это здесь намеренно, а не оставлено в переписке: молчаливое отсутствие
 * кодека в общей проверке неотличимо от его согласия с договором, а ради обратного файл и
 * заведён
 *
 */
TEST(CodecContract, PathSegmentIsJudgedByTheContainerAndNotByItsSpelling) {
	/**
	 * Договор у документа JSON
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		/**
		 * Выполняем разбор текста, где имена полей ОБРАТНЫ их местам
		 */
		ASSERT_TRUE(doc.parse("{\"m\":{\"1\":\"по-имени-1\",\"0\":\"по-имени-0\",\"01\":\"по-имени-01\"},\"a\":[\"эл-0\",\"эл-1\",\"эл-2\"]}"))
			<< json::message(doc.error());
		// У объекта звено пути обязано быть ИМЕНЕМ члена
		ASSERT_TRUE(doc.has("/m/1"));
		// Имя, записанное цифрою, обязано вести к своему полю, а не к значению по месту
		ASSERT_TRUE(doc.has("/m/0"));
		/**
		 * Имя с ведущим нулём у ОБЪЕКТА законно и обязано быть найдено
		 *
		 * @note Половина эта ловит перестаравшуюся починку: запрет ведущего нуля,
		 *       положенный ДО разбора вида вместилища, сделал бы поле «01» недостижимым
		 */
		ASSERT_TRUE(doc.has("/m/01"));
		// У массива звено пути обязано быть номером
		ASSERT_TRUE(doc.has("/a/0"));
		// Номер обязан вести к своему значению и далее
		ASSERT_TRUE(doc.has("/a/2"));
		// Номер с ведущим нулём у массива негоден по RFC 6901
		ASSERT_FALSE(doc.has("/a/01"));
		// Номер за пределом массива обязан быть отвергнут
		ASSERT_FALSE(doc.has("/a/9"));
	}
	/**
	 * Договор у дерева разбора двоичного контейнера
	 *
	 * @note Запись ABC двоична, оттого дерево собирается владеющим значением и выдаётся
	 *       октетами, а не подаётся текстом
	 */
	{
		// Собираемое значение двоичного контейнера
		abc::value_t root, mapping, listing;
		// Выполняем заведение поля, чьё имя «1», ПЕРВЫМ - на место 0
		ASSERT_TRUE(mapping.insert(abc::value_t(string("1")), abc::value_t(string("по-имени-1"))));
		// Выполняем заведение поля, чьё имя «0», ВТОРЫМ - на место 1
		ASSERT_TRUE(mapping.insert(abc::value_t(string("0")), abc::value_t(string("по-имени-0"))));
		// Выполняем заведение поля, чьё имя записано с ведущим нулём
		ASSERT_TRUE(mapping.insert(abc::value_t(string("01")), abc::value_t(string("по-имени-01"))));
		/**
		 * Выполняем заведение трёх значений перечня
		 */
		for(size_t i = 0; i < 3; i++)
			// Выполняем заведение очередного значения перечня
			ASSERT_TRUE(listing.push(abc::value_t(string("эл-") + to_string(i))));
		// Выполняем заведение отображения полем корня
		ASSERT_TRUE(root.insert(abc::value_t(string("m")), mapping));
		// Выполняем заведение перечня полем корня
		ASSERT_TRUE(root.insert(abc::value_t(string("a")), listing));
		// Выполняем выдачу собранной записи октетами
		const vector <uint8_t> record = root.dump();
		// Объект дерева разбора двоичного контейнера
		abc::document_t doc(::logger());
		// Выполняем разбор собранной записи
		ASSERT_TRUE(doc.parse(record.data(), record.size())) << abc::message(doc.error());
		/**
		 * У отображения звено пути обязано быть ИМЕНЕМ поля
		 *
		 * @note Здесь и красится отступление: возьми обход номер вместо имени - и путь
		 *       `/m/1` отдаст поле «0», ибо оно лежит на месте 1
		 */
		ASSERT_TRUE(doc.has("/m/1"));
		// Содержимое обязано отвечать ИМЕНИ, а не месту
		ASSERT_EQ(string(doc.at("/m/1").data()), string("по-имени-1"));
		// То же и у второго поля
		ASSERT_EQ(string(doc.at("/m/0").data()), string("по-имени-0"));
		/**
		 * Имя с ведущим нулём у ОТОБРАЖЕНИЯ законно и обязано быть найдено
		 *
		 * @note Половина эта ловит перестаравшуюся починку: запрет ведущего нуля,
		 *       положенный ДО разбора вида вместилища, сделал бы поле «01» недостижимым
		 */
		ASSERT_EQ(string(doc.at("/m/01").data()), string("по-имени-01"));
		// У перечня звено пути обязано быть номером
		ASSERT_EQ(string(doc.at("/a/0").data()), string("эл-0"));
		// Номер обязан вести к своему значению и далее
		ASSERT_EQ(string(doc.at("/a/2").data()), string("эл-2"));
		// Номер с ведущим нулём у перечня негоден по RFC 6901
		ASSERT_FALSE(doc.has("/a/01"));
		// Номер за пределом перечня обязан быть отвергнут
		ASSERT_FALSE(doc.has("/a/9"));
	}
	/**
	 * Договор у документа TOML
	 *
	 * @note Наличие спрашивается через `at(path).valid()`: у TOML выдаётся владеющее
	 *       значение, а не узел дерева, и вид выдачи договором не поверяется
	 */
	{
		// Объект документа
		toml::document_t doc(::logger());
		/**
		 * Выполняем разбор текста, где имена ключей ОБРАТНЫ их местам
		 */
		ASSERT_TRUE(doc.parse("[r]\n\"1\" = \"по-имени-1\"\n\"0\" = \"по-имени-0\"\n\"01\" = \"по-имени-01\"\nlist = [\"эл-0\",\"эл-1\",\"эл-2\"]\n"))
			<< toml::message(doc.error());
		// У таблицы звено пути обязано быть ИМЕНЕМ ключа
		ASSERT_TRUE(doc.at("/r/1").valid());
		// Имя, записанное цифрою, обязано вести к своему ключу, а не к значению по месту
		ASSERT_TRUE(doc.at("/r/0").valid());
		/**
		 * Имя с ведущим нулём у ТАБЛИЦЫ законно и обязано быть найдено
		 */
		ASSERT_TRUE(doc.at("/r/01").valid());
		// У перечня звено пути обязано быть номером
		ASSERT_TRUE(doc.at("/r/list/0").valid());
		// Номер обязан вести к своему значению и далее
		ASSERT_TRUE(doc.at("/r/list/2").valid());
		// Номер с ведущим нулём у перечня негоден по RFC 6901
		ASSERT_FALSE(doc.at("/r/list/01").valid());
		// Номер за пределом перечня обязан быть отвергнут
		ASSERT_FALSE(doc.at("/r/list/9").valid());
	}
	/**
	 * Договор у документа INI
	 *
	 * @note Перечней у настроек нет вовсе, оттого половина про номер здесь не поверяется:
	 *       поверять её было бы не на чем. Половина про имя поверяется целиком
	 */
	{
		// Объект документа
		ini::document_t doc(::logger());
		/**
		 * Выполняем разбор текста, где имена ключей ОБРАТНЫ их местам
		 */
		ASSERT_TRUE(doc.parse("[r]\n1 = по-имени-1\n0 = по-имени-0\n01 = по-имени-01\n"))
			<< ini::message(doc.error());
		// У раздела звено пути обязано быть ИМЕНЕМ ключа
		ASSERT_TRUE(doc.at("/r/1").valid());
		// Имя, записанное цифрою, обязано вести к своему ключу, а не к значению по месту
		ASSERT_TRUE(doc.at("/r/0").valid());
		/**
		 * Имя с ведущим нулём у РАЗДЕЛА законно и обязано быть найдено
		 */
		ASSERT_TRUE(doc.at("/r/01").valid());
		// Ключа, какого в разделе нет, найтись не должно
		ASSERT_FALSE(doc.at("/r/9").valid());
	}
	/**
	 * Договор у документа YAML
	 *
	 * @note Перечень здесь взят из ДЕВЯТИ значений намеренно, и в том вся сила проверки.
	 *       Возьми перечень короче разбираемого номера - и `07` отверглось бы по ВЫХОДУ ЗА
	 *       ПРЕДЕЛ, а не по ведущему нулю, то есть верный и неверный ответы совпали бы.
	 *       Ровно на этом прежняя проверка кодека и была зелена при живом отступлении:
	 *       перечень был из двух значений
	 *
	 * @note Спрашивается сперва `/list/7` - он обязан быть НАЙДЕН, - и лишь затем `/list/07`
	 *       и `/list/007`, обязанные быть отвергнутыми. Без первого вопроса отказ у двух
	 *       последних ничего не значил бы: он мог бы прийти от чего угодно
	 */
	{
		// Объект документа
		yaml::document_t doc(::logger());
		/**
		 * Выполняем разбор текста, где имена ключей обратны их местам, а перечень заведомо
		 * длиннее всякого разбираемого здесь номера
		 */
		ASSERT_TRUE(doc.parse(
		 "r:\n  \"1\": по-имени-1\n  \"0\": по-имени-0\n  \"01\": по-имени-01\n"
		 "list:\n  - эл-0\n  - эл-1\n  - эл-2\n  - эл-3\n  - эл-4\n  - эл-5\n  - эл-6\n  - эл-7\n  - эл-8\n"))
			<< yaml::message(doc.error());
		// У отображения звено пути обязано быть ИМЕНЕМ ключа
		ASSERT_TRUE(doc.at("/r/1").valid());
		// Имя, записанное цифрою, обязано вести к своему ключу, а не к значению по месту
		ASSERT_TRUE(doc.at("/r/0").valid());
		/**
		 * Имя с ведущим нулём у ОТОБРАЖЕНИЯ законно и обязано быть найдено
		 */
		ASSERT_TRUE(doc.at("/r/01").valid());
		/**
		 * Номер, достижимый в перечне, обязан быть найден
		 *
		 * @note Вопрос этот стоит ПЕРЕД вопросами о ведущем нуле и держит их: отвергни
		 *       кодек `07` при недостижимом `7` - и отказ ничего бы не доказывал
		 */
		ASSERT_TRUE(doc.at("/list/7").valid());
		// Номер с ведущим нулём негоден по RFC 6901, хотя бы значение по нему и было
		ASSERT_FALSE(doc.at("/list/07").valid());
		// Ведущие нули числом не сводятся ни при какой их длине
		ASSERT_FALSE(doc.at("/list/007").valid());
		// Номер за пределом перечня обязан быть отвергнут
		ASSERT_FALSE(doc.at("/list/9").valid());
	}
}
/**
 * @brief Итог разбора не зависит от нарезки текста на куски
 *
 * @details Потоковый разбор ведётся подачею кусков произвольного размера, и граница
 * куска вправе рассечь ЧТО УГОДНО: имя, число, последовательность UTF-8, знак
 * экранирования, перевод строки `\r\n`. Разбор, границу эту не переживший, отдаёт иные
 * события либо иное содержимое их, - и порок этот виден лишь сличением НЕСКОЛЬКИХ
 * нарезок между собой, ибо каждая порознь выглядит стройно
 *
 * @note Проверка эта общая намеренно: у каждого кодека своя такая уже есть, да строгость
 *       у них разная, - и договор, порознь исполненный, расходится тихо. Сличается всякий
 *       размер куска от единицы до длины текста, то есть и подача по одному октету
 *
 * @note Уклад подачи един у всех трёх: `feed()`, затем перебор `while(next())` со снятием
 *       `event()`. Обработчик, у документа JSON заведённый, есть путь ДОПОЛНИТЕЛЬНЫЙ,
 *       а не замена этому
 *
 */
TEST(CodecContract, ParsingIsIndependentOfTheChunking) {
	/**
	 * @brief Метод сбора событий разбора текста документа заданной нарезкой
	 *
	 * @param text  разбираемый текст документа
	 * @param chunk размер куска подачи
	 * @return      собранная выдача событий разбора
	 *
	 */
	auto json_events = [](const string & text, const size_t chunk) noexcept -> string {
		// Чтение текста документа
		json::reader_t reader(::logger());
		// Собранная выдача событий разбора
		string result;
		/**
		 * Выполняем подачу текста документа кусками заданного размера
		 */
		for(size_t offset = 0; offset < text.size(); offset += chunk){
			// Получаем размер очередного куска подачи
			const size_t size = min(chunk, text.size() - offset);
			// Выполняем подачу очередного куска текста документа
			reader.feed(text.data() + offset, size, ((offset + size) >= text.size()));
			/**
			 * Выполняем перебор всех собранных событий разбора
			 */
			while(reader.next())
				// Выполняем добавление вида события и содержимого его к выдаче
				result.append(std::to_string(static_cast <uint16_t> (reader.event())))
				      .append("[").append(reader.value().text).append("]");
		}
		// Выводим собранную выдачу событий разбора
		return result;
	};
	/**
	 * @brief Метод сбора событий разбора текста разметки заданной нарезкой
	 *
	 * @param text  разбираемый текст разметки
	 * @param chunk размер куска подачи
	 * @return      собранная выдача событий разбора
	 *
	 */
	auto xml_events = [](const string & text, const size_t chunk, const bool merge = true) noexcept -> string {
		// Настройки чтения текста разметки
		xml::reader_t::settings_t settings;
		/**
		 * Устанавливаем склеивание подряд идущих кусков текстового содержимого
		 *
		 * @note Признак этот поднимается намеренно: при опущенном граница подачи содержимое
		 *       РАЗРЫВАЕТ, и разбор по одному октету выдаёт текстовый узел по знакам. Свойство
		 *       это законное и записано доводом: текстовый узел разметки пределами настроек не
		 *       ограничен вовсе, и склейка без предела съела бы память на потоке без конца
		 */
		settings.mergeText = merge;
		// Чтение текста разметки
		xml::reader_t reader(::logger(), settings);
		// Собранная выдача событий разбора
		string result;
		/**
		 * Выполняем подачу текста разметки кусками заданного размера
		 */
		for(size_t offset = 0; offset < text.size(); offset += chunk){
			// Получаем размер очередного куска подачи
			const size_t size = min(chunk, text.size() - offset);
			// Выполняем подачу очередного куска текста разметки
			reader.feed(text.data() + offset, size, ((offset + size) >= text.size()));
			/**
			 * Выполняем перебор всех собранных событий разбора
			 */
			while(reader.next())
				// Выполняем добавление вида события и содержимого его к выдаче
				result.append(std::to_string(static_cast <uint16_t> (reader.event())))
				      .append("[").append(reader.text()).append("]");
		}
		// Выводим собранную выдачу событий разбора
		return result;
	};
	/**
	 * @brief Метод сбора событий разбора текста таблицы заданной нарезкой
	 *
	 * @param text  разбираемый текст таблицы
	 * @param chunk размер куска подачи
	 * @return      собранная выдача событий разбора
	 *
	 */
	auto csv_events = [](const string & text, const size_t chunk) noexcept -> string {
		// Чтение текста таблицы
		csv::reader_t reader(::logger());
		// Собранная выдача событий разбора
		string result;
		/**
		 * Выполняем подачу текста таблицы кусками заданного размера
		 */
		for(size_t offset = 0; offset < text.size(); offset += chunk){
			// Получаем размер очередного куска подачи
			const size_t size = min(chunk, text.size() - offset);
			// Выполняем подачу очередного куска текста таблицы
			reader.feed(text.data() + offset, size, ((offset + size) >= text.size()));
			/**
			 * Выполняем перебор всех собранных событий разбора
			 */
			while(reader.next())
				// Выполняем добавление вида события и содержимого его к выдаче
				result.append(std::to_string(static_cast <uint16_t> (reader.event())))
				      .append("[").append(reader.field().value).append("]");
		}
		// Выводим собранную выдачу событий разбора
		return result;
	};
	/**
	 * Независимость разбора документа от нарезки
	 *
	 * @note Текст взят так, чтобы граница куска непременно рассекала опасные места:
	 *       запись числа, последовательность UTF-8 о двух октетах, знак экранирования
	 */
	{
		// Разбираемый текст документа
		const string text = "{\"имя\":\"зна\\u0447ение\",\"число\":-1.25e+3,\"список\":[true,null,\"я\"]}";
		// Выдача разбора текста документа целиком
		const string whole = json_events(text, text.size());
		// Выполняем проверку непустоты выдачи разбора
		ASSERT_FALSE(whole.empty());
		/**
		 * Выполняем перебор всех размеров куска подачи
		 */
		for(size_t chunk = 1; chunk < text.size(); chunk++)
			// Выполняем проверку совпадения выдачи разбора с разбором целиком
			ASSERT_EQ(json_events(text, chunk), whole) << "размер куска " << chunk;
	}
	/**
	 * Независимость разбора разметки от нарезки
	 */
	{
		// Разбираемый текст разметки
		const string text = "<r a='значение'><!-- примечание --><b>текст</b><![CDATA[дословно]]><c/></r>";
		// Выдача разбора текста разметки целиком
		const string whole = xml_events(text, text.size());
		// Выполняем проверку непустоты выдачи разбора
		ASSERT_FALSE(whole.empty());
		/**
		 * Выполняем перебор всех размеров куска подачи
		 */
		for(size_t chunk = 1; chunk < text.size(); chunk++)
			// Выполняем проверку совпадения выдачи разбора с разбором целиком
			ASSERT_EQ(xml_events(text, chunk), whole) << "размер куска " << chunk;
		/**
		 * Выполняем проверку того, что при ОПУЩЕННОЙ склейке содержимое разрывается
		 *
		 * @details Расхождение это с документом JSON да таблицей CSV законное и приведению
		 * не подлежит: у них содержимое ограничено пределами настроек, а текстовый узел
		 * разметки не ограничен вовсе, и склейка через границу подачи копила бы его без
		 * предела. Ведущему чтение с опущенной склейкой надлежит складывать куски самому
		 *
		 * @note Проверка эта стоит здесь ОБРАТНОЮ стороной той, что выше: покажи разбор с
		 *       опущенной склейкой ту же выдачу, что целиком, - и признак этот не значил бы
		 *       ничего, а вместе с ним и вся плата за него
		 */
		ASSERT_NE(xml_events(text, 1, false), whole);
	}
	/**
	 * Независимость разбора таблицы от нарезки
	 *
	 * @note Перевод строки взят из двух знаков намеренно: граница куска, меж ними
	 *       прошедшая, - самое опасное место разбора таблицы
	 */
	{
		// Разбираемый текст таблицы
		const string text = "имя,значение\r\nАня,\"поле, с запятой\"\r\nБорис,\"строка\r\nв кавычках\"\r\n";
		// Выдача разбора текста таблицы целиком
		const string whole = csv_events(text, text.size());
		// Выполняем проверку непустоты выдачи разбора
		ASSERT_FALSE(whole.empty());
		/**
		 * Выполняем перебор всех размеров куска подачи
		 */
		for(size_t chunk = 1; chunk < text.size(); chunk++)
			// Выполняем проверку совпадения выдачи разбора с разбором целиком
			ASSERT_EQ(csv_events(text, chunk), whole) << "размер куска " << chunk;
	}
	/**
	 * Независимость разбора от нарезки у кодека ABC
	 *
	 * @details Подача двоичная, а договор тот же самый: выдача событий обязана НЕ
	 *          ЗАВИСЕТЬ от того, какими кусками запись подана. У двоичного кодека
	 *          зависимость эта опаснее, чем у текстовых: там значение опознаётся по
	 *          разделителям, а здесь по МЕТКЕ ДЛИНЫ, и метка, разрезанная надвое, есть
	 *          ровно то место, где накопление куска расходится с разбором целиком
	 *
	 * @note Запись здесь взята нарочно РАЗНОРОДНАЯ - отображение, вложенное отображение,
	 *       перечень чисел и длинная строка, - ибо разные виды значений накапливаются
	 *       разными дорогами: у одних длина встроена в метку, у других лежит следом
	 *       отдельными октетами, и разрезать надвое можно как саму метку, так и длину
	 *
	 * @warning Сличается СЛЕД РАЗБОРА, а не итоговое дерево. Дерево совпало бы и при
	 *          разъехавшейся выдаче событий - оно собирается из них и сглаживает порядок,
	 *          - тогда как потребитель потокового разбирателя видит именно события
	 *
	 * @warning След несёт и МЕСТО разбора - смещение с глубиной, - а не одно лишь
	 *          содержимое события. Половина эта дописана по следам подмены, какая
	 *          проверку НЕ покрасила: сдвиг начала буфера на октет при усечении
	 *          разобранной части содержимого событий не трогает вовсе, а место разбора
	 *          уводит, и потребитель, донёсший место отказа выше по слоям, донёс бы
	 *          неверное. Без места проверка была слепа к целому разряду расхождений
	 */
	{
		/**
		 * Работа снятия следа разбора двоичной записи заданными кусками
		 */
		auto abc_events = [](const vector <uint8_t> & record, const size_t chunk) noexcept -> string {
			// Объект разбирателя двоичной записи
			abc::reader_t reader(::logger());
			// Собранная выдача событий разбора
			string result;
			/**
			 * Выполняем перебор всех кусков подаваемой записи
			 */
			for(size_t offset = 0; offset < record.size(); offset += chunk){
				// Получаем размер очередного куска подачи
				const size_t size = min(chunk, record.size() - offset);
				/**
				 * Если подача очередного куска отвечена отказом
				 */
				if(!reader.feed(record.data() + offset, size, ((offset + size) >= record.size()))){
					// Выполняем добавление признака отказа к выдаче
					result.append("ОТКАЗ").append(std::to_string(static_cast <uint16_t> (reader.error())));
					// Прекращаем перебор кусков подачи
					break;
				}
				/**
				 * Выполняем вычерпывание очереди событий разбирателя
				 */
				while(reader.next()){
					// Получаем значение очередного события разбора
					const abc::reader_t::value_t value = reader.value();
					// Выполняем добавление вида события и содержимого его к выдаче
					result.append(std::to_string(static_cast <uint16_t> (reader.event())))
					      .append("[").append(std::to_string(static_cast <uint32_t> (value.type)))
					      .append(":").append(std::to_string(value.count))
					      .append(":").append(std::to_string(value.integer))
					      .append("@").append(std::to_string(reader.location().offset))
					      .append("/").append(std::to_string(reader.location().depth)).append("]");
				}
			}
			// Выводим собранную выдачу событий разбора
			return result;
		};
		// Собираемые значения разнородной записи
		abc::value_t root, nested, listing;
		// Выполняем набор вложенного отображения
		ASSERT_TRUE(nested.insert(abc::value_t(string("вложенное")), abc::value_t(string("значение подлиннее"))));
		/**
		 * Выполняем набор перечня чисел
		 */
		for(size_t i = 0; i < 5; i++)
			// Выполняем добавление очередного числа перечня
			ASSERT_TRUE(listing.push(abc::value_t(static_cast <int64_t> (i * 1000))));
		// Выполняем прививку вложенного отображения корню
		ASSERT_TRUE(root.insert(abc::value_t(string("отображение")), nested));
		// Выполняем прививку перечня чисел корню
		ASSERT_TRUE(root.insert(abc::value_t(string("перечень")), listing));
		// Выполняем прививку длинной строки корню
		ASSERT_TRUE(root.insert(abc::value_t(string("строка")), abc::value_t(string(40, 'z'))));
		// Выполняем сборку двоичной записи
		const vector <uint8_t> record = root.dump();
		// Выполняем проверку того, что запись вышла длиннее ста октетов
		ASSERT_GT(record.size(), static_cast <size_t> (100));
		// Выдача разбора записи целиком
		const string whole = abc_events(record, record.size());
		// Выполняем проверку непустоты выдачи разбора
		ASSERT_FALSE(whole.empty());
		/**
		 * Выполняем перебор всех размеров куска подачи
		 */
		for(size_t chunk = 1; chunk < record.size(); chunk++)
			// Выполняем проверку совпадения выдачи разбора с разбором целиком
			ASSERT_EQ(abc_events(record, chunk), whole) << "размер куска " << chunk;
	}
}
/**
 * @brief Путь берёт имена строковые и нестроковых не берёт
 *
 * @details Отображение ABC дозволяет именем ВСЯКОЕ значение - число, истину, отрезок
 * двоичный, - и тем он от прочих кодеков рамки отличается: у JSON, YAML и разметки имя
 * есть строка по стандарту, и вопроса не возникает. Путь же RFC 6901 состоит из звеньев
 * ТЕКСТОВЫХ, и звено `7` есть строка «7», а не число семь
 *
 * @details Правило отсюда следует одно: путь достаёт поля, названные СТРОКОЙ, а поля,
 * названные иначе, ему недоступны вовсе. Достать их можно перебором по номеру - ходами
 * `key(i)` и `at(i)`, - и дорога та у ABC заведена. Свести же их к пути значило бы
 * выдумать написание чисел, истины и октетов текстом, а всякое такое написание было бы
 * нашим изобретением, стандартом не подкреплённым
 *
 * @warning Отступлений здесь ДВА, и всякому нужен свой случай. Первое - путь берёт имя
 *          числовое ВМЕСТО строкового; ловится оно полем `7`, несомым отображением
 *          дважды - числом и строкою, - где спрашивается не «нашлось ли», а ЧТО ИМЕННО
 *          нашлось. Второе - путь берёт числовое ЕЩЁ И вдобавок, запасною дорогой;
 *          первому случаю оно невидимо вовсе, ибо строковое имя находится раньше и
 *          запасная дорога не звучит. Ловится оно полем `9`, несомым одним лишь числом
 *
 * @warning Довод этот писался сперва об одном первом случае и был НЕПОЛОН: подмена,
 *          заводившая путю запасную дорогу по десятичному написанию числа, проверку не
 *          покрасила. Поле `9` заведено по следам той подмены
 *
 * @note Правило это закрепляется здесь, а не в наборе ABC, по просьбе владельцев
 *       прочих кодеков: расхождение вида имён есть свойство рамки целиком, и видеть
 *       его должны все семеро, а не один
 *
 */
TEST(CodecContract, PathTakesStringNamesAndRefusesTheRest) {
	// Собираемое отображение с именами разного вида
	abc::value_t root;
	/**
	 * Выполняем добавление поля, названного ЧИСЛОМ семь
	 */
	ASSERT_TRUE(root.insert(abc::value_t(int64_t(7)), abc::value_t(string("по-числу"))));
	/**
	 * Выполняем добавление поля, названного СТРОКОЙ «7»
	 *
	 * @note Имена эти разные, и отображение несёт их оба: сличение имён у ABC идёт по
	 *       виду наравне с содержимым, и число семь строке «7» не равно
	 */
	ASSERT_TRUE(root.insert(abc::value_t(string("7")), abc::value_t(string("по-имени"))));
	// Выполняем добавление поля, названного ИСТИНОЙ
	ASSERT_TRUE(root.insert(abc::value_t(true), abc::value_t(string("по-истине"))));
	/**
	 * Выполняем добавление поля, названного числом ДЕВЯТЬ и только им
	 *
	 * @note Двойника строкового у поля этого нет намеренно: им ловится путь, берущий
	 *       имена числовые запасною дорогой, - поле `7` того не ловит вовсе
	 */
	ASSERT_TRUE(root.insert(abc::value_t(int64_t(9)), abc::value_t(string("только-числом"))));
	// Выполняем проверку того, что отображение несёт все четыре поля
	ASSERT_EQ(root.size(), static_cast <size_t> (4));
	// Выполняем сборку двоичной записи
	const vector <uint8_t> record = root.dump();
	// Объект документа
	abc::document_t doc(::logger());
	// Выполняем разбор собранной записи
	ASSERT_TRUE(doc.parse(record.data(), record.size())) << abc::message(doc.error());
	/**
	 * Выполняем проверку того, что путь достал поле по имени СТРОКОВОМУ
	 *
	 * @note Спрашивается здесь именно содержимое, а не пригодность: пригодность отвечала
	 *       бы истиной и когда путь берёт имя числовое
	 */
	ASSERT_TRUE(doc.at("/7").valid());
	ASSERT_EQ(doc.at("/7").data(), "по-имени");
	// Выполняем проверку недоступности поля, названного истиной
	ASSERT_FALSE(doc.at("/true").valid());
	/**
	 * Выполняем проверку недоступности поля, названного одним лишь числом
	 *
	 * @note Утверждение это и есть сторож запасной дороги: заведи её кто-нибудь - и
	 *       написание `9` достало бы поле, стандартом к тому не обязанное
	 */
	ASSERT_FALSE(doc.at("/9").valid());
	// Выполняем проверку того, что взгляд владеющий отвечает то же самое
	ASSERT_TRUE(root.at("/7").valid());
	ASSERT_EQ(root.at("/7").text(), "по-имени");
	// Выполняем проверку недоступности поля, названного истиной, взглядом владеющим
	ASSERT_FALSE(root.at("/true").valid());
	// Выполняем проверку недоступности поля, названного числом, взглядом владеющим
	ASSERT_FALSE(root.at("/9").valid());
	/**
	 * Выполняем проверку достижимости нестроковых имён перебором по номеру
	 *
	 * @note Половина эта обязательна: без неё правило читалось бы «поля с нестроковыми
	 *       именами недоступны вовсе», а это неправда - недоступны они одному лишь
	 *       ПУТИ, и дорога к ним есть
	 */
	{
		// Число полей с именами числовыми, найденных перебором
		size_t found = 0;
		/**
		 * Выполняем перебор всех полей отображения
		 */
		for(size_t i = 0; i < doc.root().size(); i++){
			// Получаем очередное имя поля отображения
			const abc::document_t::value_t name = doc.root().key(i);
			// Выполняем проверку пригодности полученного имени
			ASSERT_TRUE(name.valid()) << i;
			/**
			 * Если имя поля объявлено числом
			 */
			if(name.is(abc::type_t::SIGNED) || name.is(abc::type_t::UNSIGNED)){
				// Извлекаемое значение имени поля
				uint64_t number = 0;
				// Выполняем извлечение имени поля числом
				ASSERT_TRUE(name.value(number)) << i;
				/**
				 * Выполняем проверку содержимого поля, названного числом
				 *
				 * @note Сличается содержимое, ИМЕНИ отвечающее, а не одно лишь наличие
				 *       поля: перебор обязан отдавать имя и значение согласованно, а
				 *       рассогласование их было бы невидимо проверке на счёт
				 */
				switch(number){
					// Если поле названо числом семь
					case 7: ASSERT_EQ(doc.root().at(i).data(), "по-числу"); break;
					// Если поле названо числом девять
					case 9: ASSERT_EQ(doc.root().at(i).data(), "только-числом"); break;
					// Если поле названо числом, отображению не заданным
					default: FAIL() << "имя числовое " << number << " отображению не задано";
				}
				// Выполняем учёт найденного поля с числовым именем
				found++;
			}
		}
		// Выполняем проверку того, что оба поля с числовыми именами перебором найдены
		ASSERT_EQ(found, static_cast <size_t> (2));
	}
}
/**
 * @brief Метка порядка байтов распознаётся и в содержимое не попадает
 *
 * @details Кодировка исходного текста определяется меткою порядка байтов в начале его,
 * содержимое приводится к UTF-8, а сама метка содержимым НЕ становится. Порок здесь
 * молчалив вдвойне: метка, в содержимое попавшая, делает первое имя поля непохожим на
 * себя, - и потребитель, ищущий поле по имени, получает отсутствие там, где оно есть
 *
 * @note Текст без метки объявляется UTF-8, а не кодировкою неопределённой: неопределённой
 *       она бывает лишь ДО разбора да после очистки
 *
 * @note ABC в сличении не участвует: хода `encoding()` у него нет вовсе
 *
 */
TEST(CodecContract, ByteOrderMarkIsRecognisedAndKeptOutOfTheContent) {
	/**
	 * @note ABC в сличении этом НЕ участвует, и не по недосмотру: метки порядка байтов
	 *       двоичная запись не несёт и нести не может. Первый её октет есть МЕТКА ВИДА
	 *       значения, и всякое сочетание октетов там уже занято смыслом - отвести под
	 *       метку кодировки нечего. Порядок же октетов у чисел задан самим описанием
	 *       записи - он прямой, - и узнавать его из содержимого не требуется
	 */
	/**
	 * @brief Метод сборки текста в кодировке UTF-16 из образца US-ASCII
	 *
	 * @param ascii  образец текста в кодировке US-ASCII
	 * @param little признак обратного порядка байтов
	 * @return       собранный текст с меткою порядка байтов
	 *
	 */
	auto utf16 = [](const string & ascii, const bool little) noexcept -> string {
		// Собираемый текст в кодировке UTF-16
		string result;
		// Добавляем метку порядка байтов
		result.append(little ? "\xFF\xFE" : "\xFE\xFF", 2);
		/**
		 * Выполняем перебор всех знаков образца
		 */
		for(const char letter : ascii){
			/**
			 * Если порядок байтов обратный
			 */
			if(little){
				// Добавляем младший октет знака
				result.push_back(letter);
				// Добавляем старший октет знака
				result.push_back('\0');
			// Если порядок байтов прямой
			} else {
				// Добавляем старший октет знака
				result.push_back('\0');
				// Добавляем младший октет знака
				result.push_back(letter);
			}
		}
		// Выводим собранный текст в кодировке UTF-16
		return result;
	};
	// Метка порядка байтов кодировки UTF-8
	const string bom = "\xEF\xBB\xBF";
	/**
	 * Распознавание кодировки у документа
	 */
	{
		// Разбираемый текст документа
		const string text = "{\"поле\":1}";
		// Объекты документа под каждую из кодировок
		json::document_t plain(::logger()), marked(::logger()), little(::logger()), big(::logger());
		// Выполняем разбор текста документа без метки порядка байтов
		ASSERT_TRUE(plain.parse(text));
		// Выполняем разбор текста документа с меткою порядка байтов
		ASSERT_TRUE(marked.parse(bom + text));
		// Выполняем разбор текста документа в кодировке UTF-16 с обратным порядком байтов
		ASSERT_TRUE(little.parse(utf16("{\"a\":1}", true)));
		// Выполняем разбор текста документа в кодировке UTF-16 с прямым порядком байтов
		ASSERT_TRUE(big.parse(utf16("{\"a\":1}", false)));
		// Выполняем проверку объявления кодировки текста без метки
		ASSERT_EQ(plain.encoding(), json::encoding_t::UTF8);
		// Выполняем проверку распознавания кодировки по метке
		ASSERT_EQ(marked.encoding(), json::encoding_t::UTF8);
		// Выполняем проверку распознавания обратного порядка байтов
		ASSERT_EQ(little.encoding(), json::encoding_t::UTF16LE);
		// Выполняем проверку распознавания прямого порядка байтов
		ASSERT_EQ(big.encoding(), json::encoding_t::UTF16BE);
		/**
		 * Выполняем проверку того, что метка в содержимое не попала
		 *
		 * @note Сличается запись целиком: попади метка в имя поля - запись отличалась бы
		 *       от разбора того же текста без метки, а розыск поля по имени отвечал бы
		 *       отсутствием
		 */
		ASSERT_EQ(marked.dump(), plain.dump());
		// Выполняем проверку доступности поля по имени после разбора текста с меткою
		ASSERT_TRUE(marked.has("/поле"));
		// Выполняем проверку приведения текста UTF-16 к кодировке UTF-8
		ASSERT_EQ(little.dump(), big.dump());
	}
	/**
	 * Распознавание кодировки у дерева разметки
	 */
	{
		// Разбираемый текст разметки
		const string text = "<узел>значение</узел>";
		// Объекты дерева разметки под каждую из кодировок
		xml::document_t plain(::logger()), marked(::logger()), little(::logger()), big(::logger());
		// Выполняем разбор текста разметки без метки порядка байтов
		ASSERT_TRUE(plain.parse(text));
		// Выполняем разбор текста разметки с меткою порядка байтов
		ASSERT_TRUE(marked.parse(bom + text));
		// Выполняем разбор текста разметки в кодировке UTF-16 с обратным порядком байтов
		ASSERT_TRUE(little.parse(utf16("<a>1</a>", true)));
		// Выполняем разбор текста разметки в кодировке UTF-16 с прямым порядком байтов
		ASSERT_TRUE(big.parse(utf16("<a>1</a>", false)));
		// Выполняем проверку объявления кодировки текста без метки
		ASSERT_EQ(plain.encoding(), xml::encoding_t::UTF8);
		// Выполняем проверку распознавания кодировки по метке
		ASSERT_EQ(marked.encoding(), xml::encoding_t::UTF8);
		// Выполняем проверку распознавания обратного порядка байтов
		ASSERT_EQ(little.encoding(), xml::encoding_t::UTF16LE);
		// Выполняем проверку распознавания прямого порядка байтов
		ASSERT_EQ(big.encoding(), xml::encoding_t::UTF16BE);
		// Выполняем проверку того, что метка в содержимое не попала
		ASSERT_EQ(marked.dump(), plain.dump());
		/**
		 * Выполняем проверку доступности узла по пути после разбора текста с меткою
		 *
		 * @note Метка, в имя корня попавшая, сделала бы путь `/узел` ведущим в никуда
		 */
		ASSERT_TRUE(marked.has("/узел"));
		// Выполняем проверку приведения текста UTF-16 к кодировке UTF-8
		ASSERT_EQ(little.dump(), big.dump());
	}
	/**
	 * Распознавание кодировки у таблицы
	 */
	{
		// Разбираемый текст таблицы
		const string text = "имя,значение\r\nАня,7\r\n";
		// Объекты таблицы под каждую из кодировок
		csv::document_t plain(::logger()), marked(::logger()), little(::logger()), big(::logger());
		// Выполняем разбор текста таблицы без метки порядка байтов
		ASSERT_TRUE(plain.parse(text));
		// Выполняем разбор текста таблицы с меткою порядка байтов
		ASSERT_TRUE(marked.parse(bom + text));
		// Выполняем разбор текста таблицы в кодировке UTF-16 с обратным порядком байтов
		ASSERT_TRUE(little.parse(utf16("a,b\r\n1,2\r\n", true)));
		// Выполняем разбор текста таблицы в кодировке UTF-16 с прямым порядком байтов
		ASSERT_TRUE(big.parse(utf16("a,b\r\n1,2\r\n", false)));
		// Выполняем проверку объявления кодировки текста без метки
		ASSERT_EQ(plain.encoding(), csv::encoding_t::UTF8);
		// Выполняем проверку распознавания кодировки по метке
		ASSERT_EQ(marked.encoding(), csv::encoding_t::UTF8);
		// Выполняем проверку распознавания обратного порядка байтов
		ASSERT_EQ(little.encoding(), csv::encoding_t::UTF16LE);
		// Выполняем проверку распознавания прямого порядка байтов
		ASSERT_EQ(big.encoding(), csv::encoding_t::UTF16BE);
		/**
		 * Выполняем проверку того, что метка в первое поле не попала
		 *
		 * @note Место это у таблицы самое уязвимое: метка стоит вплотную к первому полю
		 *       первой записи, и попади она внутрь - сличение имени столбца отвечало бы
		 *       несовпадением при виде совершенно обычном
		 */
		ASSERT_EQ(marked.get(0, 0), "имя");
		// Выполняем проверку совпадения записи таблицы с разбором текста без метки
		ASSERT_EQ(marked.dump(), plain.dump());
		// Выполняем проверку приведения текста UTF-16 к кодировке UTF-8
		ASSERT_EQ(little.dump(), big.dump());
	}
	/**
	 * Выполняем закрепление ОБРАТНОЙ стороны договора: выдача всегда в UTF-8
	 *
	 * @details Прежде закреплялась одна сторона - что метка опознаётся и в содержимое
	 *          не попадает. Сторона обратная - какою кодировкой текст выдаётся - не
	 *          поверялась ничем, а между тем ход `encoding()` отвечает кодировкою
	 *          ВХОДА, и потребитель, прочитавший её, вправе ждать, что выдача пойдёт
	 *          той же. Она идёт иною
	 *
	 * @note Уклад верен и намеренен: RFC 8259 велит обмену идти в UTF-8, у XML 1.0
	 *       объявление кодировки живёт в самом тексте, а RFC 4180 кодировки не
	 *       касается вовсе. Но верное поведение, ничем не поверенное, держится на
	 *       случайности
	 *
	 * @warning Порок обратного устройства был бы тих: выдай кодек текст той же
	 * кодировкой, какою прочитал, - и потребитель, сличающий выдачу с эталоном
	 * строкою, получал бы расхождение вдвое по длине. Замер до заведения проверки:
	 * «{"a":1}» из UTF-16LE выдаётся семью октетами, а не четырнадцатью
	 *
	 * @note Сличать надо ДЛИНУ, а не одно лишь равенство выдач меж собою: две выдачи
	 *       в UTF-16 равнялись бы друг другу так же исправно
	 */
	{
		// Объект документа
		json::document_t plain(::logger());
		// Выполняем разбор текста документа кодировкою UTF-16 с обратным порядком
		ASSERT_TRUE(plain.parse(utf16("{\"a\":1}", true)));
		// Выполняем проверку опознания кодировки входа
		ASSERT_EQ(plain.encoding(), json::encoding_t::UTF16LE);
		/**
		 * Выполняем проверку того, что выдача идёт в UTF-8 знак в знак
		 */
		ASSERT_EQ(plain.dump(), "{\"a\":1}");
		// Объект дерева разметки
		xml::document_t markup(::logger());
		// Выполняем разбор текста разметки кодировкою UTF-16 с прямым порядком
		ASSERT_TRUE(markup.parse(utf16("<a>1</a>", false)));
		// Выполняем проверку опознания кодировки входа
		ASSERT_EQ(markup.encoding(), xml::encoding_t::UTF16BE);
		// Выполняем проверку того, что выдача идёт в UTF-8 знак в знак
		ASSERT_EQ(markup.dump(), "<a>1</a>");
		// Объект таблицы
		csv::document_t table(::logger());
		// Выполняем разбор текста таблицы кодировкою UTF-16 с обратным порядком
		ASSERT_TRUE(table.parse(utf16("a,b\r\n1,2\r\n", true)));
		// Выполняем проверку опознания кодировки входа
		ASSERT_EQ(table.encoding(), csv::encoding_t::UTF16LE);
		// Выполняем проверку того, что выдача идёт в UTF-8 знак в знак
		ASSERT_EQ(table.dump(), "a,b\r\n1,2\r\n");
	}
}
/**
 * @brief Превышение предела настроек отвергает разбор, а не усекает содержимое
 *
 * @details Пределы настроек ограждают разбор от текста непомерного, и ограждать они
 * обязаны ОТКАЗОМ. Порок противоположный - молчаливое усечение - худший из возможных:
 * разбор отвечает успехом, документ выглядит целым, а часть содержимого пропала, и
 * узнать о том потребителю неоткуда
 *
 * @note Сличаются ОБЕ стороны каждого предела: при малом пределе текст отвергается, при
 *       достаточном тот же самый текст принимается. Без второй стороны проверка
 *       доказывала бы лишь то, что текст отвергается всегда, а предел был бы ни при чём
 *
 * @note Коды отказа у кодеков РАЗНЫЕ и приведению не подлежат: перечень кодов у каждого
 *       свой, а общее здесь - сам отказ да пустота содержимого после него
 *
 */
TEST(CodecContract, ExceedingASettingsLimitRefusesInsteadOfTruncating) {
	/**
	 * Пределы разбора документа
	 */
	{
		/**
		 * Предел длины строкового значения
		 */
		{
			// Объекты документа под тесный и достаточный пределы
			json::document_t tight(::logger()), loose(::logger());
			// Получаем настройки документа
			json::document_t::settings_t settings = tight.settings();
			// Устанавливаем тесный предел длины строкового значения
			settings.reader.maxString = 4;
			// Выполняем установку настроек документа
			tight.settings(settings);
			// Устанавливаем достаточный предел длины строкового значения
			settings.reader.maxString = 64;
			// Выполняем установку настроек документа
			loose.settings(settings);
			// Выполняем проверку отказа разбора при тесном пределе
			ASSERT_FALSE(tight.parse("{\"a\":\"длинновато\"}"));
			// Выполняем проверку постановки кода отказа
			ASSERT_NE(tight.error(), json::error_t::NONE);
			/**
			 * Выполняем проверку того, что содержимое НЕ усечено, а отсутствует вовсе
			 *
			 * @note Отказ, оставивший часть содержимого, был бы хуже отказа чистого:
			 *       потребитель, кода не спросивший, работал бы с обрубком
			 */
			ASSERT_TRUE(tight.dump().empty());
			// Выполняем проверку успешности разбора того же текста при достаточном пределе
			ASSERT_TRUE(loose.parse("{\"a\":\"длинновато\"}"));
			// Выполняем проверку отсутствия кода отказа
			ASSERT_EQ(loose.error(), json::error_t::NONE);
		}
		/**
		 * Предел глубины вложенности
		 */
		{
			// Объекты документа под тесный и достаточный пределы
			json::document_t tight(::logger()), loose(::logger());
			// Получаем настройки документа
			json::document_t::settings_t settings = tight.settings();
			// Устанавливаем тесный предел глубины вложенности
			settings.reader.maxDepth = 2;
			// Выполняем установку настроек документа
			tight.settings(settings);
			// Устанавливаем достаточный предел глубины вложенности
			settings.reader.maxDepth = 16;
			// Выполняем установку настроек документа
			loose.settings(settings);
			// Выполняем проверку отказа разбора при тесном пределе
			ASSERT_FALSE(tight.parse("[[[[1]]]]"));
			// Выполняем проверку успешности разбора того же текста при достаточном пределе
			ASSERT_TRUE(loose.parse("[[[[1]]]]"));
		}
		/**
		 * Предел длины записи числа
		 */
		{
			// Объекты документа под тесный и достаточный пределы
			json::document_t tight(::logger()), loose(::logger());
			// Получаем настройки документа
			json::document_t::settings_t settings = tight.settings();
			// Устанавливаем тесный предел длины записи числа
			settings.reader.maxNumber = 3;
			// Выполняем установку настроек документа
			tight.settings(settings);
			// Устанавливаем достаточный предел длины записи числа
			settings.reader.maxNumber = 32;
			// Выполняем установку настроек документа
			loose.settings(settings);
			// Выполняем проверку отказа разбора при тесном пределе
			ASSERT_FALSE(tight.parse("[123456789]"));
			// Выполняем проверку отсутствия усечённого содержимого
			ASSERT_TRUE(tight.dump().empty());
			// Выполняем проверку успешности разбора того же текста при достаточном пределе
			ASSERT_TRUE(loose.parse("[123456789]"));
		}
	}
	/**
	 * Пределы разбора разметки
	 */
	{
		/**
		 * Предел глубины вложенности узлов
		 */
		{
			// Объекты дерева разметки под тесный и достаточный пределы
			xml::document_t tight(::logger()), loose(::logger());
			// Получаем настройки дерева разметки
			xml::document_t::settings_t settings = tight.settings();
			// Устанавливаем тесный предел глубины вложенности
			settings.reader.maxDepth = 2;
			// Выполняем установку настроек дерева разметки
			tight.settings(settings);
			// Устанавливаем достаточный предел глубины вложенности
			settings.reader.maxDepth = 16;
			// Выполняем установку настроек дерева разметки
			loose.settings(settings);
			// Выполняем проверку отказа разбора при тесном пределе
			ASSERT_FALSE(tight.parse("<a><b><c><d>1</d></c></b></a>"));
			// Выполняем проверку отсутствия усечённого содержимого
			ASSERT_TRUE(tight.dump().empty());
			// Выполняем проверку успешности разбора того же текста при достаточном пределе
			ASSERT_TRUE(loose.parse("<a><b><c><d>1</d></c></b></a>"));
		}
		/**
		 * Предел длины имени узла
		 */
		{
			// Объекты дерева разметки под тесный и достаточный пределы
			xml::document_t tight(::logger()), loose(::logger());
			// Получаем настройки дерева разметки
			xml::document_t::settings_t settings = tight.settings();
			// Устанавливаем тесный предел длины имени
			settings.reader.maxName = 3;
			// Выполняем установку настроек дерева разметки
			tight.settings(settings);
			// Устанавливаем достаточный предел длины имени
			settings.reader.maxName = 64;
			// Выполняем установку настроек дерева разметки
			loose.settings(settings);
			// Выполняем проверку отказа разбора при тесном пределе
			ASSERT_FALSE(tight.parse("<длинноеимя>1</длинноеимя>"));
			// Выполняем проверку успешности разбора того же текста при достаточном пределе
			ASSERT_TRUE(loose.parse("<длинноеимя>1</длинноеимя>"));
		}
		/**
		 * Предел количества атрибутов узла
		 */
		{
			// Объекты дерева разметки под тесный и достаточный пределы
			xml::document_t tight(::logger()), loose(::logger());
			// Получаем настройки дерева разметки
			xml::document_t::settings_t settings = tight.settings();
			// Устанавливаем тесный предел количества атрибутов
			settings.reader.maxAttributes = 1;
			// Выполняем установку настроек дерева разметки
			tight.settings(settings);
			// Устанавливаем достаточный предел количества атрибутов
			settings.reader.maxAttributes = 8;
			// Выполняем установку настроек дерева разметки
			loose.settings(settings);
			// Выполняем проверку отказа разбора при тесном пределе
			ASSERT_FALSE(tight.parse("<a x='1' y='2' z='3'/>"));
			/**
			 * Выполняем проверку отсутствия усечённого содержимого
			 *
			 * @note Место это самое опасное из девяти: узел с частью атрибутов выглядит
			 *       узлом совершенно обычным, и пропажу трёх из четырёх заметить нечем
			 */
			ASSERT_TRUE(tight.dump().empty());
			// Выполняем проверку успешности разбора того же текста при достаточном пределе
			ASSERT_TRUE(loose.parse("<a x='1' y='2' z='3'/>"));
		}
	}
	/**
	 * Пределы разбора таблицы
	 */
	{
		/**
		 * Предел длины поля записи
		 */
		{
			// Объекты таблицы под тесный и достаточный пределы
			csv::document_t tight(::logger()), loose(::logger());
			// Получаем настройки таблицы
			csv::document_t::settings_t settings = tight.settings();
			// Устанавливаем тесный предел длины поля
			settings.reader.maxField = 3;
			// Выполняем установку настроек таблицы
			tight.settings(settings);
			// Устанавливаем достаточный предел длины поля
			settings.reader.maxField = 64;
			// Выполняем установку настроек таблицы
			loose.settings(settings);
			// Выполняем проверку отказа разбора при тесном пределе
			ASSERT_FALSE(tight.parse("длинноеполе,б\r\n"));
			// Выполняем проверку отсутствия усечённого содержимого
			ASSERT_TRUE(tight.dump().empty());
			// Выполняем проверку успешности разбора того же текста при достаточном пределе
			ASSERT_TRUE(loose.parse("длинноеполе,б\r\n"));
		}
		/**
		 * Предел количества полей записи
		 */
		{
			// Объекты таблицы под тесный и достаточный пределы
			csv::document_t tight(::logger()), loose(::logger());
			// Получаем настройки таблицы
			csv::document_t::settings_t settings = tight.settings();
			// Устанавливаем тесный предел количества полей
			settings.reader.maxFields = 2;
			// Выполняем установку настроек таблицы
			tight.settings(settings);
			// Устанавливаем достаточный предел количества полей
			settings.reader.maxFields = 16;
			// Выполняем установку настроек таблицы
			loose.settings(settings);
			// Выполняем проверку отказа разбора при тесном пределе
			ASSERT_FALSE(tight.parse("a,b,c,d\r\n"));
			// Выполняем проверку отсутствия усечённого содержимого
			ASSERT_TRUE(tight.dump().empty());
			// Выполняем проверку успешности разбора того же текста при достаточном пределе
			ASSERT_TRUE(loose.parse("a,b,c,d\r\n"));
		}
		/**
		 * Предел длины записи целиком
		 */
		{
			// Объекты таблицы под тесный и достаточный пределы
			csv::document_t tight(::logger()), loose(::logger());
			// Получаем настройки таблицы
			csv::document_t::settings_t settings = tight.settings();
			// Устанавливаем тесный предел длины записи
			settings.reader.maxRecord = 4;
			// Выполняем установку настроек таблицы
			tight.settings(settings);
			// Устанавливаем достаточный предел длины записи
			settings.reader.maxRecord = 128;
			// Выполняем установку настроек таблицы
			loose.settings(settings);
			// Выполняем проверку отказа разбора при тесном пределе
			ASSERT_FALSE(tight.parse("aaaa,bbbb,cccc\r\n"));
			// Выполняем проверку отсутствия усечённого содержимого
			ASSERT_TRUE(tight.dump().empty());
			// Выполняем проверку успешности разбора того же текста при достаточном пределе
			ASSERT_TRUE(loose.parse("aaaa,bbbb,cccc\r\n"));
		}
	}
	/**
	 * Пределы настроек у кодека ABC
	 *
	 * @details Пределов у ABC три, и подача им двоичная, а не текстовая. Договор же
	 *          сличается тот самый: превышение предела отвечает ОТКАЗОМ, а не усечением,
	 *          и содержимого после отказа не остаётся вовсе
	 *
	 * @note Всякий предел проверяется ТРОЙКОЙ значений - нуль, тесное, достаточное, - а
	 *       не парой. Нуль означает у ABC «без предела», согласно единому уговору кодека,
	 *       и проверить его отдельно необходимо: разойдись уговор - и потребитель,
	 *       подавший нуль в значении «ни одного», получил бы обратное, причём МОЛЧА
	 *
	 * @warning Достаточный предел взят РОВНО В МЕРУ разбираемого, а не с запасом: возьми
	 *          он запас - и проверка прошла бы, даже считай кодек предел на единицу не
	 *          так. Тесный же взят заведомо меньше, чтобы отказ был об одном пределе, а
	 *          не о случайном совпадении с иным
	 */
	{
		/**
		 * Предел глубины вложенности
		 */
		{
			// Собираемое значение глубины в пять уровней
			abc::value_t deep(static_cast <int64_t> (1));
			/**
			 * Выполняем оборачивание значения до затребованной глубины
			 */
			for(size_t i = 0; i < 4; i++){
				// Объект оборачивающего перечня
				abc::value_t wrapper;
				// Выполняем оборачивание собранного значения
				ASSERT_TRUE(wrapper.push(deep));
				// Выполняем замену собираемого значения обёрнутым
				deep = wrapper;
			}
			// Выполняем сборку двоичной записи
			const vector <uint8_t> record = deep.dump();
			/**
			 * Выполняем перебор пределов: без предела, тесный и достаточный
			 */
			for(const uint32_t limit : {static_cast <uint32_t> (0), static_cast <uint32_t> (2), static_cast <uint32_t> (5)}){
				// Объект документа
				abc::document_t document(::logger());
				// Получаем настройки документа
				abc::reader_t::settings_t settings = document.settings();
				// Выполняем установку предела глубины вложенности
				settings.maxDepth = limit;
				// Выполняем установку настроек документа
				document.settings(settings);
				/**
				 * Если предел взят тесным, разбор обязан отвечать отказом
				 */
				if(limit == static_cast <uint32_t> (2)){
					// Выполняем проверку отказа разбора при тесном пределе
					ASSERT_FALSE(document.parse(record.data(), record.size()));
					// Выполняем проверку того, что причина отказа названа
					ASSERT_EQ(document.error(), abc::error_t::DEPTH_EXCEEDED) << abc::message(document.error());
					// Выполняем проверку отсутствия усечённого содержимого
					ASSERT_EQ(document.nodes(), static_cast <size_t> (0));
				/**
				 * Иначе разбор обязан удаваться целиком
				 */
				} else {
					// Выполняем проверку успешности разбора
					ASSERT_TRUE(document.parse(record.data(), record.size())) << limit;
					// Выполняем проверку полноты собранного дерева
					ASSERT_EQ(document.nodes(), static_cast <size_t> (5)) << limit;
				}
			}
		}
		/**
		 * Предел длины строкового значения
		 */
		{
			// Выполняем сборку двоичной записи строки о ста октетах
			const vector <uint8_t> record = abc::value_t(string(100, 'x')).dump();
			/**
			 * Выполняем перебор пределов: без предела, тесный и достаточный
			 */
			for(const uint64_t limit : {static_cast <uint64_t> (0), static_cast <uint64_t> (10), static_cast <uint64_t> (100)}){
				// Объект документа
				abc::document_t document(::logger());
				// Получаем настройки документа
				abc::reader_t::settings_t settings = document.settings();
				// Выполняем установку предела длины строкового значения
				settings.maxString = limit;
				// Выполняем установку настроек документа
				document.settings(settings);
				/**
				 * Если предел взят тесным, разбор обязан отвечать отказом
				 */
				if(limit == static_cast <uint64_t> (10)){
					// Выполняем проверку отказа разбора при тесном пределе
					ASSERT_FALSE(document.parse(record.data(), record.size()));
					// Выполняем проверку отсутствия усечённого содержимого
					ASSERT_EQ(document.nodes(), static_cast <size_t> (0));
				/**
				 * Иначе разбор обязан удаваться целиком
				 */
				} else {
					// Выполняем проверку успешности разбора
					ASSERT_TRUE(document.parse(record.data(), record.size())) << limit;
					// Выполняем проверку полноты вычитанной строки
					ASSERT_EQ(document.root().data().size(), static_cast <size_t> (100)) << limit;
				}
			}
		}
	}
}
/**
 * @brief Снос корня делится по стандарту кодека на четыре стороны
 *
 * @details Обращение `erase("")` у шестерых кодеков рамки означает НЕ одно и то же, и
 * различие это идёт от стандартов да от устройства ходов, а не от небрежности. Сторон
 * четыре, и всякая со своим доводом:
 *
 * @li JSON и XML снос корня ОТВЕРГАЮТ: документ JSON обязан нести ровно одно значение
 *     (RFC 8259), а разметка - ровно один корневой элемент (XML 1.0), и документ без
 *     них документом не является. Заменить корень целиком дозволено прививкой
 * @li YAML и TOML снос корня ДОПУСКАЮТ: пустой документ законен у обоих описаний, и
 *     отвергать снос у них не на что сослаться
 * @li INI и ABC хода сноса ПО ПУТИ не имеют вовсе: `erase` берёт у них ИМЯ - ключ со
 *     разделом у INI, имя поля у ABC, - и пустая строка есть законное имя. Обращение
 *     `erase("")` означает там «снеси поле, названное пустой строкой», а не «снеси
 *     корень», и отказ его есть отказ ИМЕНИ, а не отказ сносу корня
 *
 * @note Опустошение целого зовётся у всех шестерых `clear()`, и дорога эта общая. Снос
 *       корня по пути есть вопрос отдельный, и делится он вышеописанно
 *
 * @warning Проверка эта писалась дважды. Первый замер показал отказ у TOML, и был он
 *          ВЕРЕН как замер, но неверен как договор: владелец кодека вписал отказ по
 *          доводу, объявленному согласованным, а согласован был обратный. Закрепи
 *          проверка наблюдённое тогда же - описка одного владельца стала бы договором
 *          семерых, и доказывать после пришлось бы, что договор лжёт
 *
 * @warning ПРАВИЛО, ОТСЮДА ВЫВЕДЕННОЕ И ОБЩЕЕ ДЛЯ ВСЕХ, КТО ПИШЕТ ЗДЕСЬ. Поведение
 *          чужого кодека закрепляется проверкою лишь тогда, когда владелец его
 *          подтвердил, что поведение это ЗАДУМАНО. Замер говорит, ЧТО кодек делает, и
 *          не говорит, что делать он ДОЛЖЕН; закрепить первое вместо второго значит
 *          обратить случайность в договор, а починку - в поломку договора
 *
 */
TEST(CodecContract, RootRemovalDivergesByStandardInFourWays) {
	/**
	 * Сторона первая: снос корня отвергается стандартом
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем разбор текста документа
		ASSERT_TRUE(doc.parse("{\"a\":1}")) << json::message(doc.error());
		// Выполняем проверку отказа сноса корня документа
		ASSERT_FALSE(doc.erase(""));
		// Выполняем проверку сохранности документа
		ASSERT_EQ(doc.dump(), "{\"a\":1}");
		// Объект дерева разметки
		xml::document_t markup(::logger());
		// Выполняем разбор текста разметки
		ASSERT_TRUE(markup.parse("<a><b/></a>")) << xml::message(markup.error());
		// Выполняем проверку отказа сноса корневого узла разметки
		ASSERT_FALSE(markup.erase(""));
		// Выполняем проверку сохранности дерева разметки
		ASSERT_EQ(markup.dump(), "<a><b/></a>");
	}
	/**
	 * Сторона вторая: снос корня допускается стандартом
	 *
	 * @note Сличается не один признак успешности, но и ПУСТОТА следом: снос, отдавший
	 *       истину и ничего не снёсший, был бы от верного неотличим по признаку одному
	 */
	{
		// Объект документа YAML
		yaml::document_t staged(::logger());
		// Выполняем разбор текста документа
		ASSERT_TRUE(staged.parse("a: 1\n")) << yaml::message(staged.error());
		// Выполняем проверку успешности сноса корня документа
		ASSERT_TRUE(staged.erase(""));
		// Выполняем проверку опустошения документа
		ASSERT_TRUE(staged.empty());
		// Объект документа TOML
		toml::document_t tabled(::logger());
		// Выполняем разбор текста документа
		ASSERT_TRUE(tabled.parse("a = 1\n")) << toml::message(tabled.error());
		// Выполняем проверку успешности сноса корня документа
		ASSERT_TRUE(tabled.erase(""));
		// Выполняем проверку опустошения документа
		ASSERT_TRUE(tabled.empty());
	}
	/**
	 * Сторона третья: хода сноса по пути нет, и пустая строка есть ИМЯ
	 *
	 * @warning Сличается здесь не «отказ», а ПРИЧИНА отказа. Отказ у INI выглядит так
	 *          же, как отказ у JSON, а означает иное: у JSON отвергнут снос корня, у
	 *          INI не найдено свойство, названное пустой строкой. Спроси проверка один
	 *          признак - и две разные стороны договора слились бы в одну
	 */
	{
		// Объект дерева настроек
		ini::document_t doc(::logger());
		// Выполняем разбор текста настроек
		ASSERT_TRUE(doc.parse("a = 1\n")) << ini::message(doc.error());
		// Выполняем проверку отказа сноса свойства, названного пустой строкой
		ASSERT_FALSE(doc.erase(""));
		// Выполняем проверку сохранности дерева настроек
		ASSERT_FALSE(doc.empty());
		/**
		 * Выполняем проверку того, что опустошение целого дорогою своей УДАЁТСЯ
		 *
		 * @note Половина эта обязательна: без неё сторона третья читалась бы «дерево
		 *       снести нельзя», а это неправда - нельзя снести его ПО ПУТИ, дорога же
		 *       опустошения есть, и зовётся она у всех шестерых одинаково
		 *
		 * @note Положительной половины - сноса поля, названного пустой строкой, - у INI
		 *       нет и быть не может, в отличие от ABC. Пустое имя свойства НЕЗАКОННО у
		 *       него по самому виду записи: строка «= значение» без имени обратно не
		 *       прочтётся, и постановка такого имени отвергается с причиною «invalid
		 *       property name». Отказ здесь есть ВЕРНОЕ поведение, а не пробел набора
		 */
		doc.clear();
		// Выполняем проверку опустошения дерева настроек
		ASSERT_TRUE(doc.empty());
	}
	/**
	 * Сторона третья у кодека ABC
	 *
	 * @note Пустая строка есть у ABC имя законное, и проверяется здесь именно это:
	 *       поле, названное пустой строкой, СНОСИТСЯ, а корень остаётся цел. Спроси
	 *       проверка один лишь отказ на отсутствующем имени - и «пустая строка есть
	 *       имя» осталось бы недоказанным
	 */
	{
		// Собираемое отображение
		abc::value_t root;
		// Выполняем добавление поля, названного пустой строкой
		ASSERT_TRUE(root.insert(abc::value_t(string()), abc::value_t(int64_t(1))));
		// Выполняем добавление поля, названного обычным именем
		ASSERT_TRUE(root.insert(abc::value_t(string("a")), abc::value_t(int64_t(2))));
		// Выполняем проверку того, что отображение несёт оба поля
		ASSERT_EQ(root.size(), static_cast <size_t> (2));
		// Выполняем снос поля, названного пустой строкой
		ASSERT_TRUE(root.erase(""));
		// Выполняем проверку того, что снесено ровно одно поле
		ASSERT_EQ(root.size(), static_cast <size_t> (1));
		// Выполняем проверку того, что корень сносом имени не тронут
		ASSERT_TRUE(root.valid());
		// Выполняем проверку того, что уцелело именно поле с обычным именем
		ASSERT_TRUE(root.contains("a"));
		// Выполняем проверку отказа повторного сноса снесённого имени
		ASSERT_FALSE(root.erase(""));
		/**
		 * Выполняем проверку того, что опустошение целого дорогою своей удаётся
		 */
		root.clear();
		// Выполняем проверку опустошения отображения
		ASSERT_TRUE(root.empty());
	}
}
/**
 * @brief Перечисление детей и извлечение по пути дают ЗАМКНУТЫЙ обход документа
 *
 * @details Обещание общего API - обойти любой кодек ОДИНАКОВО. Держится оно на двух ходах:
 * `keys(путь)` перечисляет звенья к детям, `at(путь)` берёт значение по пути, - и обход
 * этот обязан быть ЗАМКНУТ: всякое звено, выданное первым, годно второму и ведёт к тому
 * самому ребёнку, а не к иному и не в никуда
 *
 * @warning Сличения ЧИСЛА обойдённых с числом узлов НЕДОСТАТОЧНО, и это доказано замером:
 *          у дерева разметки обход по звеньям корня не разыскивал НИ ОДНОГО ребёнка - все
 *          пути вели в никуда, ибо склейка `путь + "/" + звено` для пустого пути считала
 *          от корня арены, а звенья давались от корневого узла разметки, - а перебор при
 *          том СХОДИЛСЯ числом. Оттого сличается ещё и тождество: разысканное обязано быть
 *          тем же узлом, а не просто действительным
 *
 * @note Выдаются ЗВЕНЬЯ, а не имена. У объекта JSON они совпадают, у разметки расходятся:
 *       два узла с именем «a» дали бы два звена «a», оба ведущие к первому, - и второй не
 *       разыскался бы никогда, притом молча. Мосту, укладывающему прочитанное в чужое
 *       дерево, имя берётся отдельно ходом `name()`
 *
 * @note Таблица CSV в сличении НЕ участвует: хода `at(путь)` у неё нет вовсе, а завести
 *       `keys(путь)` без него значило бы дать общее имя без общего поведения. Обход
 *       таблицы идёт своими ходами `rows()`, `size(row)` да `get(row, col)`
 *
 */
TEST(CodecContract, EnumerationAndLookupFormAClosedTraversal) {
	/**
	 * Перечисление НИКОГДА не отвечает отказом
	 *
	 * @details Два вопроса разведены по разным ходам намеренно: «есть ли место» спрашивается
	 * ходом `has()`, «кто у него дети» - ходом `keys()`. Оттого перечисление остаётся простым
	 * и особых случаев не имеет вовсе: лист, пустое вместилище и путь в никуда отвечают
	 * пустым перечнем ОДИНАКОВО, а разнятся они ответом `has()`
	 *
	 * @note Обходу это и нужно: он спрашивает `keys()` у ВСЯКОГО места, в том числе у
	 *       скаляра, и различать заранее лист от вместимого не может - вернее, может, да
	 *       не должен, ибо это удвоило бы правила на его стороне
	 *
	 * @warning У разметки листом является узел БЕЗ ДЕТЕЙ, а не узел без вложенной разметки:
	 *          `<a>текст</a>` несёт ОДНОГО ребёнка - текстовое содержимое, - и перечисление
	 *          отвечает у него одним звеном, а не пустым перечнем. Пустым отвечает `<a/>`
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем разбор текста документа со скаляром, пустым объектом и пустым массивом
		ASSERT_TRUE(doc.parse("{\"скаляр\":1,\"пустой\":{},\"порожний\":[]}"));
		// Выполняем проверку пустоты перечня у скалярного значения
		ASSERT_TRUE(doc.keys("/скаляр").empty());
		// Выполняем проверку наличия скалярного значения
		ASSERT_TRUE(doc.has("/скаляр"));
		// Выполняем проверку пустоты перечня у пустого объекта
		ASSERT_TRUE(doc.keys("/пустой").empty());
		// Выполняем проверку пустоты перечня у пустого массива
		ASSERT_TRUE(doc.keys("/порожний").empty());
		// Выполняем проверку пустоты перечня по указателю в никуда
		ASSERT_TRUE(doc.keys("/нет-такого").empty());
		// Выполняем проверку того, что указателя в никуда и вправду нет
		ASSERT_FALSE(doc.has("/нет-такого"));
		// Выполняем проверку пустоты перечня глубже листа
		ASSERT_TRUE(doc.keys("/скаляр/глубже").empty());
		// Выполняем проверку пустоты перечня у документа, разбору не подвергавшегося
		ASSERT_TRUE(json::document_t(::logger()).keys("").empty());
	}
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем разбор текста разметки с пустым узлом и узлом с содержимым
		ASSERT_TRUE(doc.parse("<r><пустой/><несущий>текст</несущий></r>"));
		// Выполняем проверку пустоты перечня у узла без детей
		ASSERT_TRUE(doc.keys("/r/пустой").empty());
		// Выполняем проверку наличия узла без детей
		ASSERT_TRUE(doc.has("/r/пустой"));
		/**
		 * Выполняем проверку того, что узел с содержимым листом НЕ является
		 *
		 * @note Текстовое содержимое есть такой же ребёнок, как узел разметки, и обход
		 *       спускается в него наравне: он несёт содержимое, ради какого обход и ведётся
		 */
		ASSERT_EQ(doc.keys("/r/несущий").size(), static_cast <size_t> (1));
		// Выполняем проверку пустоты перечня у самого текстового содержимого
		ASSERT_TRUE(doc.keys("/r/несущий/0").empty());
		// Выполняем проверку пустоты перечня по пути в никуда
		ASSERT_TRUE(doc.keys("/нет-такого").empty());
		// Выполняем проверку того, что пути в никуда и вправду нет
		ASSERT_FALSE(doc.has("/нет-такого"));
		// Выполняем проверку пустоты перечня глубже листа
		ASSERT_TRUE(doc.keys("/r/пустой/глубже").empty());
		// Выполняем проверку пустоты перечня у дерева, разбору не подвергавшегося
		ASSERT_TRUE(xml::document_t(::logger()).keys("").empty());
	}
	/**
	 * О виде узла нельзя судить по ЧИСЛУ звеньев
	 *
	 * @details Потребитель, укладывающий разметку в чужое дерево, различает узел, несущий
	 * одно лишь содержимое, от вместилища - первый ложится скаляром, второй отображением.
	 * Соблазн судить о том по счёту звеньев велик и обманчив: ниже три случая, где счёт
	 * лжёт, и все три взяты из настоящей разметки, а не выдуманы
	 *
	 * @note Судить надлежит по ВИДАМ детей, а не по счёту их
	 *
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		/**
		 * Содержимое, разорванное примечанием
		 *
		 * @note Три звена, а текста один: примечание разрывает содержимое, не будучи его
		 *       частью. Правило «одно звено да текстовый ребёнок - значит скаляр» здесь
		 *       уложило бы вместилищем то, что по сути есть строка «xy»
		 */
		ASSERT_TRUE(doc.parse("<r><a>x<!--примечание-->y</a></r>"));
		// Выполняем проверку числа звеньев у содержимого, разорванного примечанием
		ASSERT_EQ(doc.keys("/r/a").size(), static_cast <size_t> (3));
		// Выполняем проверку того, что содержимое собирается в одну строку
		ASSERT_EQ(doc.at("/r/a").text(), "xy");
		/**
		 * Раздел дословного текста
		 *
		 * @note Одно звено, но ребёнок его НЕ текстовый узел: сличающий вид ребёнка с
		 *       `TEXT` пропустил бы дословный раздел и уложил бы его вместилищем
		 */
		ASSERT_TRUE(doc.parse("<r><a><![CDATA[дословно]]></a></r>"));
		// Выполняем проверку числа звеньев у дословного раздела
		ASSERT_EQ(doc.keys("/r/a").size(), static_cast <size_t> (1));
		// Выполняем проверку вида единственного ребёнка
		ASSERT_EQ(doc.at("/r/a/0").kind(), xml::kind_t::CDATA);
		// Выполняем проверку того, что содержимое дословного раздела доступно
		ASSERT_EQ(doc.at("/r/a").text(), "дословно");
		/**
		 * Содержимое вперемежку с вложенной разметкой
		 *
		 * @warning Здесь `text()` склеивает «xy» СКВОЗЬ вложенный узел, теряя его вовсе:
		 *          потребитель, взявший содержимое, не спросив вида детей, потерял бы
		 *          разметку молча
		 */
		ASSERT_TRUE(doc.parse("<r><a>x<b/>y</a></r>"));
		// Выполняем проверку числа звеньев у содержимого вперемежку с разметкой
		ASSERT_EQ(doc.keys("/r/a").size(), static_cast <size_t> (3));
		// Выполняем проверку склейки содержимого сквозь вложенную разметку
		ASSERT_EQ(doc.at("/r/a").text(), "xy");
		// Выполняем проверку того, что вложенный узел разметки при том на месте
		ASSERT_TRUE(doc.has("/r/a/b"));
		/**
		 * Узел без детей и узел с содержимым
		 *
		 * @note Расхождение это с кодеками YAML, TOML и INI законное: у них текст скаляра
		 *       есть ЗНАЧЕНИЕ узла, а не отдельный узел, и обходить там нечего
		 */
		ASSERT_TRUE(doc.parse("<r><пустой/><несущий>8080</несущий></r>"));
		// Выполняем проверку пустоты перечня у узла без детей
		ASSERT_TRUE(doc.keys("/r/пустой").empty());
		// Выполняем проверку того, что узел с содержимым несёт одного ребёнка
		ASSERT_EQ(doc.keys("/r/несущий").size(), static_cast <size_t> (1));
		// Выполняем проверку вида единственного ребёнка
		ASSERT_EQ(doc.at("/r/несущий/0").kind(), xml::kind_t::TEXT);
		/**
		 * Содержимое собирается ПО ВСЕЙ ГЛУБИНЕ, а не по прямым детям
		 *
		 * @warning Свойство это и делает третью ловушку худшей из трёх: у узла с вложенной
		 *          разметкой содержимое есть СКЛЕЙКА всего поддерева, и строки такой в
		 *          разметке нет нигде. Потребитель, взявший его у вместилища, получит вид
		 *          целого, какого не существует, а вложенное потеряет молча
		 */
		ASSERT_TRUE(doc.parse("<r><a><b><c>ГЛУБОКО</c></b></a></r>"));
		// Выполняем проверку сбора содержимого со всей глубины
		ASSERT_EQ(doc.at("/r/a").text(), "ГЛУБОКО");
		// Выполняем разбор разметки со своим содержимым и вложенным узлом
		ASSERT_TRUE(doc.parse("<r><a>свой<b>чужой</b></a></r>"));
		/**
		 * Выполняем проверку склейки своего содержимого с чужим
		 *
		 * @note Строки «свойчужой» в разметке нет нигде: она собрана из двух узлов разных
		 *       уровней, и потребитель, о том не знающий, примет её за значение
		 */
		ASSERT_EQ(doc.at("/r/a").text(), "свойчужой");
		/**
		 * Пробельное содержимое сохраняется как есть
		 *
		 * @note Обрезка пробелов - дело потребителя: настройкою чтения она не правится, и
		 *       кодек за него её не делает
		 */
		ASSERT_TRUE(doc.parse("<r><a>  значение  </a></r>"));
		// Выполняем проверку сохранности пробельного содержимого
		ASSERT_EQ(doc.at("/r/a").text(), "  значение  ");
	}
	/**
	 * Замкнутость обхода документа
	 *
	 * @note Имена полей взяты с косой чертой да тильдой намеренно: звенья RFC 6901 требуют
	 *       отменяющих записей, и имя, выданное КАК ЕСТЬ, разомкнуло бы обход молча
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем разбор текста документа
		ASSERT_TRUE(doc.parse("{\"a\":1,\"b\":[1,2,{\"c\":3}],\"поле/с/чертой\":4,\"тильда~тут\":5}"));
		// Количество разысканных обходом значений
		size_t walked = 0;
		/**
		 * @brief Метод обхода документа вглубь по звеньям
		 *
		 * @param self    ссылка на себя для возвратного зова
		 * @param pointer указатель на обходимое значение
		 *
		 */
		const auto walk = [&](const auto & self, const string & pointer) noexcept -> void {
			// Выполняем учёт разысканного значения
			walked++;
			/**
			 * Выполняем перебор всех звеньев к детям значения
			 */
			for(const string & key : doc.keys(pointer)){
				// Собираем указатель на очередного ребёнка
				const string child = (pointer + "/" + key);
				// Выполняем проверку того, что выданное звено годно для извлечения
				ASSERT_TRUE(doc.has(child)) << child;
				// Выполняем проверку пригодности разысканного значения
				ASSERT_TRUE(doc.at(child).valid()) << child;
				// Выполняем обход разысканного значения вглубь
				self(self, child);
			}
		};
		// Выполняем обход документа от корня его
		walk(walk, "");
		/**
		 * Выполняем проверку того, что обойдено ВСЁ хранилище документа
		 *
		 * @note Сличение это ловит недостачу: узел, звеном не выданный, остался бы
		 *       необойдённым, и число разошлось бы
		 */
		ASSERT_EQ(walked, doc.nodes());
		// Выполняем проверку записи имён со отменяющими записями RFC 6901
		const vector <string> keys = doc.keys("");
		// Выполняем проверку количества звеньев корня документа
		ASSERT_EQ(keys.size(), static_cast <size_t> (4));
		// Выполняем проверку записи косой черты отменяющей записью
		ASSERT_EQ(keys.at(2), "поле~1с~1чертой");
		// Выполняем проверку записи тильды отменяющей записью
		ASSERT_EQ(keys.at(3), "тильда~0тут");
		/**
		 * Выполняем проверку того, что записанное звено ведёт к тому самому полю
		 *
		 * @note Половина эта важнее первой: звено, записанное неверно, осталось бы
		 *       действительным указателем - он вёл бы к полю ИНОМУ либо в никуда
		 */
		ASSERT_TRUE(doc.has("/поле~1с~1чертой"));
		// Значение поля, разысканного по записанному звену
		int64_t number = 0;
		// Выполняем извлечение значения поля по записанному звену
		ASSERT_TRUE(doc.at("/поле~1с~1чертой").value(number));
		// Выполняем проверку того, что разыскано именно то поле
		ASSERT_EQ(number, static_cast <int64_t> (4));
	}
	/**
	 * Замкнутость обхода дерева разметки
	 *
	 * @note Дерево взято с ДВУМЯ одноимёнными узлами намеренно: звено по имени вело бы к
	 *       первому из них дважды, а второй не разыскался бы вовсе
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем разбор текста разметки
		ASSERT_TRUE(doc.parse("<r><a/><a/><b>текст</b><!--примеч--><c x='1'/></r>"));
		// Количество разысканных обходом узлов
		size_t walked = 0;
		/**
		 * @brief Метод обхода дерева разметки вглубь по звеньям
		 *
		 * @param self ссылка на себя для возвратного зова
		 * @param path путь к обходимому узлу
		 *
		 */
		const auto walk = [&](const auto & self, const string & path) noexcept -> void {
			// Выполняем учёт разысканного узла
			walked++;
			/**
			 * Выполняем перебор всех звеньев к вложенным узлам
			 */
			for(const string & key : doc.keys(path)){
				// Собираем путь к очередному вложенному узлу
				const string child = (path + "/" + key);
				// Выполняем проверку того, что выданное звено годно для извлечения
				ASSERT_TRUE(doc.has(child)) << child;
				// Выполняем проверку пригодности разысканного узла
				ASSERT_TRUE(doc.at(child).valid()) << child;
				// Выполняем обход разысканного узла вглубь
				self(self, child);
			}
		};
		// Выполняем обход дерева от корня его
		walk(walk, "");
		// Выполняем проверку того, что обойдена ВСЯ арена дерева разметки
		ASSERT_EQ(walked, doc.nodes());
		/**
		 * Выполняем проверку того, что пустой путь отдаёт ОДНО звено
		 *
		 * @note Корневой элемент у документа ровно один по XML 1.0, и звено это - имя его
		 */
		const vector <string> roots = doc.keys("");
		// Выполняем проверку количества звеньев пустого пути
		ASSERT_EQ(roots.size(), static_cast <size_t> (1));
		// Выполняем проверку того, что звеном служит имя корневого узла разметки
		ASSERT_EQ(roots.at(0), "r");
		// Перечень звеньев к детям корневого узла разметки
		const vector <string> keys = doc.keys("/r");
		// Выполняем проверку количества звеньев к детям корневого узла
		ASSERT_EQ(keys.size(), static_cast <size_t> (5));
		/**
		 * Выполняем проверку того, что одноимённые узлы получили НОМЕРА
		 *
		 * @note Имя годится звеном лишь при единственности: звено по имени разыскивает
		 *       ПЕРВЫЙ узел с этим именем, и второму одноимённому оно вело бы не туда
		 */
		ASSERT_EQ(keys.at(0), "0");
		// Выполняем проверку того, что второй одноимённый узел получил свой номер
		ASSERT_EQ(keys.at(1), "1");
		// Выполняем проверку того, что единственное имя осталось именем
		ASSERT_EQ(keys.at(2), "b");
		// Выполняем проверку того, что безымянное примечание получило номер
		ASSERT_EQ(keys.at(3), "3");
		// Выполняем проверку того, что единственное имя осталось именем
		ASSERT_EQ(keys.at(4), "c");
		/**
		 * Выполняем проверку ТОЖДЕСТВА разысканных узлов, а не одной их пригодности
		 *
		 * @note Замкнутость ломается тихо: два разных звена вправе вести к ОДНОМУ узлу, а
		 *       третий не разыскаться вовсе, - и перебор числом при том сойдётся
		 */
		ASSERT_FALSE(doc.at("/r/0") == doc.at("/r/1"));
		// Выполняем проверку того, что звено по имени и звено по номеру ведут к одному узлу
		ASSERT_TRUE(doc.at("/r/b") == doc.at("/r/2"));
	}
	/**
	 * Замкнутость обхода у кодека ABC
	 *
	 * @details Хода `keys(путь)` у ABC нет, и договор здесь держится ИНЫМ написанием:
	 *          перебор ведётся курсором - `size`, `key(i)`, `at(i)`, - а розыск ходами
	 *          `get(имя)` и `at(путь)`. Договор же сличается тот самый: что перечислено,
	 *          то обязано разыскиваться, а что разыскано - лежать там, куда указал
	 *          перебор
	 *
	 * @warning Сличается ТОЖДЕСТВО узлов, а не одна их пригодность, - ровно по той же
	 *          причине, что и у прочих: замкнутость ломается тихо, когда два звена ведут
	 *          к одному узлу, а третий не разыскивается вовсе. Перебор числом при том
	 *          сойдётся, и проверка на счёт была бы зелена
	 *
	 * @note Пустое отображение и пустой перечень взяты нарочно: детей у обоих нет, а
	 *       ВИДЫ у них разные, и слить их в одно значило бы потерять различие, какое
	 *       двоичная запись несёт меткой. Пригодность их при этом ИСТИНА - тем они и
	 *       разнятся с путём в никуда, у какого пригодность ложь
	 */
	{
		// Собираемые значения: пустое отображение и пустой перечень
		abc::value_t root, mapping(abc::kind_t::MAP), listing(abc::kind_t::ARRAY);
		// Выполняем набор скалярного значения
		ASSERT_TRUE(root.insert(abc::value_t(string("скаляр")), abc::value_t(int64_t(1))));
		// Выполняем прививку пустого отображения
		ASSERT_TRUE(root.insert(abc::value_t(string("пустой")), mapping));
		// Выполняем прививку пустого перечня
		ASSERT_TRUE(root.insert(abc::value_t(string("порожний")), listing));
		// Выполняем сборку двоичной записи
		const vector <uint8_t> record = root.dump();
		// Объект документа
		abc::document_t doc(::logger());
		// Выполняем разбор двоичной записи документа
		ASSERT_TRUE(doc.parse(record.data(), record.size())) << abc::message(doc.error());
		// Выполняем проверку числа детей корня
		ASSERT_EQ(doc.size(), static_cast <size_t> (3));
		/**
		 * Выполняем перебор всех детей корня документа
		 */
		for(size_t i = 0; i < doc.root().size(); i++){
			// Получаем имя очередного поля отображения
			const abc::document_t::value_t name = doc.root().key(i);
			// Выполняем проверку пригодности полученного имени
			ASSERT_TRUE(name.valid()) << i;
			// Собираем путь к очередному полю отображения
			const string path = ("/" + string(name.data()));
			/**
			 * Выполняем проверку того, что перечисленное РАЗЫСКИВАЕТСЯ
			 */
			ASSERT_TRUE(doc.has(path)) << path;
			// Выполняем проверку пригодности разысканного по пути значения
			ASSERT_TRUE(doc.at(path).valid()) << path;
			/**
			 * Выполняем проверку ТОЖДЕСТВА разысканного узла с перечисленным
			 *
			 * @note Розыск по имени и взятие по номеру обязаны вести к ОДНОМУ узлу;
			 *       сличение их размеров такого не докажет - размеры сойдутся и у
			 *       разных узлов
			 */
			ASSERT_TRUE(doc.at(path).same(doc.root().at(i))) << path;
			// Выполняем проверку того, что розыск по имени ведёт туда же
			ASSERT_TRUE(doc.root().get(string(name.data())).same(doc.root().at(i))) << path;
		}
		/**
		 * Выполняем проверку того, что РАЗНЫЕ поля ведут к разным узлам
		 *
		 * @note Половина эта обязательна: без неё перебор выше прошёл бы и тогда, когда
		 *       всякий розыск отдаёт один и тот же узел
		 */
		ASSERT_FALSE(doc.at("/скаляр").same(doc.at("/пустой")));
		ASSERT_FALSE(doc.at("/пустой").same(doc.at("/порожний")));
		// Выполняем проверку отсутствия детей у скалярного значения
		ASSERT_EQ(doc.at("/скаляр").size(), static_cast <size_t> (0));
		// Выполняем проверку отсутствия детей у пустого отображения
		ASSERT_EQ(doc.at("/пустой").size(), static_cast <size_t> (0));
		// Выполняем проверку отсутствия детей у пустого перечня
		ASSERT_EQ(doc.at("/порожний").size(), static_cast <size_t> (0));
		/**
		 * Выполняем проверку того, что пустые вместилища РАЗЛИЧАЮТСЯ видом
		 *
		 * @warning Детей у обоих нет, и всякая проверка на счёт слила бы их в одно.
		 *          Двоичная запись различие это несёт МЕТКОЙ, и терять его нельзя
		 */
		ASSERT_TRUE(doc.at("/пустой").is(abc::type_t::MAP));
		ASSERT_TRUE(doc.at("/порожний").is(abc::type_t::ARRAY));
		// Выполняем проверку непригодности значения по пути в никуда
		ASSERT_FALSE(doc.at("/нет-такого").valid());
		// Выполняем проверку того, что пути в никуда и вправду нет
		ASSERT_FALSE(doc.has("/нет-такого"));
		// Выполняем проверку непригодности значения глубже листа
		ASSERT_FALSE(doc.at("/скаляр/глубже").valid());
		/**
		 * Выполняем проверку того, что два пути В НИКУДА тождественными НЕ являются
		 *
		 * @warning Половина эта дописана по следам подмены, какая проверку не покрасила:
		 *          довод о ней стоял в исходном тексте, а утверждения не было. Объяви
		 *          тождество две непригодные ссылки равными - и проверка замкнутости
		 *          обхода прошла бы на дереве, где не разыскивается НИЧЕГО: всякий путь
		 *          равнялся бы всякому, а перечисление сошлось бы с розыском по пустоте
		 */
		ASSERT_FALSE(doc.at("/нет-такого").same(doc.at("/тоже-нет")));
		// Выполняем проверку того, что непригодная ссылка не тождественна пригодной
		ASSERT_FALSE(doc.at("/нет-такого").same(doc.at("/скаляр")));
		// Выполняем проверку того, что пригодная ссылка тождественна САМОЙ СЕБЕ
		ASSERT_TRUE(doc.at("/скаляр").same(doc.at("/скаляр")));
		/**
		 * Выполняем проверку того, что корень документа, разбору не подвергавшегося,
		 * НЕПРИГОДЕН
		 *
		 * @note Тем он и разнится с пустым вместилищем: у того пригодность истина при
		 *       нуле детей, у этого ложь. Слить их значило бы обратить «документа нет»
		 *       в «документ пуст», а это разные вещи
		 */
		ASSERT_FALSE(abc::document_t(::logger()).root().valid());
	}
	/**
	 * Выполняем закрепление замкнутости обхода у владеющего значения таблицы
	 *
	 * @details Перечисление у таблицы есть перечень имён СТОЛБЦОВ, и замкнутость его
	 *          означает то же, что у прочих кодеков: всякое выданное имя обязано
	 *          достигаться обходом, а обход - отдавать поле, а не пустоту
	 *
	 * @warning Сличения ЧИСЛА имён недостаточно, и на этом я уже обжигался у разметки:
	 * первая редакция перечисления сходилась восемь из восьми по счёту, а все выданные
	 * пути вели в никуда. Сличать надо ДОСТИЖИМОСТЬ каждого имени поимённо
	 *
	 * @note Обратная сторона обязательна: имя, перечнем НЕ выданное, обходом достигаться
	 *       не должно. Без неё перечень, выдающий лишнее, проходил бы проверку
	 */
	{
		// Объект таблицы
		csv::document_t document(::logger());
		// Получаем настройки таблицы
		auto settings = document.settings();
		// Выполняем указание на присутствие заголовка в первой записи
		settings.reader.header = csv::header_t::PRESENT;
		// Выполняем установку настроек таблицы
		document.settings(settings);
		// Выполняем разбор текста таблицы
		ASSERT_TRUE(document.parse("имя,возраст,рост\r\nАня,30,1.75\r\nБорис,41,1.80\r\n"));
		// Владеющее значение, снятое с таблицы
		const csv::value_t value(document);
		// Получаем перечень имён столбцов таблицы
		const vector <string> & names = value.header();
		// Выполняем проверку непустоты перечня имён столбцов
		ASSERT_EQ(names.size(), static_cast <size_t> (3));
		/**
		 * Выполняем перебор всех выданных имён столбцов
		 */
		for(size_t i = 0; i < names.size(); i++){
			// Выполняем проверку того, что выданное имя перечнем признаётся
			ASSERT_TRUE(value.contains(names[i]));
			// Выполняем проверку того, что номер столбца отвечает его месту в перечне
			ASSERT_EQ(value.column(names[i]), i);
			/**
			 * Выполняем перебор всех записей таблицы
			 */
			for(size_t row = 0; row < value.size(); row++){
				// Собираемый путь к полю записи по имени столбца
				const string path = ("/" + std::to_string(row) + "/" + names[i]);
				// Выполняем проверку достижимости поля обходом по имени
				ASSERT_TRUE(value.at(path).valid());
				/**
				 * Выполняем проверку ТОЖДЕСТВА обхода по имени и по номеру
				 *
				 * @note Сличение это и есть замкнутость: обход по имени обязан
				 *       достигать того же самого поля, что и обход по номеру, а
				 *       не какого-то иного, случайно пригодного
				 */
				ASSERT_EQ(value.at(path).text(), value.at("/" + std::to_string(row) + "/" + std::to_string(i)).text());
			}
		}
		/**
		 * Выполняем проверку того, что перечень лишнего не выдаёт
		 */
		ASSERT_FALSE(value.contains("нет-такого"));
		// Выполняем проверку того, что необъявленное имя обходом не достигается
		ASSERT_FALSE(value.at("/0/нет-такого").valid());
	}
}
/**
 * @brief Документ пригоден к повторному употреблению без роста хранилища
 *
 * @details Потребитель, читающий поток однородных сообщений, заводит документ ОДНАЖДЫ и
 * разбирает в него сообщение за сообщением. Договор при том двойной: прежнее содержимое
 * обязано исчезать целиком, а хранилище - не расти от разбора к разбору
 *
 * @warning Порок роста молчалив вдвойне: разбор отвечает успехом, содержимое верно, а
 *          память прибывает от сообщения к сообщению. У потока без конца это отказ по
 *          памяти через часы работы, и связать его с разбором будет уже нечем
 *
 * @note Сличается СТОКРАТНЫЙ разбор одного текста: рост на один узел за проход виден
 *       лишь на числе проходов, а на двух-трёх потерялся бы в постоянной части
 *
 */
TEST(CodecContract, DocumentIsReusableWithoutStorageGrowth) {
	/**
	 * Повторный разбор сносит прежнее содержимое целиком
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем разбор первого текста документа
		ASSERT_TRUE(doc.parse("{\"первое\":1,\"общее\":1}"));
		// Выполняем разбор второго текста документа
		ASSERT_TRUE(doc.parse("{\"второе\":2}"));
		// Выполняем проверку того, что содержимое первого разбора исчезло
		ASSERT_FALSE(doc.has("/первое"));
		// Выполняем проверку того, что одноимённое поле не пережило разбора
		ASSERT_FALSE(doc.has("/общее"));
		// Выполняем проверку содержимого второго разбора
		ASSERT_EQ(doc.dump(), "{\"второе\":2}");
	}
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем разбор первого текста разметки
		ASSERT_TRUE(doc.parse("<r><первое/><общее/></r>"));
		// Выполняем разбор второго текста разметки
		ASSERT_TRUE(doc.parse("<r><второе/></r>"));
		// Выполняем проверку того, что содержимое первого разбора исчезло
		ASSERT_FALSE(doc.has("/r/первое"));
		// Выполняем проверку содержимого второго разбора
		ASSERT_EQ(doc.dump(), "<r><второе/></r>");
	}
	{
		// Объект таблицы
		csv::document_t doc(::logger());
		// Выполняем разбор первого текста таблицы
		ASSERT_TRUE(doc.parse("a,b\r\n1,2\r\n3,4\r\n"));
		// Выполняем разбор второго текста таблицы
		ASSERT_TRUE(doc.parse("x\r\n9\r\n"));
		// Выполняем проверку числа столбцов после второго разбора
		ASSERT_EQ(doc.cols(), static_cast <size_t> (1));
		// Выполняем проверку содержимого первого поля после второго разбора
		ASSERT_EQ(doc.get(0, 0), "x");
	}
	/**
	 * Разбор поверх дерева, построенного руками, прежнее сносит наравне
	 *
	 * @note Случай этот отдельный: содержимое заведено не разбором, и снести его разбор
	 *       обязан тем же порядком, каким сносит своё
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем прививку значения корнем документа
		ASSERT_TRUE(doc.set("", json::value_t(static_cast <int64_t> (7))));
		// Выполняем разбор текста документа поверх построенного руками
		ASSERT_TRUE(doc.parse("{\"a\":1}"));
		// Выполняем проверку того, что построенное руками исчезло
		ASSERT_EQ(doc.dump(), "{\"a\":1}");
	}
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем прививку собранного значения корнем дерева разметки
		ASSERT_TRUE(doc.set("", xml::value_t("построено")));
		// Выполняем разбор текста разметки поверх построенного руками
		ASSERT_TRUE(doc.parse("<a>1</a>"));
		// Выполняем проверку того, что построенное руками исчезло
		ASSERT_EQ(doc.dump(), "<a>1</a>");
	}
	/**
	 * Стократный разбор одного текста хранилища не растит
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Счёт узлов хранилища после первого разбора
		size_t first = 0;
		/**
		 * Выполняем стократный разбор одного текста документа
		 */
		for(size_t i = 0; i < 100; i++){
			// Выполняем разбор текста документа
			ASSERT_TRUE(doc.parse("{\"a\":1,\"b\":[1,2,3]}"));
			/**
			 * Если разбор был первым
			 */
			if(i == 0)
				// Запоминаем счёт узлов хранилища после первого разбора
				first = doc.nodes();
		}
		// Выполняем проверку непустоты хранилища документа
		ASSERT_GT(first, static_cast <size_t> (0));
		// Выполняем проверку того, что хранилище от разбора к разбору не выросло
		ASSERT_EQ(doc.nodes(), first);
		// Выполняем проверку сохранности содержимого после стократного разбора
		ASSERT_EQ(doc.dump(), "{\"a\":1,\"b\":[1,2,3]}");
	}
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Счёт узлов арены после первого разбора
		size_t first = 0;
		/**
		 * Выполняем стократный разбор одного текста разметки
		 */
		for(size_t i = 0; i < 100; i++){
			// Выполняем разбор текста разметки
			ASSERT_TRUE(doc.parse("<r><a>1</a><b><c/></b></r>"));
			/**
			 * Если разбор был первым
			 */
			if(i == 0)
				// Запоминаем счёт узлов арены после первого разбора
				first = doc.nodes();
		}
		// Выполняем проверку непустоты арены дерева разметки
		ASSERT_GT(first, static_cast <size_t> (0));
		// Выполняем проверку того, что арена от разбора к разбору не выросла
		ASSERT_EQ(doc.nodes(), first);
		// Выполняем проверку сохранности содержимого после стократного разбора
		ASSERT_EQ(doc.dump(), "<r><a>1</a><b><c/></b></r>");
	}
	{
		// Объект таблицы
		csv::document_t doc(::logger());
		/**
		 * Выполняем стократный разбор одного текста таблицы
		 */
		for(size_t i = 0; i < 100; i++)
			// Выполняем разбор текста таблицы
			ASSERT_TRUE(doc.parse("a,b\r\n1,2\r\n3,4\r\n"));
		// Выполняем проверку числа записей после стократного разбора
		ASSERT_EQ(doc.size(), static_cast <size_t> (3));
		// Выполняем проверку числа столбцов после стократного разбора
		ASSERT_EQ(doc.cols(), static_cast <size_t> (2));
	}
	/**
	 * Повторное употребление документа у кодека ABC
	 *
	 * @warning Круги здесь чередуются с ОТКАЗАМИ, и в том сила проверки. Рост копится
	 *          именно на пути отказа: там снятие содержимого зовётся ИНЫМ местом, чем на
	 *          пути успеха, и перебор одних лишь удавшихся разборов остался бы зелен при
	 *          живом пороке. Порок этот у ABC и был - разбор, отказавший на середине,
	 *          оставлял обломок, и обломок ложился в основание следующего разбора
	 *
	 * @note Замер щупом: 200 000 кругов вперемежку с отказами, прирост пика памяти
	 *       НУЛЕВОЙ. Здесь кругов меньше - проверке довольно показать, что счёт узлов и
	 *       содержимое от числа разборов не зависят
	 */
	{
		// Собираемые значения первого и второго разборов
		abc::value_t first, second;
		// Выполняем набор записи первого разбора
		ASSERT_TRUE(first.insert(abc::value_t(string("первое")), abc::value_t(int64_t(1))));
		// Выполняем добавление поля, общего с записью второго разбора
		ASSERT_TRUE(first.insert(abc::value_t(string("общее")), abc::value_t(int64_t(1))));
		// Выполняем набор записи второго разбора
		ASSERT_TRUE(second.insert(abc::value_t(string("второе")), abc::value_t(int64_t(2))));
		// Выполняем сборку двоичных записей обоих разборов
		const vector <uint8_t> older = first.dump(), newer = second.dump();
		// Запись, отказ на которой настигает разбор на середине
		const uint8_t corrupted = 0xA1;
		// Объект документа
		abc::document_t doc(::logger());
		// Выполняем разбор первой записи документа
		ASSERT_TRUE(doc.parse(older.data(), older.size())) << abc::message(doc.error());
		// Выполняем разбор второй записи тем же документом
		ASSERT_TRUE(doc.parse(newer.data(), newer.size())) << abc::message(doc.error());
		// Выполняем проверку того, что содержимое первого разбора исчезло
		ASSERT_FALSE(doc.has("/первое"));
		/**
		 * Выполняем проверку того, что ОДНОИМЁННОЕ поле не пережило разбора
		 *
		 * @note Поле это опаснее прочих: хранилище имён держит указатель по строкам, и
		 *       имя, пережившее сброс, разыскалось бы во ВТОРОМ дереве, указывая на узел
		 *       первого. Проверка на «первое» такого не поймала бы - того имени во
		 *       второй записи нет вовсе
		 */
		ASSERT_FALSE(doc.has("/общее"));
		// Выполняем проверку содержимого второго разбора
		ASSERT_TRUE(doc.has("/второе"));
		// Выполняем проверку числа детей корня после второго разбора
		ASSERT_EQ(doc.size(), static_cast <size_t> (1));
		// Счёт узлов арены, снятый вторым разбором
		const size_t nodes = doc.nodes();
		/**
		 * Выполняем перебор кругов разбора вперемежку с отказами
		 */
		for(size_t i = 0; i < 64; i++){
			// Выполняем наведение отказа негодною записью
			ASSERT_FALSE(doc.parse(&corrupted, sizeof(corrupted))) << i;
			// Выполняем проверку снятия содержимого отказом
			ASSERT_EQ(doc.nodes(), static_cast <size_t> (0)) << i;
			// Выполняем разбор годной записи документа
			ASSERT_TRUE(doc.parse(newer.data(), newer.size())) << i;
			// Выполняем проверку того, что счёт узлов арены не изменился
			ASSERT_EQ(doc.nodes(), nodes) << i;
			// Выполняем проверку того, что содержимое осталось прежним
			ASSERT_TRUE(doc.has("/второе")) << i;
		}
	}
}
/**
 * @brief Проверка того, что запредельная вложенность отвергается, а не рвёт стек
 *
 * @details Место отказа у кодеков РАЗНОЕ, и это не расхождение недосмотром. Документ
 *          JSON огранивает настройку потолком `MAX_DEPTH` до разбора и отвергает
 *          текст на месте превышения. Дерево же разметки текст принимает: арена
 *          узлов плоская, и глубина ей безразлична - стережёт она рекурсивное
 *          снятие значением, и отвергает его целиком. Оба уклада закреплены своими
 *          проверками с доводами, и проверка эта их не спорит, а сводит воедино
 *          общее: запредельная глубина НИГДЕ не проходит насквозь молча
 *
 * @note Довод общности взят замером, а не догадкой. Разбор у обоих кодеков идёт
 *       стеком в поле, не возвратом, и стека работ не рвёт: глубина 100000 у
 *       разметки разобралась, записалась (699997 октетов), отдала содержимое и
 *       розыск вглубь - процесс жив. Оттого сторожем здесь служит не срыв, а
 *       именно отказ, и закреплять надо его
 *
 * @note Проверка эта СЛУЖИТ ДОЗОРОМ на будущее: перевод любого из ходов на возврат
 *       обратит запредельную глубину из отказа в падение всей работы, а падение
 *       приходит на тексте, присланном извне
 */
TEST(CodecContract, ExcessiveNestingIsRefusedAndNeverSmashesTheStack) {
	// Глубина, потолок вложенности заведомо перерастающая
	constexpr size_t DEPTH = 1500;
	/**
	 * Выполняем закрепление уклада документа JSON: отказ на разборе с местом
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Получаем настройки документа
		auto settings = doc.settings();
		// Выполняем поднятие предела вложенности заведомо выше потолка
		settings.reader.maxDepth = 200000;
		// Выполняем установку настроек документа
		doc.settings(settings);
		// Собираемый текст документа
		string text(DEPTH, '[');
		// Выполняем дополнение текста закрывающими скобками
		text.append(DEPTH, ']');
		// Выполняем проверку отказа разбора текста запредельной глубины
		ASSERT_FALSE(doc.parse(text));
		// Выполняем проверку кода отказа разбора текста
		ASSERT_EQ(doc.error(), json::error_t::DEPTH_EXCEEDED);
		/**
		 * Выполняем проверку того, что отказ назвал место превышения
		 *
		 * @note Потолок у документа JSON стережётся ВДВОЙНЕ: огранением настройки до
		 *       разбора и запасным заслоном сборки дерева. Замерено подменою: сними
		 *       огранение - и отказ приходит от заслона, тем же кодом и с тем же
		 *       местом (строка 1, столбец 1025), то есть подмена одной точки здесь
		 *       безвредна. Проверка оттого закрепляет не какую-то из двух точек, а
		 *       сам договор: запредельная глубина отвергается С НАЗВАННЫМ местом
		 */
		ASSERT_EQ(doc.errorLocation().line, static_cast <uint32_t> (1));
		// Выполняем проверку названного столбца превышения потолка вложенности
		ASSERT_GT(doc.errorLocation().column, static_cast <uint32_t> (0));
	}
	/**
	 * Выполняем закрепление уклада дерева разметки: разбор проходит, снятие отвергает
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Получаем настройки дерева разметки
		auto settings = doc.settings();
		// Выполняем поднятие предела вложенности заведомо выше потолка
		settings.reader.maxDepth = 200000;
		// Выполняем установку настроек дерева разметки
		doc.settings(settings);
		// Собираемый текст разметки
		string text;
		/**
		 * Выполняем сборку открывающих узлов разметки
		 */
		for(size_t i = 0; i < DEPTH; i++)
			// Выполняем добавление открывающего узла разметки
			text.append("<a>");
		/**
		 * Выполняем сборку закрывающих узлов разметки
		 */
		for(size_t i = 0; i < DEPTH; i++)
			// Выполняем добавление закрывающего узла разметки
			text.append("</a>");
		// Выполняем проверку того, что дерево текст запредельной глубины принимает
		ASSERT_TRUE(doc.parse(text));
		/**
		 * Выполняем проверку того, что запись глубокого дерева стека не рвёт
		 *
		 * @note Ход этот идёт СТЕКОМ В ПОЛЕ, а не возвратом, и замер тому порукой:
		 *       глубина 100000 записалась целиком, отдав 699997 октетов
		 */
		ASSERT_FALSE(doc.dump().empty());
		// Выполняем проверку отказа снятия значения вместо срыва стека работ
		ASSERT_FALSE(xml::value_t(doc.element()).valid());
	}
	/**
	 * Выполняем закрепление того, что глубина в пределах потолка проходит насквозь
	 *
	 * @note Проверка эта обязательна: отвергай снятие всякую вложенность вовсе, и
	 *       отказ выше выходил бы верным по случайности
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Собираемый текст разметки
		string text;
		/**
		 * Выполняем сборку открывающих узлов разметки
		 */
		for(size_t i = 0; i < 500; i++)
			// Выполняем добавление открывающего узла разметки
			text.append("<a>");
		/**
		 * Выполняем сборку закрывающих узлов разметки
		 */
		for(size_t i = 0; i < 500; i++)
			// Выполняем добавление закрывающего узла разметки
			text.append("</a>");
		// Выполняем проверку успешности разбора текста глубины допустимой
		ASSERT_TRUE(doc.parse(text));
		// Выполняем проверку пригодности снятия значения с корня дерева
		ASSERT_TRUE(xml::value_t(doc.element()).valid());
	}
	/**
	 * Чрезмерная вложенность у кодека ABC
	 *
	 * @details Разбор у ABC ведётся БЕЗ ВОЗВРАТНОСТИ - стек вложенности лежит в куче, а
	 *          не в стеке машины, - и глубина в полторы тысячи ему стек не срывает по
	 *          устройству. Отказ здесь есть решение уклада, а не защита от срыва
	 *
	 * @warning Настройка глубины поднять потолок МОДУЛЯ не может, и в том вся суть
	 *          проверки. Предел выставлен здесь в двести тысяч - заведомо выше потолка, -
	 *          и запись глубиной свыше потолка всё равно отвергается. Сумей настройка
	 *          потолок поднять - и потребитель, поставивший её побольше, получил бы
	 *          расход памяти по чужому слову, ибо глубину задаёт ПОДАННАЯ ЗАПИСЬ
	 *
	 * @note Записи кладутся октетами: `81` есть метка перечня об одном звене, и цепочка
	 *       их даёт вложенность нужной глубины, а `00` в конце - число нуль, лист цепи
	 */
	{
		/**
		 * Работа сборки записи затребованной глубины вложенности
		 */
		const auto nested = [](const size_t depth) noexcept -> vector <uint8_t> {
			// Собираемая запись затребованной глубины
			vector <uint8_t> result(depth, static_cast <uint8_t> (0x81));
			// Выполняем добавление листа цепи вложенности
			result.push_back(static_cast <uint8_t> (0x00));
			// Выводим собранную запись
			return result;
		};
		// Объект документа
		abc::document_t doc(::logger());
		// Получаем настройки документа
		abc::reader_t::settings_t settings = doc.settings();
		// Выполняем поднятие предела вложенности заведомо выше потолка модуля
		settings.maxDepth = 200000;
		// Выполняем установку настроек документа
		doc.settings(settings);
		// Собранная запись глубины, потолок модуля перерастающей
		const vector <uint8_t> excessive = nested(DEPTH);
		// Выполняем проверку отказа разбора записи чрезмерной глубины
		ASSERT_FALSE(doc.parse(excessive.data(), excessive.size()));
		// Выполняем проверку названной причины отказа
		ASSERT_EQ(doc.error(), abc::error_t::DEPTH_EXCEEDED) << abc::message(doc.error());
		// Выполняем проверку того, что содержимого после отказа не осталось
		ASSERT_EQ(doc.nodes(), static_cast <size_t> (0));
		/**
		 * Выполняем проверку того, что глубина ДОПУСТИМАЯ принимается
		 *
		 * @note Половина эта обязательна: отказ на всякой глубине выглядел бы так же,
		 *       и проверка была бы зелена у кодека, не берущего вложенности вовсе
		 */
		const vector <uint8_t> admissible = nested(64);
		// Выполняем проверку успешности разбора записи допустимой глубины
		ASSERT_TRUE(doc.parse(admissible.data(), admissible.size())) << abc::message(doc.error());
		// Выполняем проверку пригодности корня разобранного дерева
		ASSERT_TRUE(doc.root().valid());
	}
}
/**
 * @brief Проверка того, что предел вложенности допускает ровно столько уровней, сколько назван
 *
 * @details Граница у предела ВКЛЮЧАЮЩАЯ: предел в три уровня три уровня и допускает,
 *          а отвергает четвёртый. Уклад этот кажется само собою разумеющимся ровно
 *          до сличения с соседями: у кодека INI граница исключающая и записана
 *          подписью (`ini/reader.hpp`, «при значении в единицу отвергается уже
 *          «[a.b]», где разделитель один»), у кодека TOML - включающая, как здесь.
 *          Один уклад тут не лучше другого, но молчаливая перемена уклада есть
 *          порок: настройка, перенесённая потребителем с кодека на кодек, начнёт
 *          отвергать текст, прежде принимаемый, и без единого слова
 *
 * @note Замер, проверку породивший: предел 3 при глубине 3 проходит у обоих кодеков,
 *       при глубине 4 отвергается; предел 1 при глубине 1 проходит, при глубине 2
 *       отвергается. Сличение на единице обязательно: при исключающей границе предел
 *       в единицу неотличим от нуля, и один уровень настройки пропадает впустую
 *
 * @warning Проверка сторожит СЧЁТ, а не потолок: сличение по одному уровню съезжает
 * от правки сличения `>=` на `>` беззвучно, никакой текст от того не падает, и
 * заметить перемену можно только замером ровно по границе
 */
TEST(CodecContract, TheNestingLimitAdmitsExactlyAsManyLevelsAsItNames) {
	/**
	 * Выполняем закрепление счёта границы у документа JSON
	 */
	{
		/**
		 * Выполняем перебор сличаемых пределов вложенности
		 */
		for(const uint32_t limit : {static_cast <uint32_t> (1), static_cast <uint32_t> (3)}){
			// Объект документа
			json::document_t doc(::logger());
			// Получаем настройки документа
			auto settings = doc.settings();
			// Выполняем установку сличаемого предела вложенности
			settings.reader.maxDepth = limit;
			// Выполняем установку настроек документа
			doc.settings(settings);
			// Собираемый текст документа глубиной ровно по пределу
			string admissible(limit, '[');
			// Выполняем дополнение текста закрывающими скобками
			admissible.append(limit, ']');
			// Выполняем проверку того, что глубина ровно по пределу принимается
			ASSERT_TRUE(doc.parse(admissible));
			// Собираемый текст документа глубиной на уровень выше предела
			string excessive(limit + 1, '[');
			// Выполняем дополнение текста закрывающими скобками
			excessive.append(limit + 1, ']');
			// Выполняем проверку того, что глубина выше предела отвергается
			ASSERT_FALSE(doc.parse(excessive));
			// Выполняем проверку кода отказа разбора текста
			ASSERT_EQ(doc.error(), json::error_t::DEPTH_EXCEEDED);
		}
	}
	/**
	 * Выполняем закрепление счёта границы у дерева разметки
	 */
	{
		/**
		 * Выполняем перебор сличаемых пределов вложенности
		 */
		for(const uint32_t limit : {static_cast <uint32_t> (1), static_cast <uint32_t> (3)}){
			// Объект дерева разметки
			xml::document_t doc(::logger());
			// Получаем настройки дерева разметки
			auto settings = doc.settings();
			// Выполняем установку сличаемого предела вложенности
			settings.reader.maxDepth = limit;
			// Выполняем установку настроек дерева разметки
			doc.settings(settings);
			// Собираемый текст разметки глубиной ровно по пределу
			string admissible;
			/**
			 * Выполняем сборку узлов разметки глубиной ровно по пределу
			 */
			for(uint32_t i = 0; i < limit; i++)
				// Выполняем добавление открывающего узла разметки
				admissible.append("<a>");
			/**
			 * Выполняем закрытие узлов разметки
			 */
			for(uint32_t i = 0; i < limit; i++)
				// Выполняем добавление закрывающего узла разметки
				admissible.append("</a>");
			// Выполняем проверку того, что глубина ровно по пределу принимается
			ASSERT_TRUE(doc.parse(admissible));
			// Собираемый текст разметки глубиной на уровень выше предела
			string excessive;
			/**
			 * Выполняем сборку узлов разметки глубиной выше предела
			 */
			for(uint32_t i = 0; i <= limit; i++)
				// Выполняем добавление открывающего узла разметки
				excessive.append("<a>");
			/**
			 * Выполняем закрытие узлов разметки
			 */
			for(uint32_t i = 0; i <= limit; i++)
				// Выполняем добавление закрывающего узла разметки
				excessive.append("</a>");
			// Выполняем проверку того, что глубина выше предела отвергается
			ASSERT_FALSE(doc.parse(excessive));
			// Выполняем проверку кода отказа разбора текста разметки
			ASSERT_EQ(doc.error(), xml::error_t::DEPTH_EXCEEDED);
		}
	}
	/**
	 * Точность предела вложенности у кодека ABC
	 *
	 * @warning Пределы взяты ТРОЙКОЙ - один, три и восемь, - а не одним. Предел в
	 *          единицу стережёт край: кодек, считающий уровни с нуля, принял бы при нём
	 *          два уровня, и ошибка на единицу осталась бы невидимой у пределов
	 *          побольше, где она тонет в запасе
	 */
	{
		/**
		 * Работа сборки записи затребованной глубины вложенности
		 */
		const auto nested = [](const size_t depth) noexcept -> vector <uint8_t> {
			// Собираемая запись затребованной глубины
			vector <uint8_t> result(depth, static_cast <uint8_t> (0x81));
			// Выполняем добавление листа цепи вложенности
			result.push_back(static_cast <uint8_t> (0x00));
			// Выводим собранную запись
			return result;
		};
		/**
		 * Выполняем перебор сличаемых пределов вложенности
		 */
		for(const uint32_t limit : {static_cast <uint32_t> (1), static_cast <uint32_t> (3), static_cast <uint32_t> (8)}){
			// Объект документа
			abc::document_t doc(::logger());
			// Получаем настройки документа
			abc::reader_t::settings_t settings = doc.settings();
			// Выполняем установку сличаемого предела вложенности
			settings.maxDepth = limit;
			// Выполняем установку настроек документа
			doc.settings(settings);
			// Собранная запись глубиной ровно по пределу
			const vector <uint8_t> admissible = nested(static_cast <size_t> (limit));
			// Выполняем проверку того, что глубина ровно по пределу принимается
			ASSERT_TRUE(doc.parse(admissible.data(), admissible.size()))
				<< "предел " << limit << ": " << abc::message(doc.error());
			// Собранная запись глубиною на уровень выше предела
			const vector <uint8_t> excessive = nested(static_cast <size_t> (limit) + 1);
			// Выполняем проверку того, что глубина выше предела отвергается
			ASSERT_FALSE(doc.parse(excessive.data(), excessive.size())) << "предел " << limit;
			// Выполняем проверку названной причины отказа
			ASSERT_EQ(doc.error(), abc::error_t::DEPTH_EXCEEDED) << abc::message(doc.error());
		}
	}
}
/**
 * @brief Проверка потолка вложенности, стоящего последней рукой у самого дерева
 *
 * @details Огранок вложенности у кодеков ДВЕ, и стерегут они разное. Первая - предел
 *          чтения, настраиваемый потребителем: он бережёт память под стек состояний
 *          разбора. Вторая - потолок МОДУЛЯ, снять который потребитель не может вовсе:
 *          он бережёт стек вызовов у возвратных работ по ГОТОВОМУ дереву, у снятия
 *          владеющим значением и у записи. Первая срабатывает раньше и вторую собою
 *          закрывает, оттого до потолка дело доходит лишь при снятом пределе чтения
 *
 * @warning Числа здесь записаны ЛИТЕРАЛАМИ, а не выведены из постоянных. Правило это
 *          куплено дорого: у JSON проверка потолка строила глубину текста из
 *          `MAX_DEPTH` и сличала её С НЕЮ ЖЕ, обе стороны двигались согласно, и потолок,
 *          сведённый грубою подменою к четырём, не красил НИ ОДНОЙ проверки - всякий
 *          документ глубже четырёх перестал бы читаться молча. Ту же слепоту нашёл у
 *          себя Геннадий тем же щупом в тот же день
 *
 * @note Сличаются ОБА края: глубина ровно в потолок принимается, а превышающая его на
 *       единицу отвергается. Проверка одного лишь отказа прошла бы и при потолке,
 *       сорвавшемся вдвое раньше
 *
 * @note Ноль у предела чтения означает «без предела» у обоих кодеков, но потолок
 *       модуля им НЕ снимается: ноль огранивается наравне с числом завышенным
 *
 */
TEST(CodecContract, TheTreeCeilingHoldsWhenTheReaderLimitIsLifted) {
	// Величины потолков, записанные числами намеренно
	constexpr size_t JSON_CEILING = 1024, XML_CEILING = 1024, ABC_CEILING = 1024;
	/**
	 * Выполняем проверку потолка у дерева документа JSON
	 */
	{
		/**
		 * @brief Метод разбора текста заданной глубины при снятом пределе чтения
		 *
		 * @param depth глубина вложенности разбираемого текста
		 * @return      признак принятия текста разбором
		 *
		 */
		const auto accepts = [](const size_t depth) noexcept -> bool {
			// Объект документа
			json::document_t doc(::logger());
			// Получаем настройки документа
			json::document_t::settings_t settings = doc.settings();
			// Снимаем предел глубины у чтения, оставляя потолок дерева
			settings.reader.maxDepth = 0;
			// Выполняем установку настроек документа
			doc.settings(settings);
			// Собираемый текст документа заданной глубины
			string text(depth, '[');
			// Дописываем закрывающие скобки собираемого текста
			text.append(depth, ']');
			// Выводим признак принятия текста разбором
			return doc.parse(text);
		};
		// Выполняем проверку принятия глубины ровно в потолок
		ASSERT_TRUE(accepts(JSON_CEILING));
		// Выполняем проверку отклонения глубины, потолок превысившей на единицу
		ASSERT_FALSE(accepts(JSON_CEILING + 1));
	}
	/**
	 * Выполняем проверку потолка у владеющего значения разметки
	 *
	 * @note У разметки потолок стоит не у дерева, а у ВЛАДЕЮЩЕГО ЗНАЧЕНИЯ, и место это
	 *       у кодеков разное. Общим остаётся уклад: потолок модуля переживает снятие
	 *       предела чтения, и глубина сверх него отвергается
	 */
	{
		/**
		 * @brief Метод разбора разметки заданной глубины при снятом пределе чтения
		 *
		 * @param depth глубина вложенности разбираемой разметки
		 * @return      признак принятия разметки разбором
		 *
		 */
		const auto accepts = [](const size_t depth) noexcept -> bool {
			// Настройки разбора разметки со снятым пределом глубины
			xml::reader_t::settings_t settings;
			// Снимаем предел глубины у чтения, оставляя потолок значения
			settings.maxDepth = 0;
			// Собираемый текст разметки заданной глубины
			string text;
			// Выполняем сборку открывающих тегов разметки
			for(size_t i = 0; i < depth; i++)
				// Дописываем очередной открывающий тег разметки
				text.append("<a>");
			// Выполняем сборку закрывающих тегов разметки
			for(size_t i = 0; i < depth; i++)
				// Дописываем очередной закрывающий тег разметки
				text.append("</a>");
			// Владеющее значение разметки
			xml::value_t value;
			// Выводим признак принятия разметки разбором
			return value.parse(text, settings);
		};
		// Выполняем проверку принятия глубины ровно в потолок
		ASSERT_TRUE(accepts(XML_CEILING));
		// Выполняем проверку отклонения глубины, потолок превысившей на единицу
		ASSERT_FALSE(accepts(XML_CEILING + 1));
	}
	/**
	 * Выполняем проверку потолка у двоичного контейнера
	 *
	 * @note ABC участвует здесь тем же укладом и по тому же доводу: настройка в ноль
	 *       означает у него не «без предела», а «предел МОДУЛЯ», и оттого постоянная
	 *       потолка есть предел последней руки, а не умолчание настраиваемого поля.
	 *       Мест таких у него четыре у разбора со сборкой и одно у владеющего значения
	 *
	 * @note Запись собирается ОКТЕТАМИ, а не сборщиком: сборщик держит тот же потолок, и
	 *       записи глубже потолка через него не получить вовсе, - а проверять надлежит
	 *       поведение разбора на обоих краях, включая край отвергаемый
	 *
	 */
	{
		/**
		 * @brief Метод разбора записи заданной глубины при снятом пределе чтения
		 *
		 * @param depth глубина вложенности разбираемой записи
		 * @return      признак принятия записи разбором
		 *
		 */
		const auto accepts = [](const size_t depth) noexcept -> bool {
			// Собираемая двоичная запись из вложенных перечней об одном звене
			vector <uint8_t> record(depth, 0x81);
			// Дописываем лист цепи вложенности записи
			record.push_back(0x01);
			// Объект документа
			abc::document_t document(::logger());
			// Получаем настройки документа
			abc::reader_t::settings_t settings = document.settings();
			// Снимаем предел глубины у чтения, оставляя потолок модуля
			settings.maxDepth = 0;
			// Выполняем установку настроек документа
			document.settings(settings);
			// Выводим признак принятия записи разбором
			return document.parse(record.data(), record.size());
		};
		// Выполняем проверку принятия глубины ровно в потолок
		ASSERT_TRUE(accepts(ABC_CEILING));
		// Выполняем проверку отклонения глубины, потолок превысившей на единицу
		ASSERT_FALSE(accepts(ABC_CEILING + 1));
	}
}
/**
 * @brief Проверка договора о повторяющихся именах
 *
 * @details Правило здесь задаёт СТАНДАРТ, и стандарты расходятся: у разметки
 *          повторный атрибут есть ошибка правильности построения (XML 1.0, отказ
 *          безусловный и настройкою не снимаемый), у документа RFC 8259 велит
 *          именам быть уникальными, оставляя поведение при повторе на усмотрение -
 *          оттого повтор здесь настраивается, а по умолчанию отвергается, у таблицы
 *          же RFC 4180 повторных заголовков не запрещает вовсе. Расхождение это
 *          законно и по старшинству правил, и по существу
 *
 * @note Согласовано при этом то, что согласовать МОЖНО: у обоих кодеков, повтор
 *       удерживающих, доступ по имени достаёт ПЕРВОЕ вхождение. Договор этот легко
 *       разошёлся бы недосмотром - у документа удержание живёт правилом `KEEP`, у
 *       таблицы отключением проверки, места разные и общего кода нет
 *
 * @warning Порок расхождения здесь молчалив вдвойне: доступ по имени отдаёт не отказ,
 * а ЧУЖОЕ значение - соседнее поле той же записи. Потребитель, перенёсший разбор с
 * таблицы на документ, получил бы последнее вместо первого, и ни отказа, ни знака
 */
TEST(CodecContract, RepeatedNamesFollowTheStandardAndYieldTheFirstOne) {
	/**
	 * Выполняем закрепление безусловного отказа у дерева разметки
	 *
	 * @note Отказ этот настройкою не снимается НАМЕРЕННО: правильность построения
	 *       стоит выше пожеланий потребителя, и текст, её нарушивший, разметкой
	 *       не является вовсе
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем проверку отказа разбора повторного атрибута узла
		ASSERT_FALSE(doc.parse("<a x=\"1\" x=\"2\"/>"));
		/**
		 * Выполняем проверку отказа при повторе, тождество которого видно лишь
		 * через пространство имён
		 *
		 * @note Ловушка эта у разборщиков самая частая: имена «p:x» и «q:x» разнятся
		 *       записью, а обозначают одно и то же, ибо оба префикса объявлены одним
		 *       обозначением - и повтор здесь такой же, как явный
		 */
		ASSERT_FALSE(doc.parse("<a xmlns:p=\"u\" xmlns:q=\"u\" p:x=\"1\" q:x=\"2\"/>"));
		// Выполняем проверку отказа повторного объявления одного префикса
		ASSERT_FALSE(doc.parse("<a xmlns:p=\"u\" xmlns:p=\"v\"/>"));
		/**
		 * Выполняем проверку того, что разные обозначения повтором НЕ считаются
		 */
		ASSERT_TRUE(doc.parse("<a xmlns:p=\"u\" xmlns:q=\"v\" p:x=\"1\" q:x=\"2\"/>"));
		/**
		 * Выполняем проверку того, что атрибут без префикса пространству имён
		 * по умолчанию НЕ принадлежит
		 *
		 * @note Обратная сторона той же ловушки, и промах здесь противоположный:
		 *       посчитай мы «x» принадлежащим обозначению «u», объявленному по
		 *       умолчанию, и запись эта отвергалась бы повтором - а она правильна
		 */
		ASSERT_TRUE(doc.parse("<a xmlns=\"u\" x=\"1\" xmlns:p=\"u\" p:x=\"2\"/>"));
		/**
		 * Выполняем закрепление отказа на ДОРОГЕ ЧЕРЕЗ СВОД
		 *
		 * @details Розыск повтора идёт двумя дорогами: попарным сличением, покуда
		 *          имён немного, и раскладкою по свёртке, когда их больше тридцати
		 *          двух. Дороги эти РАЗНЫЕ и кодом общего не имеют, а проверка на
		 *          двух атрибутах достаёт лишь первую из них
		 *
		 * @note Замером установлено: порог равен тридцати двум, и дорог этих две у
		 *       атрибутов узла и ещё две у объявлений пространств имён - всего
		 *       четыре места отказа. Подмена каждого поодиночке показала, что
		 *       проверка на двух именах достаёт из них только одно
		 *
		 * @warning Порок непокрытой дороги здесь особенно тих: тексты с тремя
		 * десятками атрибутов у одного узла редки, и отказ, на ней пропавший, вышел
		 * бы наружу не разбором своего образца, а чужим текстом много позже
		 */
		{
			// Собираемый текст разметки со множеством атрибутов узла
			string text("<a");
			/**
			 * Выполняем сборку атрибутов числом выше порога дороги
			 */
			for(size_t i = 0; i < 40; i++)
				// Выполняем добавление очередного атрибута узла
				text.append(" k").append(std::to_string(i)).append("=\"v\"");
			// Выполняем добавление повторного имени атрибута
			text.append(" x=\"1\" x=\"2\"/>");
			// Выполняем проверку отказа разбора повтора на дороге через свод
			ASSERT_FALSE(doc.parse(text));
		}
		{
			// Собираемый текст разметки со множеством объявлений пространств имён
			string text("<a");
			/**
			 * Выполняем сборку объявлений числом выше порога дороги
			 */
			for(size_t i = 0; i < 40; i++)
				// Выполняем добавление очередного объявления пространства имён
				text.append(" xmlns:n").append(std::to_string(i)).append("=\"u").append(std::to_string(i)).append("\"");
			// Выполняем добавление повторного объявления одного префикса
			text.append(" xmlns:z=\"w\" xmlns:z=\"w2\"/>");
			// Выполняем проверку отказа разбора повтора объявлений через свод
			ASSERT_FALSE(doc.parse(text));
		}
	}
	/**
	 * Выполняем закрепление настраиваемого правила у документа
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем проверку отказа повторного имени правилом по умолчанию
		ASSERT_FALSE(doc.parse("{\"a\":1,\"a\":2}"));
		// Получаем настройки документа
		auto settings = doc.settings();
		// Выполняем установку правила удержания всех повторов
		settings.duplicates = json::duplicate_t::KEEP;
		// Выполняем установку настроек документа
		doc.settings(settings);
		// Выполняем проверку принятия повторного имени правилом удержания
		ASSERT_TRUE(doc.parse("{\"a\":1,\"a\":2}"));
		// Выполняем проверку сохранности ОБОИХ вхождений при записи
		ASSERT_EQ(doc.dump(), "{\"a\":1,\"a\":2}");
		// Извлекаемое по имени значение
		int64_t value = 0;
		// Выполняем извлечение значения по повторяющемуся имени
		ASSERT_TRUE(doc.root()["a"].value(value));
		// Выполняем проверку того, что доступ по имени достал ПЕРВОЕ вхождение
		ASSERT_EQ(value, static_cast <int64_t> (1));
	}
	/**
	 * Выполняем закрепление уклада таблицы
	 */
	{
		// Объект таблицы
		csv::document_t doc(::logger());
		// Получаем настройки таблицы
		auto settings = doc.settings();
		// Выполняем указание на присутствие заголовка в первой записи
		settings.reader.header = csv::header_t::PRESENT;
		// Выполняем установку настроек таблицы
		doc.settings(settings);
		/**
		 * Выполняем проверку отказа повторного имени столбца проверкой по умолчанию
		 */
		ASSERT_FALSE(doc.parse("a,a\r\n1,2\r\n"));
		// Выполняем отключение проверки повторных имён столбцов
		settings.reader.duplicates = false;
		// Выполняем установку настроек таблицы
		doc.settings(settings);
		// Выполняем проверку принятия повтора при отключённой проверке
		ASSERT_TRUE(doc.parse("a,a\r\n1,2\r\n"));
		// Выполняем проверку того, что доступ по имени достал ПЕРВЫЙ столбец
		ASSERT_EQ(doc.get(0, "a"), "1");
		/**
		 * Выполняем проверку того, что второй столбец достижим лишь номером
		 *
		 * @note Уклад этот записан подписью настройки: отключение есть отказ от
		 *       расхода, а НЕ разрешение повтора, и столбец, по имени недостижимый,
		 *       молчит - ни отказа, ни знака
		 */
		ASSERT_EQ(doc.get(0, static_cast <size_t> (1)), "2");
		/**
		 * Выполняем проверку того, что заголовок, поданный извне, повтор отвергает
		 * ВСЕГДА, отключения проверки не спрашивая
		 *
		 * @note Расхождение это намеренно и записано: проверка там свободна от
		 *       расхода на разбор, ради которого отключение и заведено
		 */
		ASSERT_FALSE(doc.header(vector <string> {"a", "a"}));
	}
	/**
	 * Повторные имена у кодека ABC
	 *
	 * @details Уклад ABC здесь богаче прочих: он не один, а ЧЕТЫРЕ, и выбирается
	 *          настройкою разбора. Причина в том, что вид записи двоичный и повтор в нём
	 *          законен по устройству - метка отображения несёт число пар, а не запрет
	 *          на совпадение имён, - оттого решать судьбу повтора обязан потребитель, а
	 *          не кодек за него
	 *
	 * @note Общее у ABC с прочими одно и главное: как бы повтор ни разрешался, доступ
	 *       ПО ИМЕНИ выдаёт значение, встреченное ПЕРВЫМ. Уклад `KEEP` держит обе пары -
	 *       детей у корня два, - а `at` отдаёт первую, ровно как таблица отдаёт первый
	 *       столбец
	 *
	 * @warning Уклады сличаются ЗНАЧЕНИЯМИ, а не одним лишь счётом детей. `FIRST` и
	 *          `LAST` дают по одному ребёнку оба, и проверка на счёт их не различила бы
	 *          вовсе - зелёная при укладе, взятом наоборот. Оттого запись и несёт РАЗНЫЕ
	 *          значения у повторяющегося имени, единицу и двойку
	 */
	{
		/**
		 * Двоичная запись отображения о двух парах с ОДНИМ именем: «a» → 1 и «a» → 2
		 *
		 * @note Запись кладётся октетами: собрать её владеющим значением нельзя, ибо оно
		 *       повтора не допускает - `insert` вторую пару отвергнет. Повтор приходит
		 *       ИЗВНЕ, от чужого писателя, и разбор обязан знать, что с ним делать
		 */
		const vector <uint8_t> record = {0xA2, 0x41, 0x61, 0x01, 0x41, 0x61, 0x02};
		/**
		 * Уклад отказа: повтор отвергается разбором
		 */
		{
			// Объект документа
			abc::document_t doc(::logger());
			// Получаем настройки документа
			abc::reader_t::settings_t settings = doc.settings();
			// Устанавливаем укладом отказ разбора при повторе
			settings.duplicates = abc::duplicate_t::REFUSE;
			// Выполняем установку настроек документа
			doc.settings(settings);
			// Выполняем проверку отказа разбора записи с повтором
			ASSERT_FALSE(doc.parse(record.data(), record.size()));
			// Выполняем проверку названной причины отказа
			ASSERT_EQ(doc.error(), abc::error_t::DUPLICATE_KEY) << abc::message(doc.error());
			// Выполняем проверку отсутствия усечённого содержимого
			ASSERT_EQ(doc.nodes(), static_cast <size_t> (0));
		}
		/**
		 * Уклады сохранения: первым, последним и обоими
		 */
		{
			// Перечень укладов вместе с ожидаемым от них
			const vector <tuple <abc::duplicate_t, size_t, uint64_t>> rules = {
				{abc::duplicate_t::FIRST, static_cast <size_t> (1), static_cast <uint64_t> (1)},
				{abc::duplicate_t::LAST,  static_cast <size_t> (1), static_cast <uint64_t> (2)},
				{abc::duplicate_t::KEEP,  static_cast <size_t> (2), static_cast <uint64_t> (1)}
			};
			/**
			 * Выполняем перебор всех укладов сохранения
			 */
			for(auto & rule : rules){
				// Объект документа
				abc::document_t doc(::logger());
				// Получаем настройки документа
				abc::reader_t::settings_t settings = doc.settings();
				// Выполняем установку уклада повторных имён
				settings.duplicates = ::std::get <0> (rule);
				// Выполняем установку настроек документа
				doc.settings(settings);
				// Выполняем разбор записи с повтором
				ASSERT_TRUE(doc.parse(record.data(), record.size())) << abc::message(doc.error());
				// Выполняем проверку числа детей корня, укладом положенного
				ASSERT_EQ(doc.size(), ::std::get <1> (rule));
				// Получаем значение, доступное по повторяющемуся имени
				const abc::document_t::value_t value = doc.at("/a");
				// Выполняем проверку пригодности значения, доступного по имени
				ASSERT_TRUE(value.valid());
				// Извлекаемое значение поля отображения
				uint64_t number = 0;
				// Выполняем извлечение значения поля числом
				ASSERT_TRUE(value.value(number));
				// Выполняем проверку значения, укладом положенного
				ASSERT_EQ(number, ::std::get <2> (rule));
			}
		}
	}
}
/**
 * @brief Проверка договора об управляющих знаках в содержимом
 *
 * @details Правило здесь у каждого кодека СВОЁ, и всякое оно продиктовано своим
 *          стандартом: RFC 8259 запрещает знаки от `U+0000` до `U+001F` внутри
 *          строки неэкранированными, оставляя дорогу управляющей последовательности;
 *          XML 1.0 запрещает их в тексте ВОВСЕ, и запрет этот ссылкою на знак не
 *          обходится, ибо ссылка обязана указывать на знак допустимый; RFC 4180
 *          держит вне допустимого набора все управляющие разом, а разбор таблицы
 *          делает одно исключение - для горизонтальной табуляции, ибо ею полем
 *          разделяют повсеместно
 *
 * @warning Проверка эта стоит ЗАСЛОНОМ ПРОТИВ ЕДИНООБРАЗИЯ: расхождение здесь есть
 * итог верный, и всякий, кто сведёт три правила к одному, сломает ровно один
 * стандарт из трёх - молча и с виду улучшив согласованность API
 *
 * @note Сличать надо обе стороны у каждого: один лишь отказ доказывался бы и
 *       заслоном, отвергающим всё подряд
 */
TEST(CodecContract, ControlCharactersFollowEachStandardSeparately) {
	/**
	 * Выполняем закрепление правила документа: сырой отвергнут, экранированный принят
	 */
	{
		// Объект документа
		json::document_t doc(::logger());
		// Собираемый текст документа с сырым управляющим знаком
		string text("{\"a\":\"x");
		// Выполняем добавление сырого управляющего знака
		text.push_back(static_cast <char> (0x01));
		// Выполняем закрытие текста документа
		text.append("y\"}");
		// Выполняем проверку отказа разбора сырого управляющего знака
		ASSERT_FALSE(doc.parse(text));
		/**
		 * Выполняем проверку отказа сырой табуляции внутри строки
		 *
		 * @note Табуляция тут отвергается наравне с прочими: `U+0009` лежит в том же
		 *       запретном промежутке, и послабления ей RFC 8259 не делает - вот
		 *       первое из трёх мест, где правила кодеков расходятся
		 */
		{
			// Собираемый текст документа с сырой табуляцией
			string tabbed("{\"a\":\"x");
			// Выполняем добавление сырой табуляции
			tabbed.push_back('\t');
			// Выполняем закрытие текста документа
			tabbed.append("y\"}");
			// Выполняем проверку отказа разбора сырой табуляции
			ASSERT_FALSE(doc.parse(tabbed));
		}
		// Выполняем проверку принятия того же знака управляющей последовательностью
		ASSERT_TRUE(doc.parse("{\"a\":\"x\\u0001y\"}"));
	}
	/**
	 * Выполняем закрепление правила разметки: запрет полный, ссылкою не обходимый
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Собираемый текст разметки с сырым управляющим знаком
		string text("<a>x");
		// Выполняем добавление сырого управляющего знака
		text.push_back(static_cast <char> (0x01));
		// Выполняем закрытие текста разметки
		text.append("y</a>");
		// Выполняем проверку отказа разбора сырого управляющего знака
		ASSERT_FALSE(doc.parse(text));
		/**
		 * Выполняем проверку того, что ссылка на знак запрета НЕ обходит
		 *
		 * @note Тут пролегает граница между разметкой и документом: у документа
		 *       управляющая последовательность есть дорога законная, у разметки
		 *       ссылка обязана указывать на знак, разметке допустимый, и `&#1;`
		 *       отвергается ровно так же, как знак сырой
		 */
		ASSERT_FALSE(doc.parse("<a>x&#1;y</a>"));
		// Выполняем проверку отказа ссылки на знак с нулевым кодом
		ASSERT_FALSE(doc.parse("<a>x&#0;y</a>"));
		/**
		 * Выполняем проверку принятия допустимых пробельных знаков
		 *
		 * @note Табуляция и перевод строки разметке допустимы, и без этой стороны
		 *       отказ выше доказывался бы заслоном, отвергающим всё подряд
		 */
		ASSERT_TRUE(doc.parse("<a>x\ty\nz</a>"));
		// Выполняем проверку принятия ссылки на допустимый знак возврата каретки
		ASSERT_TRUE(doc.parse("<a>x&#xD;y</a>"));
	}
	/**
	 * Выполняем закрепление правила таблицы: запрет всех, кроме табуляции
	 */
	{
		/**
		 * Выполняем перебор управляющих знаков, таблице недопустимых
		 */
		for(const int letter : {0x00, 0x01, 0x08, 0x0B, 0x0C, 0x1B, 0x1F, 0x7F}){
			// Объект таблицы
			csv::document_t doc(::logger());
			// Собираемый текст таблицы с управляющим знаком
			string text("a");
			// Выполняем добавление управляющего знака
			text.push_back(static_cast <char> (letter));
			// Выполняем закрытие записи таблицы
			text.append("b\r\n");
			// Выполняем проверку отказа разбора управляющего знака
			ASSERT_FALSE(doc.parse(text));
			// Выполняем проверку кода отказа разбора текста таблицы
			ASSERT_EQ(doc.error(), csv::error_t::INVALID_CHARACTER);
		}
		{
			// Объект таблицы
			csv::document_t doc(::logger());
			/**
			 * Выполняем проверку принятия горизонтальной табуляции
			 *
			 * @note Исключение это записано договором и сделано намеренно: табуляцией
			 *       поля разделяют повсеместно, и отказ по ней отверг бы обычай,
			 *       никому не мешающий
			 */
			ASSERT_TRUE(doc.parse("a\tb\r\n"));
		}
	}
	/**
	 * Управляющие знаки у кодека ABC
	 *
	 * @details Сторона ABC здесь СВОЯ и от текстовых кодеков отлична начисто: строка у
	 *          него несёт ОБЪЯВЛЕННУЮ ДЛИНУ, а не завершается разделителем, и потому
	 *          знак управляющий не значит для разбора ничего - он обычное содержимое.
	 *          Отвергать его не на что сослаться: ни один октет строки не может оборвать
	 *          её или увести разбор, ибо длина известна заранее
	 *
	 * @note Нуль здесь взят НАРОЧНО, и он же довод решающий. У текстовых кодеков нуль
	 *       обрывает строку, у ABC он равноправный октет её содержимого. Кодек, тайно
	 *       положивший строку в `char *`, потерял бы на нём хвост - и потеря эта была бы
	 *       молчаливой, ибо разбор ответил бы успехом
	 *
	 * @warning Отказ у ABC всё же есть, но основание его ИНОЕ - негодная кодировка, а не
	 *          управляющий знак. Половина эта обязательна: без неё сторона ABC читалась
	 *          бы «принимает всякий октет подряд», а это неправда, и потребитель,
	 *          понадеявшийся на такое чтение, положил бы в строку что попало
	 */
	{
		// Собираемое содержимое строки с сырыми управляющими знаками
		string body("x");
		// Выполняем добавление управляющего знака
		body.push_back(static_cast <char> (0x01));
		// Выполняем добавление табуляции
		body.push_back('\t');
		// Выполняем добавление НУЛЯ содержимым строки
		body.push_back(static_cast <char> (0x00));
		// Выполняем добавление перевода строки
		body.push_back('\n');
		// Выполняем дополнение содержимого строки
		body.append("y");
		// Собираемое значение
		abc::value_t root;
		// Выполняем набор записи со строкой из управляющих знаков
		ASSERT_TRUE(root.insert(abc::value_t(string("поле")), abc::value_t(body)));
		// Выполняем сборку двоичной записи
		const vector <uint8_t> record = root.dump();
		// Объект документа
		abc::document_t doc(::logger());
		// Выполняем проверку успешности разбора записи с управляющими знаками
		ASSERT_TRUE(doc.parse(record.data(), record.size())) << abc::message(doc.error());
		// Получаем значение поля с управляющими знаками
		const abc::document_t::value_t value = doc.at("/поле");
		// Выполняем проверку пригодности полученного значения
		ASSERT_TRUE(value.valid());
		/**
		 * Выполняем проверку СОВПАДЕНИЯ содержимого строки октет в октет
		 *
		 * @note Сличается содержимое целиком, а не одна его длина: длина сошлась бы и
		 *       при потерянном нуле, замени его кодек чем угодно об одном октете
		 */
		ASSERT_EQ(value.data().size(), body.size());
		ASSERT_EQ(string(value.data()), body);
		/**
		 * Выполняем проверку отказа разбора строки, кодировке НЕ отвечающей
		 *
		 * @note Запись здесь кладётся октетами: собрать негодную строку владеющим
		 *       значением нельзя, ибо оно её не примет, - а приходит она ИЗВНЕ
		 */
		{
			// Запись отображения со строкой, несущей октет вне кодировки
			const vector <uint8_t> malformed = {0xA1, 0x44, 0xD0, 0x9F, 0x62, 0xFF, 0x01};
			// Объект документа
			abc::document_t broken(::logger());
			// Выполняем проверку отказа разбора негодной строки
			ASSERT_FALSE(broken.parse(malformed.data(), malformed.size()));
			// Выполняем проверку названной причины отказа
			ASSERT_EQ(broken.error(), abc::error_t::INVALID_ENCODING) << abc::message(broken.error());
		}
	}
}
/**
 * @brief Проверка того, что наличие вложенного значения спрашивается одним словом
 *
 * @details Договор здесь не о поведении, а об ИМЕНИ, и оттого проверкою обычной не
 *          стережётся вовсе: ход, названный иначе, работает верно, проверки свои
 *          проходит, и расхождение живёт до первого потребителя, переносящего разбор
 *          с кодека на кодек
 *
 * @note Уклад общий таков: у ДОКУМЕНТА наличие по пути спрашивается словом `has`, а у
 *       ВЛАДЕЮЩЕГО ЗНАЧЕНИЯ наличие вложенного по имени - словом `contains`. Разделение
 *       не прихоть: у разметки слово `has` занято под наличие СВОЙСТВА узла, величины
 *       иной, и сведи мы оба хода к одному имени - потребитель попадал бы в ход об
 *       ином предмете
 *
 * @warning Проверка эта закрепляет имена САМИМ ФАКТОМ вызова: строка, зовущая
 * `contains` у трёх значений, перестанет собираться в тот день, когда имя у одного из
 * них разойдётся. Иного способа устеречь имя у проверки нет - утверждать тут нечего,
 * кроме того, что вызов существует
 *
 * @note Расхождение это было НАСТОЯЩИМ: владеющее значение таблицы завелось со словом
 *       `has`, взятым по образцу своего же документа, и вскрылось оно сличением
 *       состава ходов, а не проверкою. Проверка заведена, чтобы вскрывать впредь
 *       сборкой
 */
TEST(CodecContract, PresenceOfANestedValueIsAskedByOneWord) {
	/**
	 * Выполняем закрепление имени у владеющего значения документа
	 */
	{
		// Объект владеющего значения документа
		json::value_t value;
		// Выполняем разбор текста документа
		ASSERT_TRUE(value.parse("{\"поле\":1}"));
		// Выполняем проверку наличия объявленного поля
		ASSERT_TRUE(value.contains("поле"));
		// Выполняем проверку отсутствия неназванного поля
		ASSERT_FALSE(value.contains("нет-такого"));
	}
	/**
	 * Выполняем закрепление имени у владеющего значения разметки
	 */
	{
		// Объект владеющего значения разметки
		xml::value_t value;
		// Выполняем разбор текста разметки
		ASSERT_TRUE(value.parse("<a><узел/></a>"));
		/**
		 * @note Обращение идёт к корневому УЗЛУ, а не к самому значению: значение
		 *       разметки держит документ целиком, и вложенные узлы лежат у корня
		 */
		const xml::value_t & root = value[static_cast <size_t> (0)];
		// Выполняем проверку наличия объявленного узла
		ASSERT_TRUE(root.contains("узел"));
		// Выполняем проверку отсутствия неназванного узла
		ASSERT_FALSE(root.contains("нет-такого"));
		/**
		 * Выполняем закрепление того, что слово `has` у разметки занято ИНЫМ
		 *
		 * @note Ровно тот довод, ради которого имена и разведены: `has` спрашивает
		 *       наличие свойства узла, а не вложенного узла, и свести их к одному
		 *       имени значило бы завести западню
		 */
		ASSERT_FALSE(root.has("узел"));
	}
	/**
	 * Выполняем закрепление имени у владеющего значения таблицы
	 */
	{
		// Объект таблицы
		csv::document_t document(::logger());
		// Получаем настройки таблицы
		auto settings = document.settings();
		// Выполняем указание на присутствие заголовка в первой записи
		settings.reader.header = csv::header_t::PRESENT;
		// Выполняем установку настроек таблицы
		document.settings(settings);
		// Выполняем разбор текста таблицы
		ASSERT_TRUE(document.parse("столбец\r\nзначение\r\n"));
		// Владеющее значение, снятое с таблицы
		const csv::value_t value(document);
		// Выполняем проверку наличия объявленного столбца
		ASSERT_TRUE(value.contains("столбец"));
		// Выполняем проверку отсутствия неназванного столбца
		ASSERT_FALSE(value.contains("нет-такого"));
	}
	/**
	 * Выполняем закрепление имени у документов всех трёх кодеков
	 *
	 * @note Сторона эта обязательна: закрепи мы одни значения, и уклад «у документа
	 *       has, у значения contains» держался бы половиною, а разойтись мог бы с
	 *       любой из двух
	 */
	{
		// Объект документа
		json::document_t plain(::logger());
		// Выполняем разбор текста документа
		ASSERT_TRUE(plain.parse("{\"поле\":1}"));
		// Выполняем проверку наличия значения по пути
		ASSERT_TRUE(plain.has("/поле"));
		// Объект дерева разметки
		xml::document_t markup(::logger());
		// Выполняем разбор текста разметки
		ASSERT_TRUE(markup.parse("<a><узел/></a>"));
		// Выполняем проверку наличия узла по пути
		/**
		 * @note Путь у разметки строится от имени КОРНЕВОГО элемента: «keys("")»
		 *       отдаёт одно звено - имя корня, и обход через него замкнут
		 */
		ASSERT_TRUE(markup.has("/a/узел"));
		// Объект таблицы
		csv::document_t table(::logger());
		// Получаем настройки таблицы
		auto settings = table.settings();
		// Выполняем указание на присутствие заголовка в первой записи
		settings.reader.header = csv::header_t::PRESENT;
		// Выполняем установку настроек таблицы
		table.settings(settings);
		// Выполняем разбор текста таблицы
		ASSERT_TRUE(table.parse("столбец\r\nзначение\r\n"));
		// Выполняем проверку наличия столбца по имени
		ASSERT_TRUE(table.has("столбец"));
	}
}
/**
 * @brief Проверка того, что правка обесценивает взятое прежде
 *
 * @details Ссылка на узел дерева живёт не сама по себе: правка переселяет узлы, а
 *          снос освобождает их место под новые. Ссылка, правку пережившая, читала бы
 *          ЧУЖОЕ содержимое - молча, не падая и не подавая знака. Оттого договор
 *          требует, чтобы всякая правка обращала взятое прежде в непригодное, и
 *          потребитель узнавал о том опросом, а не по искажённым данным
 *
 * @note Стережётся это КЛЕЙМОМ ПОКОЛЕНИЯ: дерево наращивает его при всякой правке, а
 *       ссылка помнит то, при каком взята. Сличение клейм и отвечает на вопрос о
 *       пригодности
 *
 * @warning Перебирать надо ВСЕ ходы правки, а не один: клеймо наращивается в каждом
 * из них порознь, и ход, забывший его нарастить, оставляет ссылку живой по виду.
 * Замер у разметки до заведения проверки: все три хода - установка, снос и сброс -
 * обесценивают узел исправно, но поверено это не было ничем
 *
 * @note Проверка эта не первая по предмету, и говорится это прямо: у разметки своя
 *       проверка обесценивания есть давно (CodecXmlDocument.EditingInvalidatesTheNodesTakenBefore),
 *       и покрывает она те же три хода. Общая добавляет к ней две вещи: сличение
 *       обоих кодеков под одним договором и случай ПРИВИВКИ КОРНЯ, который у частной
 *       не покрыт - а дорога у него своя, и клеймо там наращивается своею строкою
 *
 * @note Таблица в проверку не входит НАМЕРЕННО: своих ссылок на записи у неё нет, а
 *       выдаётся вид в хранилище знаков, и чтение его после правки есть поведение
 *       неопределённое, закреплению не подлежащее. Защита там иная - владеющее
 *       значение, и она закреплена проверкою CodecCsvValue.TakenValueSurvivesTheStorageMove
 */
TEST(CodecContract, EditingInvalidatesWhatWasTakenBefore) {
	/**
	 * Выполняем перебор всех ходов правки дерева документа
	 */
	for(uint8_t operation = 0; operation < 3; operation++){
		// Объект документа
		json::document_t doc(::logger());
		// Выполняем разбор текста документа
		ASSERT_TRUE(doc.parse("{\"a\":\"первое\",\"b\":1}"));
		// Снимаем значение соседа правимого места
		const json::document_t::value_t value = doc.at("/a");
		// Выполняем проверку пригодности снятого значения до правки
		ASSERT_TRUE(value.valid()) << static_cast <uint32_t> (operation);
		/**
		 * Выполняем правку дерева документа выбранным ходом
		 */
		switch(operation){
			// Выполняем правку значения по указателю
			case 0: ASSERT_TRUE(doc.set("/b", json::value_t(static_cast <int64_t> (7)))); break;
			// Выполняем снос значения по указателю
			case 1: ASSERT_TRUE(doc.erase("/b")); break;
			// Выполняем сброс значения по указателю
			case 2: ASSERT_TRUE(doc.reset("/b")); break;
		}
		// Выполняем проверку обесценивания снятого значения правкой
		ASSERT_FALSE(value.valid()) << static_cast <uint32_t> (operation);
	}
	/**
	 * Выполняем перебор всех ходов правки дерева разметки
	 *
	 * @note Сторона эта и была непокрытой: у документа договор поверен давно, а у
	 *       разметки держался поведением, ничем не закреплённым
	 */
	for(uint8_t operation = 0; operation < 3; operation++){
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем разбор текста разметки
		ASSERT_TRUE(doc.parse("<root><a>первое</a><b>второе</b></root>"));
		// Снимаем узел соседа правимого места
		const auto node = doc.at("/root/a");
		// Выполняем проверку пригодности снятого узла до правки
		ASSERT_TRUE(static_cast <bool> (node)) << static_cast <uint32_t> (operation);
		/**
		 * Выполняем правку дерева разметки выбранным ходом
		 */
		switch(operation){
			// Выполняем правку узла по пути
			case 0: ASSERT_TRUE(doc.set("/root/b", xml::value_t("новый"))); break;
			// Выполняем снос узла по пути
			case 1: ASSERT_TRUE(doc.erase("/root/b")); break;
			// Выполняем сброс узла по пути
			case 2: ASSERT_TRUE(doc.reset("/root/b")); break;
		}
		// Выполняем проверку обесценивания снятого узла правкой
		ASSERT_FALSE(static_cast <bool> (node)) << static_cast <uint32_t> (operation);
	}
	/**
	 * Выполняем закрепление обесценивания ПРИВИВКОЙ КОРНЯ
	 *
	 * @details Прививка корня пустым путём идёт дорогою СВОЕЙ, отдельной от правки
	 *          вложенного узла: она правит нумерацию узлов арены, а через очистку не
	 *          проходит. Оттого клеймо наращивается там своею строкою, и проверка,
	 *          правящая один лишь вложенный узел, до неё не достаёт
	 *
	 * @note Пробел этот вскрыт поштучной подменою клейма: из четырёх мест наращивания
	 *       три краснели, а четвёртое - место прививки корня - проходило молча. Замер
	 *       щупом подтвердил, что место живо и договор держит: узел, снятый до
	 *       прививки, после неё непригоден
	 */
	{
		// Объект дерева разметки
		xml::document_t doc(::logger());
		// Выполняем разбор текста разметки
		ASSERT_TRUE(doc.parse("<root><a>первое</a></root>"));
		// Снимаем узел, прививку переживающий
		const auto node = doc.at("/root/a");
		// Выполняем проверку пригодности снятого узла до прививки
		ASSERT_TRUE(static_cast <bool> (node));
		// Выполняем прививку нового корня дерева разметки
		ASSERT_TRUE(doc.set("", xml::value_t("иной")));
		// Выполняем проверку обесценивания снятого узла прививкою корня
		ASSERT_FALSE(static_cast <bool> (node));
	}
}
/**
 * @brief Проверка согласия двух дорог розыска по обе стороны порога указателя
 *
 * @details Розыск вложенного по имени идёт ДВУМЯ дорогами: покуда детей немного -
 *          перебором, а с порога `INDEX_THRESHOLD` строится указатель имён. Дороги
 *          эти разные и кодом общего не имеют, а отвечать обязаны ОДНО
 *
 * @warning Порок расхождения тих по устройству: оброни указатель одно имя - и дерево
 * о шестнадцати детях повело бы себя иначе, чем о пятнадцати, при том же тексте и без
 * единого отказа. Потребитель, отладивший на малом образце, встретил бы беду на
 * большом - и связать её с числом детей не смог бы
 *
 * @note Сам порог подменою НЕ стережётся, и это законно: сдвиг его на единицу лишь
 *       переносит границу дорог, а итог у обеих один. Замерено перебором постоянных -
 *       из семнадцати сдвиг шестнадцати красил проверки, а этот единственный проходил
 *       молча. Дырою было не отсутствие проверки на порог, а отсутствие проверки на
 *       согласие дорог - вывод этот пришёл от Геннадия, замерившего то же у ABC
 *
 * @note Сличать надо ТОЖДЕСТВО: узел, взятый по имени, обязан быть тем же самым, что
 *       взят по месту, а не просто пригодным. Сличение одной лишь пригодности
 *       прошло бы у указателя, ведущего к соседу
 */
TEST(CodecContract, LookupAgreesOnBothSidesOfTheIndexThreshold) {
	/**
	 * Выполняем перебор чисел детей по обе стороны порога указателя
	 *
	 * @note Числа взяты вокруг порога вплотную: 15 и 16 лежат по разные его стороны,
	 *       а 40 уводит заведомо за него. Проверь мы одно лишь большое число - и
	 *       расхождение у самой границы осталось бы невидимым
	 */
	for(const size_t count : {static_cast <size_t> (8), static_cast <size_t> (15), static_cast <size_t> (16), static_cast <size_t> (17), static_cast <size_t> (40)}){
		/**
		 * Выполняем закрепление согласия дорог у дерева разметки
		 */
		{
			// Собираемый текст разметки
			string text("<root>");
			/**
			 * Выполняем сборку узлов разметки заданным числом
			 */
			for(size_t i = 0; i < count; i++)
				// Выполняем добавление очередного узла разметки
				text.append("<узел").append(std::to_string(i)).append(">").append(std::to_string(i)).append("</узел").append(std::to_string(i)).append(">");
			// Завершаем собираемый текст разметки
			text.append("</root>");
			// Объект дерева разметки
			xml::document_t doc(::logger());
			// Выполняем разбор текста разметки
			ASSERT_TRUE(doc.parse(text)) << count;
			/**
			 * Выполняем перебор всех собранных узлов разметки
			 */
			for(size_t i = 0; i < count; i++){
				// Собираемое имя очередного узла разметки
				const string name = ("узел" + std::to_string(i));
				// Выполняем проверку достижимости узла обходом по имени
				ASSERT_TRUE(doc.has("/root/" + name)) << count << "/" << i;
				/**
				 * Выполняем проверку ТОЖДЕСТВА содержимого, взятого по имени
				 *
				 * @note Указатель, ведущий к соседу, отвечал бы пригодностью исправно,
				 *       и одна лишь достижимость его не вскрыла бы
				 */
				ASSERT_EQ(doc.at("/root/" + name).text(), std::to_string(i)) << count << "/" << i;
			}
			// Владеющее значение, снятое с корневого узла разметки
			const xml::value_t value(doc.element());
			/**
			 * Выполняем перебор всех собранных узлов у владеющего значения
			 *
			 * @note Сторона эта отдельная: у значения свой указатель и свой порог,
			 *       и согласие дорог у дерева его не доказывает
			 */
			for(size_t i = 0; i < count; i++){
				// Собираемое имя очередного узла разметки
				const string name = ("узел" + std::to_string(i));
				// Выполняем проверку признания имени владеющим значением
				ASSERT_TRUE(value.contains(name)) << count << "/" << i;
			}
			// Выполняем проверку того, что необъявленное имя не признаётся
			ASSERT_FALSE(value.contains("нет-такого")) << count;
		}
		/**
		 * Выполняем закрепление согласия дорог у документа
		 */
		{
			// Собираемый текст документа
			string text("{");
			/**
			 * Выполняем сборку полей документа заданным числом
			 */
			for(size_t i = 0; i < count; i++){
				// Добавляем разделитель полей документа
				if(i > 0)
					// Устанавливаем разделитель полей документа
					text.append(1, ',');
				// Добавляем очередное поле документа
				text.append("\"поле").append(std::to_string(i)).append("\":").append(std::to_string(i));
			}
			// Завершаем собираемый текст документа
			text.append(1, '}');
			// Объект документа
			json::document_t doc(::logger());
			// Выполняем разбор текста документа
			ASSERT_TRUE(doc.parse(text)) << count;
			/**
			 * Выполняем перебор всех собранных полей документа
			 */
			for(size_t i = 0; i < count; i++){
				// Извлекаемое значение поля документа
				int64_t number = -1;
				// Выполняем извлечение значения поля по его имени
				ASSERT_TRUE(doc.at("/поле" + std::to_string(i)).value(number)) << count << "/" << i;
				// Выполняем проверку тождества извлечённого значения
				ASSERT_EQ(number, static_cast <int64_t> (i)) << count << "/" << i;
			}
			// Выполняем проверку того, что необъявленное имя не достигается
			ASSERT_FALSE(doc.has("/нет-такого")) << count;
		}
	}
}
